window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0226", [{"word":"regardless","ipa_uk":"/rɪˈɡɑːdləs/","ipa_us":"/rɪˈɡɑːrdləs/","definition_zh":"不管，不顾；无论如何；无论（常与介词连用，引出被忽略的因素）","definition_en":"without being affected by something; in any case, no matter what","core_image":"一个人顶着斜风把伞收进包里，抬头只看路，不看天色","scene":"雨点砸在站台上，列车员照旧挥旗放行。The conductor waved the train through regardless of the storm.","sceneCN":"这里取「不顾、不论」（第 2 个义项：后接名词，指出该因素不影响行动）；句意为列车员不顾暴雨照样放行。","pos":[{"tag":"adv.","zh":"副词：无论如何、照样"},{"tag":"prep. phr.","zh":"介词短语：不顾、不论"}],"collocations":[{"phrase":"regardless of cost","zh":"不论成本"},{"phrase":"regardless of age","zh":"不论年龄"},{"phrase":"regardless of the outcome","zh":"不论结果如何"},{"phrase":"regardless of whether","zh":"不论是否"},{"phrase":"carry on regardless","zh":"照样继续"},{"phrase":"regardless of the consequences","zh":"不顾后果"}],"forms":[{"label":"原形","form":"regardless"},{"label":"介词短语","form":"regardless of"},{"label":"从句引导","form":"regardless of whether"},{"label":"事实从句","form":"regardless of the fact that"}],"derivatives":[{"word":"regard","pos":"n./v.","zh":"注视；看待"},{"word":"regarding","pos":"prep.","zh":"关于"},{"word":"disregard","pos":"v./n.","zh":"漠视；不理会"},{"word":"regardless of","pos":"prep. phr.","zh":"不顾；不论"},{"word":"irrespective of","pos":"prep. phr.","zh":"不论（正式同义说法）"}],"senses":[{"no":"01","title":"In any case, at the end of a clause","titleCN":"句末状语：无论如何、照样","definition":"used at the end of a statement to say that something still happens after what was just mentioned","definitionCN":"放在陈述末尾，表示尽管前面提到的情况，某事仍然发生","example":"The forecast was poor, but they set off regardless.","exampleCN":"预报很差，他们还是照样出发了。","why":"The -less suffix removes regard, so the adverb marks an act performed without looking at the obstacle just named.","whyCN":"否定后缀去掉了「顾及」，因此这个副词标出不看眼前阻碍、照旧进行的动作。"},{"no":"02","title":"Ignoring a named factor","titleCN":"后接名词：不顾、不论某因素","definition":"used before a noun to say that the named factor has no influence on the result","definitionCN":"用在名词前，表示所提到的事物对结果没有影响","example":"The rule applies to everyone regardless of age.","exampleCN":"这条规则适用于所有人，不论年龄。","why":"Here of carries the thing that is deliberately set aside, which is why a noun follows it and not a clause.","whyCN":"此处介词引出被有意搁置的对象，所以它后面接名词而不是从句。"},{"no":"03","title":"Ignoring an open question","titleCN":"后接疑问从句：不论是否、不论怎样","definition":"used before a clause with whether, what or how to mean that no possible answer changes the outcome","definitionCN":"用在是否、什么、怎样引导的从句前，表示任何答案都不改变结果","example":"The hall stays open regardless of whether it rains.","exampleCN":"不论下不下雨，大厅都开放。","why":"An open question is still a factor to be set aside, so the same of-phrase takes a clause instead of a noun.","whyCN":"尚未确定的疑问同样属于被搁置的因素，于是同一个介词短语改接从句而非名词。"},{"no":"04","title":"A spoken turn-back marker","titleCN":"句首转折：尽管如此、反正","definition":"used at the beginning of a sentence in speech to brush aside the previous objection and continue","definitionCN":"在口语中置于句首，把先前的反对意见撇开，继续往下说","example":"Regardless, the deadline does not move.","exampleCN":"反正截止日期不会往后挪。","why":"Standing alone at the front, the word stops being a comment on a noun phrase and becomes a signal that the speaker is moving on.","whyCN":"单独站在句首时，这个词不再修饰某个名词短语，而变成说话人「继续往下讲」的信号。"},{"no":"05","title":"Conceding a stated fact","titleCN":"后接事实从句：尽管事实如此","definition":"used before the fact that to admit a fact while denying that it changes anything","definitionCN":"用在「事实是……」之前，承认某一事实，同时否认它会带来改变","example":"Regardless of the fact that funding fell, the survey was finished.","exampleCN":"尽管经费减少，调查还是完成了。","why":"The fact that frame makes the concession explicit, so the sentence sounds more formal than a bare noun phrase.","whyCN":"「事实是」这一框架把让步说得很明白，因此整句比光秃秃的名词短语更正式。"},{"no":"06","title":"A blunt one-word dismissal","titleCN":"单独成句：管它呢、反正","definition":"used alone as a short reply showing that the speaker will not change course","definitionCN":"单独成句作答，表示说话人不会改变做法","example":"Regardless — we leave at dawn.","exampleCN":"管它呢，我们天亮就走。","why":"A whole turn reduced to one word signals impatience; the omitted clause is understood from the exchange before it.","whyCN":"整句话压缩成一个词，透出不耐；省略的部分由前面的对话补足。"},{"no":"07","title":"The everyday twin of a formal phrase","titleCN":"日常语域：正式说法的通用替代","definition":"in general and business writing it replaces the more formal irrespective of without any change of meaning","definitionCN":"在一般与商务文字中替代更正式的「不论」说法，意义不变","example":"The refund policy is the same regardless of the payment method.","exampleCN":"不论用哪种付款方式，退款政策都一样。","why":"English keeps two near-identical phrases mainly by register: this one is neutral and common, its twin is formal and technical.","whyCN":"英语保留两个几乎同义的短语，主要靠语域分工：这一说法中性常用，另一说法正式偏技术。"},{"no":"08","title":"The old adjective of heedlessness","titleCN":"旧义形容词：不加留意的","definition":"in older literary use, an adjective meaning paying no attention to what is around","definitionCN":"在较早的文学用法中作形容词，意为对周围事物不加留意","example":"The old texts describe a regardless rider who never looked back.","exampleCN":"旧时的文本写到一位从不回头的骑手，全然不顾身后。","why":"Before the adverb took over, the adjective described a person's habit of not looking, and that sense survives only in literary style.","whyCN":"在副词用法占据主流之前，这个形容词描述一个人「不看」的习惯，该义项如今只留在文学文体里。"}],"etymology":{"intro":{"en":"Contrast reached English through French and Italian from a Vulgar Latin verb built on Latin contra, against, and stare, to stand. The Latin line is secure, but the date of the English phrase is approximate.","cn":"regardless 由 regard 加本族后缀 -less 构成。regard 经古法语 regarder「看」进入英语，其词干可追到日耳曼语护卫词族，但那个法兰克语原形只是重构，来源不确定。这里没有拉丁语成分。"},"items":[{"era":"OLD FRENCH REGARDER","en":"Regard comes from Old French regarder, to look at, formed from re-, back, and garder, to watch.","cn":"regard 来自古法语 regarder「看」，由 re-「向后」与 garder「看守」构成。"},{"era":"FRANKISH FORM (SOURCE UNCERTAIN)","en":"The French verb garder belongs to the Germanic guard family. The exact Frankish shape is a reconstruction, so the ultimate source is uncertain.","cn":"法语动词 garder 属日耳曼语「护卫」词族。确切的法兰克语形式属重构，因此最终来源不确定。"},{"era":"ENGLISH REGARD","en":"English took regard in the fourteenth century for a look or attention; the fixed phrase with regard to still keeps that sense.","cn":"英语在十四世纪借入 regard，表「看、留意」；固定短语「关于」至今保留此义。"},{"era":"NATIVE -LESS","en":"The native suffix -less, meaning without, turned regard into regardless, literally without looking.","cn":"本族后缀 -less 意为「无」，把 regard 变成 regardless，字面就是「不看」。"},{"era":"MODERN ADVERB","en":"The adverb and the pattern regardless of settle in the nineteenth century; exact first dates are approximate.","cn":"副词用法与「不顾」这一介词搭配在十九世纪定型，确切首见年代为约数。"},{"era":"REGISTER SPLIT","en":"Modern usage keeps this form neutral and common, while its formal twin belongs to contracts and technical reports.","cn":"现代用法让这一形式保持中性常用，其正式双胞胎则留在合同与技术报告里。"}]},"similar":{"note":{"en":"The first group shares the same slot before a noun but belongs to other families; the second group holds adverbs and connectors with a similar dismissive force.","cn":"第一组同样放在名词前，却属别的词族；第二组是语气相近的副词与连接语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"irrespective of","ipa":"/ɪrɪˈspektɪv əv/","tag":"formal twin, other family","definition":"The formal equivalent; it belongs to the respect family, not to regard.","definitionCN":"正式同义说法；属「看」的另一词族，与「看」的词根无关。"},{"word":"notwithstanding","ipa":"/ˌnɒtwɪθˈstændɪŋ/","tag":"concessive preposition","definition":"A formal preposition meaning in spite of, common in legal and official writing.","definitionCN":"正式介词，意为尽管，多用于法律与公文。"},{"word":"as regards","ipa":"/æz rɪˈɡɑːdz/","tag":"about, not ignoring","definition":"It introduces a topic; it does not set an obstacle aside.","definitionCN":"它引出话题，并不排除某种阻碍。"},{"word":"in spite of","ipa":"/ɪn ˈspaɪt əv/","tag":"concedes a fact","definition":"It admits that a fact exists; regardless of denies that the fact has any weight.","definitionCN":"它承认事实存在；而「不顾」否认该事实有分量。"}]},{"heading":"NEAR MEANING","entries":[{"word":"anyway","ipa":"/ˈenɪweɪ/","tag":"plain spoken equivalent","definition":"In spite of what has been said; the everyday adverb in conversation.","definitionCN":"尽管如此；口语中最平常的对应副词。"},{"word":"nevertheless","ipa":"/ˌnevəˈðeles/","tag":"formal connector","definition":"A written connector meaning in spite of that.","definitionCN":"书面连接词，意为尽管如此。"},{"word":"even so","ipa":"/ˈiːvn səʊ/","tag":"conversational turn","definition":"It concedes the previous point and then continues.","definitionCN":"先承认上一点，再继续往下说。"},{"word":"no matter","ipa":"/nəʊ ˈmætə/","tag":"open factor","definition":"It introduces any value of a factor that leaves the result unchanged.","definitionCN":"引出任一不影响结果的取值。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real suffix, the real family and the real grammar of the phrase.","cn":"正常联想用真实后缀、真实词族与真实语法。"},"normal":[{"en":"-less means without, so the word literally says not looking.","cn":"后缀意为「无」，这个词字面上就是「不看」。"},{"en":"Before a noun it needs of; before a question it takes whether.","cn":"接名词要带相应介词，接疑问要带是否从句。"},{"en":"At the end of a clause it means anyway; at the front it means speaking of which, moving on.","cn":"放句末等于「照样」，放句首等于「话说回来，继续」。"},{"en":"Its formal twin lives in contracts and technical reports.","cn":"它的正式双胞胎住在合同与技术报告里。"},{"en":"Regard is looking, disregard is not looking, regardless is not caring to look.","cn":"词根是「看」，反向词是「不看」，本词是「不屑于看」。"}],"abstract":[{"en":"Like a person walking with eyes fixed ahead while the wind throws rain sideways.","cn":"像一个人眼睛只盯前方，任凭斜雨打在身上。"},{"en":"Like a train that keeps its timetable while the platform empties.","cn":"像列车照旧按时刻表发车，站台却已空无一人。"},{"en":"Like a sentence that drops the word but and keeps walking.","cn":"像一句话扔掉了「但是」，却继续往前走。"}]},"examples":[{"en":"The policy applies to all applicants regardless of nationality.","cn":"这项政策适用于所有申请人，不论国籍。"},{"en":"She kept working regardless of the noise around her.","cn":"她不顾周围的喧闹，继续工作。"},{"en":"The old rule stands regardless of how often it is questioned.","cn":"这条旧规不论被质疑多少次，依然有效。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「瑞加德勒斯」——灯再亮也不抬头看：不管、不顾","word":"regardless"},"root":"regard 经古法语 regarder「看」进入英语，词干 garder 属日耳曼语护卫词族，其法兰克语原形为重构形式，来源不确定；本族后缀 -less 表「无」。合起来即「不看、不顾」。首见年代为约数。","sensesIntro":{"en":"Eight senses split by position and complement: a clause-final anyway, a noun after of, a clause after of, a sentence-initial turn, a fact clause, a one-word reply, a register twin, and the old adjective.","cn":"八个义项按位置与搭配分开：句末的「照样」、接名词的「不顾」、接从句的「不论」、句首的转折、事实从句、单词作答、语域替代，以及旧形容词义。"},"semanticMap":{"core":{"en":"CORE IMAGE: a person with an umbrella closed, eyes on the road, rain ignored.","cn":"核心意象：一个人收起伞，眼睛只看路，把雨置之不理。"},"chain":["NOT LOOKING","IGNORED FACTOR","OPEN CLAUSE","ANY CASE","SPOKEN TURN","OLD ADJECTIVE"],"branches":[{"senses":"01","en":"THE WITHHELD GAZE: the act goes on without a look at the obstacle.","cn":"不看的目光：行动继续，却不看阻碍。"},{"senses":"02 · 07","en":"THE IGNORED FACTOR: a noun is named only to be set aside, in neutral or formal register.","cn":"被搁置的因素：点出名词只为把它放到一边，语域可中性也可正式。"},{"senses":"03 · 05","en":"THE OPEN CLAUSE: whether and the fact that extend the same move to whole clauses.","cn":"开放的从句：是否引导词与「事实是」把同一动作扩展到整句。"},{"senses":"04 · 06","en":"THE SPOKEN TURN: at the front or alone, the word becomes a signal to continue.","cn":"口语转折：放句首或单独成句，词就成了「继续」的信号。"},{"senses":"08","en":"THE OLD ADJECTIVE: an earlier sense described the habit of never looking back.","cn":"旧形容词：更早的义项描述从不回头的习惯。"}]},"affixes":{"intro":{"en":"The word is a native suffix added to a French verb with a Germanic core; no Latin element is present.","cn":"这个词是本族后缀加在一个带日耳曼语核心的法语动词上；没有拉丁语成分。"},"latinIntro":{"en":"No Latin etymon is involved: regard is French, its stem is Germanic, and the suffix is native English.","cn":"这里不涉及拉丁语词根：regard 是法语词，词干属日耳曼语，后缀是英语本族成分。"},"items":[{"word":"regard","structure":"Old French regarder (verb)","meaning":"to look at; attention","meaningCN":"看；留意","example":"The nurse regarded the wound for a long moment.","exampleCN":"护士仔细看了伤口好一会儿。"},{"word":"garder","structure":"Old French verb, Germanic stem","meaning":"to watch, keep","meaningCN":"看守；保管","example":"The stem survives in the guard family of words.","exampleCN":"这个词干仍留在「护卫」一族词里。"},{"word":"-less","structure":"native English suffix","meaning":"without","meaningCN":"无；缺少","example":"The suffix turns a noun of attention into a word of neglect.","exampleCN":"后缀把「留意」之名变成「不顾」之词。"},{"word":"regardless","structure":"regard + -less (adjective)","meaning":"heedless; paying no attention","meaningCN":"不留意的；不顾的","example":"The old adjective sense survives in literary prose.","exampleCN":"旧的形容词义仍留在文学散文里。"},{"word":"disregard","structure":"dis- + regard (verb)","meaning":"to ignore deliberately","meaningCN":"故意无视","example":"The clerk disregarded the warning on the form.","exampleCN":"办事员无视表格上的警告。"},{"word":"regarding","structure":"regard + -ing (preposition)","meaning":"concerning","meaningCN":"关于","example":"A letter regarding the contract arrived today.","exampleCN":"一封关于合同的信今天到了。"},{"word":"regardless of","structure":"fixed prepositional phrase","meaning":"without regard to","meaningCN":"不顾；不论","example":"The phrase takes a noun or a question clause after of.","exampleCN":"这一短语在介词后接名词或疑问从句。"},{"word":"irrespective of","structure":"formal parallel phrase","meaning":"without respect to","meaningCN":"不论（正式）","example":"The formal phrase belongs to a different family and register.","exampleCN":"这个正式短语属另一词族，语域也不同。"}],"latinEntries":[],"derivatives":[{"word":"regard","pos":"n./v.","zh":"注视；看待"},{"word":"regarding","pos":"prep.","zh":"关于"},{"word":"disregard","pos":"v./n.","zh":"漠视；不理会"},{"word":"regardless of","pos":"prep. phr.","zh":"不顾；不论"},{"word":"irrespective of","pos":"prep. phr.","zh":"不论（正式同义说法）"}]}},{"word":"irrespective of","ipa_uk":"/ɪrɪˈspektɪv əv/","ipa_us":"/ɪrɪˈspektɪv əv/","definition_zh":"不论，不考虑，不受……影响（比日常同义说法更正式，多用于法律、技术与学术文本）","definition_en":"without being affected or limited by a particular factor; a formal equivalent of regardless of","core_image":"一份合同压在两叠厚薄悬殊的账本上，印章对两叠一视同仁","scene":"审计员翻看两叠厚薄不一的账本，表示抽查范围不看账本大小。The auditor applied the same check to every ledger, irrespective of its size.","sceneCN":"这里取「不受……影响」（第 2 个义项：后接名词，属正式语域）；句意为审计员对所有账本施加同样的检查，不论其厚薄。","pos":[{"tag":"prep. phr.","zh":"介词短语：不论、不受……影响（正式）"},{"tag":"adv. phr.","zh":"状语用法：不论……都……"}],"collocations":[{"phrase":"irrespective of age","zh":"不论年龄"},{"phrase":"irrespective of cost","zh":"不论成本"},{"phrase":"irrespective of nationality","zh":"不论国籍"},{"phrase":"irrespective of the outcome","zh":"不论结果"},{"phrase":"irrespective of whether","zh":"不论是否"},{"phrase":"irrespective of any other provision","zh":"不受任何其他条款限制"}],"forms":[{"label":"原形","form":"irrespective of"},{"label":"从句引导","form":"irrespective of whether"},{"label":"事实从句","form":"irrespective of the fact that"},{"label":"后置用法","form":"applies irrespective of"}],"derivatives":[{"word":"respect","pos":"n./v.","zh":"尊重；方面"},{"word":"respective","pos":"adj.","zh":"各自的"},{"word":"respectively","pos":"adv.","zh":"分别地"},{"word":"irrespective","pos":"adj.","zh":"不顾的（罕用形容词）"},{"word":"irrespective of","pos":"prep. phr.","zh":"不论（正式）"}],"senses":[{"no":"01","title":"Front-position concession in formal prose","titleCN":"句首状语：不论……都……（正式书面）","definition":"placed at the start of a formal sentence to say that the outcome is unchanged by the named factor","definitionCN":"置于正式句子的开头，表示所述因素不改变结果","example":"Irrespective of the outcome, the procedure must be recorded.","exampleCN":"不论结果如何，程序都必须记录在案。","why":"Fronting the phrase turns it into a frame for the whole sentence, a habit borrowed from legal and scientific drafting.","whyCN":"把这个短语提到句首，它就成了统摄全句的框架，这是法律与科学写作的习惯。"},{"no":"02","title":"A noun that carries no weight","titleCN":"后接名词：不受……影响","definition":"used before a noun phrase to state that the factor does not affect the decision","definitionCN":"用在名词短语前，说明该因素不影响决定","example":"The fee is fixed irrespective of income.","exampleCN":"费用是固定的，不受收入影响。","why":"Of introduces the factor being neutralized; because the phrase is formal, it prefers abstract nouns such as income or rank.","whyCN":"介词引出被中和的因素；由于语域正式，它更偏爱收入、级别这类抽象名词。"},{"no":"03","title":"An open yes-or-no condition","titleCN":"后接是否从句：不论是否","definition":"used before a whether clause to cover both possible answers at once","definitionCN":"用在是否从句前，把两种可能一并覆盖","example":"The policy holds irrespective of whether the applicant is resident.","exampleCN":"不论申请人是否本地居民，政策都一样。","why":"Whether presents two branches, and the phrase declares that neither branch changes the rule.","whyCN":"是否从句摆出两条分支，而这个短语宣称两条都不改变规则。"},{"no":"04","title":"An open wh-question","titleCN":"后接疑问从句：不论怎样、不论什么","definition":"used before a clause with how, what or who to cancel every possible value","definitionCN":"用在怎样、什么、谁引导的从句前，抵消一切可能取值","example":"The sample was treated alike irrespective of how it had been stored.","exampleCN":"不论样品此前如何存放，处理方式都相同。","why":"A wh-clause supplies a range of values, and the phrase says the same treatment applies across the whole range.","whyCN":"疑问从句给出一个取值范围，这个短语表示整个范围都适用同一处理。"},{"no":"05","title":"A trailing qualifier after the verb","titleCN":"句末后置：一概适用","definition":"placed at the end of a clause after the verb to add a condition that does not restrict the rule","definitionCN":"置于从句末尾、动词之后，补充一个并不限制规则的条件","example":"The safety rule applies to all staff, irrespective of rank.","exampleCN":"安全规则适用于全体员工，不论级别。","why":"In final position the phrase reads as an afterthought that widens the rule rather than narrowing it.","whyCN":"放在句末时，这个短语像是补一句，把规则的范围放宽而不是收窄。"},{"no":"06","title":"Admitting a fact in formal style","titleCN":"后接事实从句：尽管","definition":"used before the fact that to grant a fact while denying its effect","definitionCN":"用在「事实是」之前，承认事实但否认其作用","example":"Irrespective of the fact that funding fell, the team completed the survey.","exampleCN":"尽管经费减少，团队仍完成了调查。","why":"The fact that clause is the formal route for a full statement, because the bare phrase cannot take a clause on its own.","whyCN":"「事实是」从句是表达完整命题的正式通道，因为光秃秃的短语本身不能直接接从句。"},{"no":"07","title":"Contract language that overrides other terms","titleCN":"合同用语：不受其他条款限制","definition":"in legal drafting, used to deny that any other provision can limit the clause","definitionCN":"在法律起草中，用来否认任何其他条款能限制本条","example":"Irrespective of any other provision, notice must be given in writing.","exampleCN":"不受任何其他条款限制，通知必须以书面形式发出。","why":"Contracts need a phrase that switches off competing clauses, and this one does that without naming them.","whyCN":"合同需要一个能关掉竞争条款的说法，这个短语不必点名就做到了。"},{"no":"08","title":"Statistical independence from a variable","titleCN":"科研统计：不随……改变、独立于","definition":"in research writing, used to say that a trend or result does not vary with a measured variable","definitionCN":"在科研写作中，表示某个趋势或结果不随被测变量而变化","example":"The trend was stable irrespective of sample size.","exampleCN":"这一趋势不随样本量改变而改变。","why":"Technical writing uses the phrase where a statistician would say independent of, because it marks a variable that was checked and found irrelevant.","whyCN":"技术写作在此用这个短语，相当于统计学家说的「独立于」，因为它标出一个已被检验、判定无关的变量。"}],"etymology":{"intro":{"en":"Irrespective joins the negative prefix ir- to respective, from Latin respectus, a looking back, built on respicere, re- back plus specere, to look. The Latin line is certain; the English phrase is modern.","cn":"irrespective 由否定前缀 ir- 加 respective 构成；respective 出自拉丁语 respectus「回望」，词根 respicere 为 re-「回」加 specere「看」。拉丁语线索确定，英语短语属近代。"},"items":[{"era":"LATIN SPECERE","en":"Specere, to look, is the root of respect, spectacle and specimen.","cn":"specere 意为「看」，是 respect、spectacle、specimen 的共同词根。"},{"era":"LATIN RESPICERE","en":"Respicere meant to look back at or take notice of, hence to have regard for.","cn":"respicere 意为「回看、注意到」，由此引申为「顾及」。"},{"era":"LATIN RESPECTUS","en":"The noun respectus named a looking back and, later, regard or esteem.","cn":"名词 respectus 本指回望，后来指顾及与尊敬。"},{"era":"IR- NEGATION","en":"The assimilated negative prefix ir- reverses the looking, giving the sense of not looking at a factor.","cn":"同化的否定前缀 ir- 把「看」反过来，产生「不看某因素」之义。"},{"era":"ENGLISH PHRASE","en":"The phrase irrespective of appears in formal nineteenth-century prose; dates are approximate.","cn":"短语 irrespective of 在十九世纪的正式散文里出现，年代为约数。"}]},"similar":{"note":{"en":"The first group shares the same slot and register but comes from other roots; the second group holds formal ways of expressing concession or exemption.","cn":"第一组同样占名词前的正式位置，却来自别的词根；第二组是表达让步或豁免的正式说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"regardless of","ipa":"/rɪˈɡɑːdləs əv/","tag":"neutral twin, other family","definition":"The everyday equivalent; it belongs to the regard family and sounds less technical.","definitionCN":"日常同义说法；属「看」的词族，听起来不那么技术化。"},{"word":"in respect of","ipa":"/ɪn rɪˈspekt əv/","tag":"legal about-phrase","definition":"A British legal phrase meaning concerning or as regards, not a negation of the factor.","definitionCN":"英式法律短语，意为「关于」，并非否定某因素。"},{"word":"with respect to","ipa":"/wɪð rɪˈspekt tuː/","tag":"topic marker","definition":"It narrows the topic of a statement rather than cancelling a condition.","definitionCN":"它限定陈述的话题，而不是取消某个条件。"},{"word":"notwithstanding","ipa":"/ˌnɒtwɪθˈstændɪŋ/","tag":"concessive preposition","definition":"It concedes a fact and still asserts the main clause.","definitionCN":"它承认事实，同时仍主张主句内容。"}]},{"heading":"NEAR MEANING","entries":[{"word":"without regard to","ipa":"/wɪˈðaʊt rɪˈɡɑːd tuː/","tag":"plain paraphrase","definition":"A transparent phrase with the same force, common outside technical writing.","definitionCN":"意思透明的同义说法，在技术文本之外常用。"},{"word":"independent of","ipa":"/ˌɪndɪˈpendənt əv/","tag":"statistical paraphrase","definition":"The usual research phrasing when a measured variable does not affect the result.","definitionCN":"研究写作中的常用说法，指被测变量不影响结果。"},{"word":"no matter","ipa":"/nəʊ ˈmætə/","tag":"spoken frame","definition":"It sets up an irrelevant factor in conversation.","definitionCN":"在口语中引出一个无关因素。"},{"word":"whatever","ipa":"/wɒtˈevə/","tag":"single-word frame","definition":"It compresses an open range into one word before a noun.","definitionCN":"在名词前用一个词压缩整个取值范围。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Latin root, the real negation and the real register.","cn":"正常联想用真实拉丁词根、真实否定前缀与真实语域。"},"normal":[{"en":"Specere is to look, so respect is a looking back, and the negative form is not looking at the factor.","cn":"拉丁词根意为「看」，回看即顾及，否定形式就是不看那个因素。"},{"en":"Ir- is the same negative prefix seen in irregular and irrelevant.","cn":"这个否定前缀与另外两个否定词相同。"},{"en":"It takes a noun or a whether clause, never a bare that clause.","cn":"它接名词或是否从句，从不直接接陈述从句。"},{"en":"Position matters: fronting frames the whole sentence, trailing position widens the rule.","cn":"位置有讲究：提前统摄全句，后置放宽规则。"},{"en":"Its neutral twin is the one people actually say at lunch.","cn":"它中性的双胞胎才是人们午饭时真会说的那个。"}],"abstract":[{"en":"Like a single lamp switched on over two piles of papers of very different height.","cn":"像一盏灯同时照亮两叠厚薄悬殊的文件。"},{"en":"Like a measuring rod that ignores the weight of what it measures.","cn":"像一把尺子，不管所称之物有多重。"},{"en":"Like a door that opens for every name on the list, with no line drawn through any of them.","cn":"像一扇门为名单上每个名字打开，没有一个被划掉。"}]},"examples":[{"en":"The same standard was applied to all suppliers irrespective of their size.","cn":"对所有供应商都采用同一标准，不论其规模。"},{"en":"Irrespective of how the data were collected, the conclusion held.","cn":"不论数据是如何收集的，结论都成立。"},{"en":"The clause operates irrespective of any later agreement between the parties.","cn":"该条款不受双方之后任何协议的影响。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「伊瑞斯佩克提夫 奥夫」——名单上一个也不划掉：不论、不受影响","word":"irrespective of"},"root":"irrespective 由否定前缀 ir- 加 respective 构成；respective 出自拉丁语 respectus「回望」，词根 respicere 为 re-「回」加 specere「看」。因此本词字面是「不看某因素」，即「不论」。英语短语首见年代为约数。","sensesIntro":{"en":"Eight senses differ by position, complement and register: front and trailing placement, noun and whether and wh clauses, a fact clause, contract override, and statistical independence.","cn":"八个义项按位置、搭配与语域区分：句首与句末、名词与是否及疑问从句、事实从句、合同凌驾条款、统计独立。"},"semanticMap":{"core":{"en":"CORE IMAGE: one seal pressed onto two ledgers of very different thickness.","cn":"核心意象：同一枚印章盖在两叠厚薄悬殊的账本上。"},"chain":["NOT LOOKING","NEUTRAL FACTOR","OPEN WH","TRAILING QUALIFIER","CONTRACT OVERRIDE","STATISTICAL INDEPENDENCE"],"branches":[{"senses":"01","en":"THE FRAME: at the front, the phrase governs the whole sentence.","cn":"框架：置于句首时统摄全句。"},{"senses":"02 · 08","en":"THE NEUTRAL FACTOR: a noun is cancelled, whether in a fee rule or in a research variable.","cn":"被中和的因素：无论在收费规则还是研究变量中，名词都被取消。"},{"senses":"03 · 04","en":"THE OPEN CLAUSE: whether and wh questions extend the cancellation to every branch.","cn":"开放从句：是否引导词与疑问词把取消扩展到每条分支。"},{"senses":"05 · 06","en":"THE TRAILING AND THE FACT: a final qualifier widens the rule, a fact clause concedes openly.","cn":"后置与事实：句末限定放宽规则，事实从句公开让步。"},{"senses":"07","en":"THE OVERRIDE: in contracts the phrase switches off competing clauses.","cn":"凌驾：合同里这个短语关掉竞争条款。"}]},"affixes":{"intro":{"en":"The word is a negative prefix, a Latin verb of looking and a native preposition; the Latin core is clear.","cn":"这个词由否定前缀、拉丁语「看」的动词与英语介词组成；拉丁核心清楚。"},"latinIntro":{"en":"The Latin etymon is respicere, to look back, whose root specere also gives spectacle and specimen.","cn":"拉丁语词源是 respicere「回看」，其词根 specere 也给出 spectacle 与 specimen。"},"items":[{"word":"specere","structure":"Latin verb","meaning":"to look","meaningCN":"看","example":"The root appears across the spect- family.","exampleCN":"这个词根贯穿整个「看」的词族。"},{"word":"respicere","structure":"Latin verb, re- + specere","meaning":"to look back; to regard","meaningCN":"回看；顾及","example":"To regard a person was first to look back at him.","exampleCN":"「顾及」一个人，最初就是回头看他。"},{"word":"respectus","structure":"Latin noun from respicere","meaning":"a looking back; regard","meaningCN":"回望；顾及","example":"The noun supplies the base of the English adjective.","exampleCN":"这个名词提供了英语形容词的基词。"},{"word":"ir-","structure":"assimilated negative prefix","meaning":"not","meaningCN":"不","example":"The prefix reverses the act of looking.","exampleCN":"前缀把「看」这一动作反过来。"},{"word":"respective","structure":"English adjective from respectus","meaning":"relating separately to each","meaningCN":"各自的","example":"The adjective first meant looked at one by one.","exampleCN":"这个形容词原指逐个看待的。"},{"word":"irrespective","structure":"ir- + respective","meaning":"not looking at; without regard","meaningCN":"不看的；不顾的","example":"The adjective sense survives though the phrase dominates.","exampleCN":"形容词义仍在，但短语用法更常见。"},{"word":"irrespective of","structure":"fixed prepositional phrase","meaning":"without regard to","meaningCN":"不论；不受影响","example":"The phrase is the normal formal use of the word.","exampleCN":"这个短语是该词正常的正式用法。"},{"word":"regardless of","structure":"neutral parallel phrase","meaning":"in spite of; without regard to","meaningCN":"不顾；不论","example":"The neutral phrase comes from a different family.","exampleCN":"中性短语来自另一词族。"}],"latinEntries":[{"word":"respicere","structure":"respicere, respicio, respexi, respectum (verb, third conjugation)","meaning":"to look back at; to regard","meaningCN":"回看；顾及"},{"word":"specere","structure":"specere, specio, spexi, spectum (verb)","meaning":"to look","meaningCN":"看"},{"word":"respectus","structure":"respectus, -us (noun, fourth declension)","meaning":"a looking back; regard","meaningCN":"回望；顾及"}],"derivatives":[{"word":"respect","pos":"n./v.","zh":"尊重；方面"},{"word":"respective","pos":"adj.","zh":"各自的"},{"word":"respectively","pos":"adv.","zh":"分别地"},{"word":"irrespective","pos":"adj.","zh":"不顾的（罕用形容词）"},{"word":"irrespective of","pos":"prep. phr.","zh":"不论（正式）"}]}},{"word":"in contrast","ipa_uk":"/ɪn ˈkɒntrɑːst/","ipa_us":"/ɪn ˈkɑːntræst/","definition_zh":"相比之下；与……形成对照（用于指出两者的明显差异）","definition_en":"used to point out a clear difference between two things, facts or situations","core_image":"同一张展台上，左边满杯，右边空杯，两束光颜色相反","scene":"展柜两侧并排放着满杯与空杯，标签说明两者的差别。The first case held a full cup; in contrast, the second case held an empty one.","sceneCN":"这里取「相比之下」（第 1 个义项：句首或分句间的对比标记）；句意为第一个展柜里是满杯，相比之下第二个展柜里是空杯。","pos":[{"tag":"adv. phr.","zh":"状语短语：相比之下"},{"tag":"prep. phr.","zh":"介词短语：与……形成对照"}],"collocations":[{"phrase":"in contrast to","zh":"与……形成对照"},{"phrase":"in contrast with","zh":"与……相比（正式/英式）"},{"phrase":"in contrast, however","zh":"相比之下，然而"},{"phrase":"stand in contrast to","zh":"与……形成鲜明对比"},{"phrase":"in sharp contrast","zh":"形成鲜明对比"},{"phrase":"in contrast to earlier findings","zh":"与早先的发现相反"}],"forms":[{"label":"原形","form":"in contrast"},{"label":"接名词（英式）","form":"in contrast to"},{"label":"接名词（正式变体）","form":"in contrast with"},{"label":"强调式","form":"in sharp contrast"}],"derivatives":[{"word":"contrast","pos":"n./v.","zh":"对比；形成对照"},{"word":"contrastive","pos":"adj.","zh":"对比的；对照的"},{"word":"contrastingly","pos":"adv.","zh":"对比之下（少见）"},{"word":"by contrast","pos":"adv. phr.","zh":"相比之下"},{"word":"contrast with","pos":"v. phr.","zh":"与……形成对比"}],"senses":[{"no":"01","title":"The sentence-opening contrast marker","titleCN":"句首：相比之下","definition":"placed at the beginning of a clause to announce that what follows differs from what came before","definitionCN":"置于从句开头，宣告接下来的内容与前述不同","example":"The coast is humid; in contrast, the interior is dry.","exampleCN":"沿海潮湿；相比之下，内陆干燥。","why":"Fronting the phrase turns the whole clause into the second half of a pair, so the reader expects a mirrored point.","whyCN":"把短语提到句首，整个从句就成了成对句的后半，读者自然期待一个对应的点。"},{"no":"02","title":"The mid-sentence pivot","titleCN":"分句间插入：而……","definition":"inserted between two parallel statements, often with a semicolon or a comma, to mark the turning point","definitionCN":"插在两个平行陈述之间，常用分号或逗号隔开，标出转折点","example":"The first method is cheap; the second, in contrast, is accurate.","exampleCN":"第一种方法便宜；相比之下，第二种精准。","why":"In the middle the phrase pivots the sentence without breaking it, which is why it often sits inside commas.","whyCN":"放在中间，短语完成转折却不打断句子，因此常被逗号夹住。"},{"no":"03","title":"A named reference point","titleCN":"后接介词加名词：与……截然不同","definition":"used before to and a noun to name the thing that the subject differs from","definitionCN":"用在介词加名词之前，点出主语与之不同的事物","example":"In contrast to earlier studies, the new survey found no decline.","exampleCN":"与早先的研究不同，这次调查没有发现下降。","why":"To names the standard of comparison, so the phrase stops being an adverb and becomes a prepositional frame.","whyCN":"这个介词点出比较的基准，于是这个短语不再是副词，而成了介词框架。"},{"no":"04","title":"The formal with variant","titleCN":"后接另一个介词加名词：与……相比（正式/英式）","definition":"used with with instead of to, chiefly in formal British writing, with the same meaning","definitionCN":"用一个介词代替另一个，多见于正式的英式书面语，意义相同","example":"In contrast with the coastal group, the inland group moved less.","exampleCN":"与沿海组相比，内陆组流动更少。","why":"The two prepositions are near-variants; with is the older, more formal partner and to the more common modern one.","whyCN":"两个介词近乎变体；一个更旧更正式，另一个是现代更常见的搭档。"},{"no":"05","title":"The academic counter-evidence signal","titleCN":"学术语篇：引出相反证据","definition":"in research writing, used to introduce a result that opposes the one just reported","definitionCN":"在学术写作中，用来引出与前一条结果相反的结果","example":"The first trial failed; in contrast, the second trial met every target.","exampleCN":"第一次试验失败；相比之下，第二次试验达成了全部目标。","why":"Research prose needs a signal that separates two findings without claiming either is wrong, and this phrase supplies it.","whyCN":"学术写作需要一个把两项发现分开、又不判定谁错的信号，这个短语正好提供。"},{"no":"06","title":"The paragraph-opening turn","titleCN":"段落开头：转入对立面","definition":"at the start of a paragraph or section, used to shift the discussion to the opposite case","definitionCN":"在段落或章节开头使用，把讨论转向相反的情形","example":"In contrast, the following section examines rural households.","exampleCN":"相比之下，下一节考察农村家庭。","why":"At paragraph level the phrase is a signpost, telling the reader that the argument is about to switch sides.","whyCN":"在段落层面，这个短语是路标，告诉读者论证即将换边。"},{"no":"07","title":"The parallel-structure contrast","titleCN":"并列结构：同一句中对照两个事实","definition":"used in a single sentence to balance two opposite facts, often with parallel wording","definitionCN":"在同一句中平衡两个相反事实，措辞常保持平行","example":"Prices rose in the north; in contrast, wages fell in the south.","exampleCN":"北方物价上涨；相比之下，南方工资下降。","why":"Parallel clauses make the contrast measurable, and the phrase marks where the second half begins.","whyCN":"平行从句让对比可衡量，短语则标出后半句的起点。"},{"no":"08","title":"The data-description contrast","titleCN":"图表与数据：与前一组数字对照","definition":"used when reporting figures to set the current number against an earlier or neighbouring one","definitionCN":"报告数字时，把当前数字与先前或相邻数字并置","example":"In contrast, the 2020 figure almost doubled.","exampleCN":"相比之下，2020 年的数字几乎翻了一倍。","why":"Numerical writing uses the phrase to keep two series apart without repeating the whole comparison in words.","whyCN":"数字写作借此把两组数据分开，不必用文字重复整个比较。"}],"etymology":{"intro":{"en":"Contrast came into English through French from Italian contrastare, a Vulgar Latin verb built on Latin contra, against, and stare, to stand. The reconstruction is reliable; the date of the English phrase is approximate.","cn":"contrast 经法语、意大利语进入英语，其动词是通俗拉丁语形式，由拉丁语 contra「反对」与 stare「站立」构成。该重构形式可靠；英语短语的年代为约数。"},"items":[{"era":"LATIN CONTRA","en":"Contra, against, is the same element found in contradiction and contraflow.","cn":"contra 意为「反对」，与 contradiction、contraflow 中的成分相同。"},{"era":"LATIN STARE","en":"Stare, to stand, gives the picture of two things standing face to face.","cn":"stare 意为「站立」，画出两物面对面站立的画面。"},{"era":"VULGAR LATIN CONTRASTARE","en":"The reconstructed verb meant to stand against or withstand.","cn":"重构的动词意为「对立而站、抵抗」。"},{"era":"ITALIAN AND FRENCH","en":"Italian contrastare passed into French as contraster and then into English in the sixteenth century.","cn":"意大利语 contrastare 传入法语作 contraster，十六世纪再进入英语。"},{"era":"ENGLISH PHRASAL USE","en":"The prepositional frame in contrast appears in modern written English; the exact first date is approximate.","cn":"介词框架 in contrast 出现在近代书面英语中，确切首见年代为约数。"}]},"similar":{"note":{"en":"The first group occupies the same contrast slot but names different relations; the second group holds other connectors that also set two facts against each other.","cn":"第一组占同样的对比位置，却指不同的关系；第二组是同样把两件事并置的其他连接语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"in comparison","ipa":"/ɪn kəmˈpærɪsn/","tag":"similarity, not opposition","definition":"It weighs two things on one scale; in contrast stresses that they diverge.","definitionCN":"它把两物放在同一把尺上；本短语强调两者分道扬镳。"},{"word":"by contrast","ipa":"/baɪ ˈkɒntrɑːst/","tag":"same work, different syntax","definition":"It works as a stand-alone connector and rarely takes to or with after it.","definitionCN":"它作独立连接语，很少在后面接介词。"},{"word":"on the contrary","ipa":"/ɒn ðə ˈkɒntrəri/","tag":"denies a negative claim","definition":"It rejects a stated negative and asserts the opposite; it does not simply set two facts side by side.","definitionCN":"它否定一个被说出的否定命题并主张相反面，不只是把两件事并置。"},{"word":"in spite of","ipa":"/ɪn ˈspaɪt əv/","tag":"concession, not comparison","definition":"It concedes an obstacle; it never introduces a second item to compare.","definitionCN":"它承认阻碍，从不引出被比较的第二项。"}]},{"heading":"NEAR MEANING","entries":[{"word":"whereas","ipa":"/ˈweəræz/","tag":"clausal conjunction","definition":"A conjunction joining two clauses that differ, common in formal and legal prose.","definitionCN":"连接两个不同从句的连词，多见于正式与法律文字。"},{"word":"conversely","ipa":"/kənˈvɜːsli/","tag":"inverse relation","definition":"It marks the reverse side of a relation rather than a mere difference.","definitionCN":"它标出关系的反面，而不只是差异。"},{"word":"instead","ipa":"/ɪnˈsted/","tag":"replacement","definition":"It marks what takes the place of something, not a parallel contrast.","definitionCN":"它标出替代物，而非平行对照。"},{"word":"on the other hand","ipa":"/ɒn ði ˈʌðə hænd/","tag":"balanced alternative","definition":"It introduces the second side of an argument in a more conversational tone.","definitionCN":"以更口语的语气引出论点的另一面。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Latin pair, the real prepositions and the real position rules.","cn":"正常联想用真实拉丁语对、真实介词与真实位置规则。"},"normal":[{"en":"Contra is against and stare is to stand, so two things stand facing each other.","cn":"拉丁词根一是「反」，一是「站」，两物便面对面站着。"},{"en":"In contrast to and in contrast with both take a noun, never a clause.","cn":"这个短语的两种介词形式都接名词，从不接从句。"},{"en":"At the front it announces the other side; between clauses it pivots.","cn":"句首宣告另一面，句间完成转折。"},{"en":"Its twin by contrast usually stands alone and avoids to and with.","cn":"它的近义双胞胎通常独立使用，避开介词。"},{"en":"It pairs things; it does not deny what was said, which is the job of on the contrary.","cn":"它把两物配对，并不否定已说的话，那是对立说法的工作。"}],"abstract":[{"en":"Like two lamps of opposite colours switched on at the two ends of one table.","cn":"像同一张桌子两端亮起两盏颜色相反的灯。"},{"en":"Like a hinge in the middle of a sentence, letting the second half swing the other way.","cn":"像句子中间的一枚铰链，让后半句向另一边转。"},{"en":"Like a scale with one full pan and one empty pan, both visible at once.","cn":"像一架天平，一端满一端空，同时可见。"}]},"examples":[{"en":"The north remained industrial; in contrast, the south turned to services.","cn":"北方仍是工业区；相比之下，南方转向服务业。"},{"en":"In contrast to the first edition, the second contains almost no illustrations.","cn":"与第一版不同，第二版几乎没有插图。"},{"en":"In contrast with the coastal towns, inland villages lost population.","cn":"与沿海城镇相比，内陆村庄人口减少。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「因 康特拉斯特」——两物面对面站着，一比就看出不同：相比之下","word":"in contrast"},"root":"contrast 经法语、意大利语进入英语，其动词由拉丁语 contra「反对」与 stare「站立」构成通俗拉丁语重构形式；短语 in contrast 属近代书面英语，首见年代为约数。","sensesIntro":{"en":"Eight senses split by position and complement: front and mid-clause markers, to and with plus a noun, academic counter-evidence, paragraph signpost, parallel clauses, and figure reporting.","cn":"八个义项按位置与搭配区分：句首与句中的对比标记、两个介词加名词、学术反证、段落路标、平行从句、数字报告。"},"semanticMap":{"core":{"en":"CORE IMAGE: one full cup and one empty cup displayed side by side under opposite lights.","cn":"核心意象：满杯与空杯并排摆在相反的灯光下。"},"chain":["STAND AGAINST","FRONT MARKER","MID PIVOT","NAMED BENCHMARK","COUNTER-EVIDENCE","DATA CONTRAST"],"branches":[{"senses":"01 · 07","en":"THE PAIRED CLAUSE: two parallel statements are set face to face.","cn":"成对从句：两个平行陈述面对面摆开。"},{"senses":"02","en":"THE HINGE: inserted mid-sentence, the phrase turns without breaking the line.","cn":"铰链：插在句中，转折而不打断句子。"},{"senses":"03 · 04","en":"THE BENCHMARK: to and with name the thing being stood against.","cn":"基准：两个介词点出被对照的对象。"},{"senses":"05 · 06","en":"THE ARGUMENT SIGNPOST: research and paragraph openings use it to switch sides.","cn":"论证路标：研究与段落开头用它换边。"},{"senses":"08","en":"THE FIGURE: in data writing two series are kept apart without repeating the comparison.","cn":"数字：数据写作中把两组数字分开，不重复比较。"}]},"affixes":{"intro":{"en":"The phrase joins a Latin preposition and a Latin verb of standing; the reconstruction belongs to Vulgar Latin.","cn":"这个短语由拉丁语介词与拉丁语「站立」动词组成；重构形式属通俗拉丁语。"},"latinIntro":{"en":"The Latin etyma are contra, against, and stare, to stand; the verb passed through Italian and French.","cn":"拉丁语词源是 contra「反对」与 stare「站立」；动词经意大利语与法语传来。"},"items":[{"word":"contra","structure":"Latin preposition","meaning":"against; opposite","meaningCN":"反对；相对","example":"Contra appears in many English compounds of opposition.","exampleCN":"这个词根出现在许多表对立的英语复合词里。"},{"word":"stare","structure":"Latin verb, first conjugation","meaning":"to stand","meaningCN":"站立","example":"The verb supplies the image of standing one's ground.","exampleCN":"这个动词提供「站定不退」的画面。"},{"word":"contrastare","structure":"Vulgar Latin verb, reconstructed","meaning":"to stand against","meaningCN":"对立而站","example":"The reconstructed verb is the missing link between Latin and Italian.","exampleCN":"这个重构动词是拉丁语与意大利语之间缺失的一环。"},{"word":"contraster","structure":"Old French verb","meaning":"to contrast","meaningCN":"形成对比","example":"French carried the verb into English in the sixteenth century.","exampleCN":"法语在十六世纪把这个动词带入英语。"},{"word":"contrast","structure":"English noun and verb","meaning":"difference set side by side","meaningCN":"并置的差异","example":"The noun names the difference that the phrase points to.","exampleCN":"名词命名短语所指出的差异。"},{"word":"contrastive","structure":"contrast + -ive","meaning":"expressing contrast","meaningCN":"表示对比的","example":"Linguistics speaks of contrastive pairs.","exampleCN":"语言学讲「对比对」。"},{"word":"in contrast","structure":"preposition + noun, fixed phrase","meaning":"by way of contrast","meaningCN":"相比之下","example":"The phrase works as a connector in written English.","exampleCN":"这个短语在书面英语里作连接语。"},{"word":"by contrast","structure":"preposition + noun, fixed phrase","meaning":"as a contrast","meaningCN":"相比之下（独立连接）","example":"Its twin usually stands alone between sentences.","exampleCN":"它的双胞胎通常在句间独立使用。"}],"latinEntries":[{"word":"contra","structure":"contra (preposition, with ablative)","meaning":"against","meaningCN":"反对"},{"word":"stare","structure":"stare, sto, steti, statum (verb, first conjugation)","meaning":"to stand","meaningCN":"站立"}],"derivatives":[{"word":"contrast","pos":"n./v.","zh":"对比；形成对照"},{"word":"contrastive","pos":"adj.","zh":"对比的；对照的"},{"word":"contrastingly","pos":"adv.","zh":"对比之下（少见）"},{"word":"by contrast","pos":"adv. phr.","zh":"相比之下"},{"word":"contrast with","pos":"v. phr.","zh":"与……形成对比"}]}},{"word":"in comparison","ipa_uk":"/ɪn kəmˈpærɪsn/","ipa_us":"/ɪn kəmˈpærɪsn/","definition_zh":"比较起来；与……相比（用于衡量两者的相似或差距）","definition_en":"when judged against something else; used to weigh two or more things on the same scale","core_image":"两把新旧尺子并排贴在桌面，刻度线一一对齐","scene":"设计师把新旧两版尺子并排贴在桌上，逐一对照刻度。In comparison, the new ruler is slightly longer.","sceneCN":"这里取「比较起来」（第 1 个义项：句首比较标记）；句意为比较起来，新尺子稍长一些。","pos":[{"tag":"adv. phr.","zh":"状语短语：比较起来"},{"tag":"prep. phr.","zh":"介词短语：与……相比"}],"collocations":[{"phrase":"in comparison with","zh":"与……相比"},{"phrase":"in comparison to","zh":"与……相比（北美常用）"},{"phrase":"pale in comparison","zh":"相形见绌"},{"phrase":"bear comparison with","zh":"经得起与……比较"},{"phrase":"in comparison, however","zh":"相比之下，然而"},{"phrase":"in direct comparison","zh":"直接比较之下"}],"forms":[{"label":"原形","form":"in comparison"},{"label":"接名词","form":"in comparison with"},{"label":"接名词（北美变体）","form":"in comparison to"},{"label":"强调式","form":"in direct comparison"}],"derivatives":[{"word":"compare","pos":"v.","zh":"比较；对照"},{"word":"comparable","pos":"adj.","zh":"可比的；相当的"},{"word":"comparative","pos":"adj./n.","zh":"比较的；比较级"},{"word":"comparatively","pos":"adv.","zh":"相对地"},{"word":"comparison","pos":"n.","zh":"比较；对照"}],"senses":[{"no":"01","title":"The sentence-opening comparison marker","titleCN":"句首：比较起来","definition":"placed at the beginning of a clause to introduce a judgement made by weighing two things","definitionCN":"置于从句开头，引出把两物放在同一把尺上得出的判断","example":"In comparison, the second route is shorter.","exampleCN":"比较起来，第二条路线更短。","why":"Front position tells the reader that the following statement is measured against the one just made.","whyCN":"置于句首告诉读者，接下来的说法是拿前一句作尺子量出来的。"},{"no":"02","title":"The formal with variant","titleCN":"后接介词加名词：与……相比","definition":"used with with and a noun to name the standard of comparison","definitionCN":"用介词加名词，点出比较的基准","example":"In comparison with last year, sales fell.","exampleCN":"与去年相比，销售额下降了。","why":"With names the benchmark, turning the adverbial phrase into a prepositional frame at the head of the sentence.","whyCN":"该介词点出基准，于是状语短语变成句首的介词框架。"},{"no":"03","title":"The North American to variant","titleCN":"后接另一个介词加名词：与……相比（北美常用）","definition":"used with to instead of with, especially in North American writing, with the same meaning","definitionCN":"用另一个介词代替，多见于北美书面语，意义相同","example":"In comparison to the older model, this one runs cooler.","exampleCN":"与旧型号相比，这一款运行更凉。","why":"The two prepositions are variants rather than contrasts; to has become the more frequent partner in North America.","whyCN":"两个介词是变体而非对立；在北美，后者已成为更常见的搭档。"},{"no":"04","title":"The mid-sentence aside","titleCN":"句中插入：相比之下","definition":"inserted inside a clause, usually between commas, to add a measured aside","definitionCN":"插在从句内部，通常用逗号夹住，补一句比较性的旁白","example":"The new model, in comparison, uses far less power.","exampleCN":"相比之下，新型号耗电少得多。","why":"Inside commas the phrase behaves like a parenthetical comment rather than a full connector.","whyCN":"被逗号夹住时，这个短语更像插入的旁注，而不是完整的连接语。"},{"no":"05","title":"The idiom of falling short","titleCN":"固定搭配：相形见绌","definition":"in the fixed pattern pale in comparison, used to say that one thing looks weak beside another","definitionCN":"在固定说法「相形见绌」中，表示一物放在另一物旁边显得逊色","example":"The old hall pales in comparison.","exampleCN":"与之一比，旧礼堂相形见绌。","why":"The verb pale supplies the image of colour draining away, and the phrase supplies the standard that causes it.","whyCN":"动词「失色」提供颜色褪去的画面，这个短语则提供使之失色的基准。"},{"no":"06","title":"Weighing similarity, not opposition","titleCN":"同类对比：强调相似","definition":"used when two things are placed on one scale to show how close or far apart they are","definitionCN":"把两物放在同一把尺上，显示它们相差多少","example":"In comparison, the two samples were nearly identical.","exampleCN":"比较起来，两个样本几乎完全相同。","why":"This is the boundary against in contrast: here the point may be closeness, there the point is always divergence.","whyCN":"这正是它与对比短语的分界：这里可以指接近，那里永远指分歧。"},{"no":"07","title":"Reporting a neighbouring figure","titleCN":"图表叙述：与相邻数字比较","definition":"used in data writing to set a figure against the one before or beside it","definitionCN":"在数据写作中，把某个数字与前一数字或相邻数字并置","example":"In comparison, imports rose while exports held steady.","exampleCN":"相比之下，进口上升，出口持平。","why":"Charts need a short signal that two series are read together, and the phrase provides it without repeating the numbers.","whyCN":"图表需要一个短信号说明两组数据要合看，这个短语不必重复数字就做到了。"},{"no":"08","title":"The evaluative aside","titleCN":"评价句：对比之下显得……","definition":"used to introduce a judgement about quality after a standard has been set","definitionCN":"在基准已经摆出之后，引出关于优劣的判断","example":"In comparison, the first draft looks careless.","exampleCN":"对比之下，初稿显得草率。","why":"Once a benchmark is on the table, the phrase can carry a verdict rather than a measurement.","whyCN":"基准一旦摆上桌面，这个短语就能承载评判而不只是测量。"}],"etymology":{"intro":{"en":"Comparison goes back to Latin comparatio, from comparare, to pair together, itself com-, together, plus par, equal. The Latin line is clear; the English phrase is modern.","cn":"comparison 可追溯到拉丁语 comparatio，来自 comparare「配对」，由 com-「共同」与 par「相等」构成。拉丁语线索清楚，英语短语属近代。"},"items":[{"era":"LATIN PAR","en":"Par means equal and is also the root of peer and parity.","cn":"par 意为「相等」，也是 peer 与 parity 的词根。"},{"era":"LATIN COMPARARE","en":"Comparare meant to bring things together as equals, hence to compare.","cn":"comparare 意为把事物作为对等者放到一起，即「比较」。"},{"era":"LATIN COMPARATIO","en":"The noun named a setting side by side, and Old French comparaison carried it to English.","cn":"这个名词指并置对照，古法语 comparaison 把它带入英语。"},{"era":"ENGLISH COMPARISON","en":"English comparison appears in the Middle English period; the exact date is approximate.","cn":"英语 comparison 出现于中古英语时期，确切年代为约数。"},{"era":"THE MODERN PHRASE","en":"The adverbial phrase and its two prepositional variants settle in modern written English.","cn":"状语短语及其两个介词变体在近代书面英语中定型。"}]},"similar":{"note":{"en":"The first group shares the comparison slot but stresses difference or another relation; the second group holds adverbs and paraphrases of measured judgement.","cn":"第一组占同样的比较位置，却强调差异或别的关系；第二组是衡量判断的副词与同义改写。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"in contrast","ipa":"/ɪn ˈkɒntrɑːst/","tag":"difference, not similarity","definition":"It always stresses divergence, while this phrase may also report closeness.","definitionCN":"它始终强调分歧，而本短语也可以报告接近。"},{"word":"by comparison","ipa":"/baɪ kəmˈpærɪsn/","tag":"stand-alone connector","definition":"It usually opens a sentence on its own and rarely takes with or to.","definitionCN":"它通常独立开启一句，很少接介词。"},{"word":"compared with","ipa":"/kəmˈpɛəd wɪð/","tag":"participial frame","definition":"It is the common verbal frame for the same benchmark.","definitionCN":"它是同一基准最常用的分词框架。"},{"word":"in relation to","ipa":"/ɪn rɪˈleɪʃn tuː/","tag":"relation, wider than scale","definition":"It relates two things without necessarily measuring them.","definitionCN":"它把两物联系起来，未必要测量。"}]},{"heading":"NEAR MEANING","entries":[{"word":"comparatively","ipa":"/kəmˈpærətɪvli/","tag":"adverb of degree","definition":"It means relatively, judged against others, and often modifies an adjective.","definitionCN":"意为相对地，常修饰形容词。"},{"word":"relatively","ipa":"/rɪˈleɪtɪvli/","tag":"proportional judgement","definition":"It marks a judgement that depends on the standard chosen.","definitionCN":"标出取决于所选基准的判断。"},{"word":"alongside","ipa":"/əˈlɒŋsaɪd/","tag":"placed next to","definition":"It puts two things side by side in space or argument.","definitionCN":"在空间或论证中把两物并排。"},{"word":"measured against","ipa":"/ˈmeʒəd əˈɡenst/","tag":"explicit benchmark","definition":"It names the standard in a verbal phrase rather than a fixed idiom.","definitionCN":"用动词短语点明基准，而非固定习语。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Latin pair, the real prepositions and the real idiom.","cn":"正常联想用真实拉丁语对、真实介词与真实习语。"},"normal":[{"en":"Par is equal, so to compare is to bring equals together.","cn":"拉丁词根意为「相等」，比较就是把对等者放到一起。"},{"en":"With names the benchmark; to is its North American twin.","cn":"一个介词点出基准，另一个是它的北美双胞胎。"},{"en":"At the front it opens the judgement; in commas it is an aside.","cn":"放句首开启判断，放逗号里则是旁注。"},{"en":"Pale in comparison is the idiom for falling short.","cn":"「相形见绌」是表示逊色的固定说法。"},{"en":"Its neighbour in contrast always stresses difference, so the two are not interchangeable.","cn":"邻近的对比短语始终强调差异，两者不能互换。"}],"abstract":[{"en":"Like two rulers laid edge to edge so the marks line up.","cn":"像两把尺子边缘对齐，刻度一一相合。"},{"en":"Like a pair of scales that can report either a gap or a match.","cn":"像一架天平，既能报出差值，也能报出相等。"},{"en":"Like a colour fading when a brighter sample is held beside it.","cn":"像更亮的样本一放旁边，颜色便显得褪了。"}]},"examples":[{"en":"In comparison with the coast, the inland region receives little rain.","cn":"与沿海相比，内陆地区降雨很少。"},{"en":"In comparison to the first edition, this one is heavily illustrated.","cn":"与第一版相比，这一版插图很多。"},{"en":"The earlier attempt pales in comparison.","cn":"早先的尝试相形见绌。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「因 康帕瑞森」——两把尺子并排，一比就知长短：比较起来","word":"in comparison"},"root":"comparison 来自拉丁语 comparatio，词根 comparare 由 com-「共同」与 par「相等」构成，经古法语进入英语；短语 in comparison 属近代书面用法，首见年代为约数。","sensesIntro":{"en":"Eight senses split by position and complement: front and mid-clause, with and to plus a noun, the idiom of falling short, similarity, figure reporting, and evaluative judgement.","cn":"八个义项按位置与搭配区分：句首与句中、两个介词加名词、「相形见绌」习语、相似性、数字报告、评价判断。"},"semanticMap":{"core":{"en":"CORE IMAGE: two rulers laid edge to edge, marks aligned.","cn":"核心意象：两把尺子边缘对齐，刻度相合。"},"chain":["PAIR TOGETHER","FRONT MARKER","NAMED BENCHMARK","MID ASIDE","FALL SHORT","EVALUATION"],"branches":[{"senses":"01 · 04","en":"THE MARKER: front position opens a judgement, mid position adds a parenthetical aside.","cn":"标记：句首开启判断，句中补入旁注。"},{"senses":"02 · 03","en":"THE BENCHMARK: two prepositions name the standard being used.","cn":"基准：两个介词点出所采用的基准。"},{"senses":"05","en":"THE IDIOM: one thing fades beside another.","cn":"习语：一物在另一物旁失色。"},{"senses":"06 · 07","en":"THE SCALE: the phrase may report closeness or set two series of figures together.","cn":"刻度：可报告接近，也可把两组数字并置。"},{"senses":"08","en":"THE VERDICT: once a standard is set, quality can be judged.","cn":"评判：基准既定，便可评优劣。"}]},"affixes":{"intro":{"en":"The phrase joins a Latin noun of pairing with an English preposition; the Latin core is clear.","cn":"这个短语把拉丁语「配对」名词与英语介词结合；拉丁核心清楚。"},"latinIntro":{"en":"The Latin etyma are comparare, to pair together, and par, equal.","cn":"拉丁语词源是 comparare「配对」与 par「相等」。"},"items":[{"word":"par","structure":"Latin adjective and noun","meaning":"equal","meaningCN":"相等的","example":"Par is the root of peer and parity as well.","exampleCN":"这个词根也是另外两个英语词的来源。"},{"word":"comparare","structure":"Latin verb, first conjugation","meaning":"to pair together; to compare","meaningCN":"配对；比较","example":"The verb brings two equals into one frame.","exampleCN":"这个动词把两个对等者放进同一框架。"},{"word":"comparatio","structure":"Latin noun from comparare","meaning":"a setting side by side","meaningCN":"并置对照","example":"The noun names the act that the phrase marks.","exampleCN":"名词命名这个短语所标记的动作。"},{"word":"comparaison","structure":"Old French noun","meaning":"comparison","meaningCN":"比较","example":"French carried the noun into Middle English.","exampleCN":"法语把这个名词带入中古英语。"},{"word":"comparison","structure":"English noun","meaning":"the act of comparing","meaningCN":"比较","example":"The noun is the base of the adjective comparable.","exampleCN":"这个名词是相应形容词的基词。"},{"word":"comparable","structure":"comparison + -able","meaning":"able to be compared","meaningCN":"可比的","example":"The suffix turns the noun into an adjective.","exampleCN":"后缀把名词变成形容词。"},{"word":"comparative","structure":"comparison + -ative","meaning":"relating to comparison","meaningCN":"比较的","example":"Grammar uses the word for the comparative degree.","exampleCN":"语法用它指比较级。"},{"word":"in comparison","structure":"preposition + noun, fixed phrase","meaning":"by way of comparison","meaningCN":"比较起来","example":"The phrase works as a connector in written English.","exampleCN":"这个短语在书面英语中作连接语。"}],"latinEntries":[{"word":"comparare","structure":"comparare, comparo, comparavi, comparatum (verb, first conjugation)","meaning":"to pair together; to compare","meaningCN":"配对；比较"},{"word":"par","structure":"par, paris (adjective and noun, third declension)","meaning":"equal","meaningCN":"相等的"}],"derivatives":[{"word":"compare","pos":"v.","zh":"比较；对照"},{"word":"comparable","pos":"adj.","zh":"可比的；相当的"},{"word":"comparative","pos":"adj./n.","zh":"比较的；比较级"},{"word":"comparatively","pos":"adv.","zh":"相对地"},{"word":"comparison","pos":"n.","zh":"比较；对照"}]}},{"word":"in accordance with","ipa_uk":"/ɪn əˈkɔːdəns wɪð/","ipa_us":"/ɪn əˈkɔːrdəns wɪð/","definition_zh":"依照，按照（规定、法律、指示）；与……一致","definition_en":"following or agreeing with a rule, law, instruction or standard","core_image":"一只手把申请表压在法条汇编上，逐条核对后盖章","scene":"审批员把申请表摊在法规汇编旁，逐条核对后盖章。The permit was issued in accordance with the safety code.","sceneCN":"这里取「依照规定」（第 1 个义项：后接法规、规范等正式依据）；句意为许可证是依照安全规范签发的。","pos":[{"tag":"prep. phr.","zh":"介词短语：依照、按照（正式）"},{"tag":"prep. phr.","zh":"介词短语：与……一致、相符"}],"collocations":[{"phrase":"in accordance with the law","zh":"依照法律"},{"phrase":"in accordance with the rules","zh":"按照规则"},{"phrase":"in accordance with instructions","zh":"按照指示"},{"phrase":"in accordance with standards","zh":"符合标准"},{"phrase":"in accordance with the contract","zh":"依照合同"},{"phrase":"in accordance with the findings","zh":"与调查结果相符"}],"forms":[{"label":"原形","form":"in accordance with"},{"label":"正式变体","form":"in accordance with the provisions of"},{"label":"后置用法","form":"shall be conducted in accordance with"}],"derivatives":[{"word":"accord","pos":"n./v.","zh":"一致；给予"},{"word":"according","pos":"prep.","zh":"根据（较口语的对应说法）"},{"word":"accordingly","pos":"adv.","zh":"因此；相应地"},{"word":"accordance","pos":"n.","zh":"一致；依照"},{"word":"in accordance with","pos":"prep. phr.","zh":"依照（正式）"}],"senses":[{"no":"01","title":"Compliance with a law or regulation","titleCN":"依照法律、法规","definition":"used before the name of a law or regulation to say that an act follows it","definitionCN":"用在法律或法规名称之前，表示行为遵循该规定","example":"The permit was issued in accordance with the safety code.","exampleCN":"许可证是依照安全规范签发的。","why":"The phrase turns a rule into the authority behind an act, which is why statutes are its most natural object.","whyCN":"这个短语把规则变成行为背后的授权依据，所以法规是它最自然的宾语。"},{"no":"02","title":"Acting on an instruction or authorization","titleCN":"按照指示、授权","definition":"used before an instruction or an authority to show that the action was authorized","definitionCN":"用在指示或授权之前，表明行为获得许可","example":"Payment was released in accordance with your written instruction.","exampleCN":"款项是依照你的书面指示放出的。","why":"With an instruction, the phrase answers the question of who authorized the act, not merely what rule exists.","whyCN":"接指示时，这个短语回答「谁授权了这个动作」，而不只是说明有何规则。"},{"no":"03","title":"Agreement with facts or records","titleCN":"与事实、记录相符","definition":"used before a statement of fact to say that a description matches the evidence","definitionCN":"用在事实陈述之前，表示描述与证据一致","example":"The report was corrected in accordance with the original records.","exampleCN":"报告已依照原始记录作了更正。","why":"Here the phrase moves from obedience to correspondence: what is checked is accuracy, not permission.","whyCN":"此处短语从「服从」转向「相符」：被检验的是准确，而非许可。"},{"no":"04","title":"Compliance with contract terms","titleCN":"合同条款：依约","definition":"used in contracts to bind a party to the terms already agreed","definitionCN":"在合同中使用，使一方受已达成的条款约束","example":"The goods were delivered in accordance with clause four.","exampleCN":"货物是依照第四条交付的。","why":"Contract drafting needs a phrase that points to the document itself as the standard, and this one does exactly that.","whyCN":"合同起草需要一个以文件本身为准的说法，这个短语正好如此。"},{"no":"05","title":"Conformity with a technical standard","titleCN":"符合技术标准","definition":"used before a standard or specification to state that a product or process meets it","definitionCN":"用在标准或规格之前，说明产品或流程达到该要求","example":"The samples were tested in accordance with the national standard.","exampleCN":"样品是依照国家标准检测的。","why":"In technical writing the phrase links a procedure to a published standard, so the method can be audited.","whyCN":"在技术写作中，这个短语把流程挂到已公布的标准上，方法因而可被审核。"},{"no":"06","title":"The formal alternative to a plain phrase","titleCN":"正式语域：书面替代口语说法","definition":"in official and academic prose it replaces the plainer phrase according to","definitionCN":"在官方与学术文字中替代更口语的说法","example":"The forms must be filed in accordance with the guidance issued last year.","exampleCN":"表格必须依照去年发布的指引提交。","why":"The phrase is chosen precisely because it sounds institutional; the everyday alternative would lower the register.","whyCN":"选用这个短语正因为它听起来像机构语言；日常说法会把语域拉低。"},{"no":"07","title":"The routine formula in procedure documents","titleCN":"公文句式：须依照……进行","definition":"in manuals and procedure documents it frames an obligatory step in a fixed formula","definitionCN":"在手册与程序文件中，以固定句式框定一个必须执行的步骤","example":"All inspections shall be conducted in accordance with the attached schedule.","exampleCN":"所有检查均须依照所附日程进行。","why":"Procedure writing pairs shall with the phrase so that the obligation and its standard appear in one clause.","whyCN":"程序写作把「须」与这个短语配对，使义务与标准出现在同一从句里。"},{"no":"08","title":"Consistency with a principle or intention","titleCN":"与原则、意愿保持一致","definition":"used before a principle or intention to say that an act expresses it consistently","definitionCN":"用在原则或意愿之前，表示行为一贯地体现它","example":"The decision was made in accordance with the values the committee had stated.","exampleCN":"这一决定与委员会先前申明的价值取向一致。","why":"When the object is abstract, the phrase checks coherence over time rather than compliance with a written rule.","whyCN":"当宾语是抽象原则时，这个短语检验的是长期一致性，而非对成文规则的服从。"}],"etymology":{"intro":{"en":"Accordance comes from accord, which English took from Old French acorder, from Vulgar Latin accordare, from Latin ad, to, and cor, heart. The heart etymon is certain; the Vulgar Latin verb is a reconstruction.","cn":"accordance 来自 accord，英语经古法语 acorder 借入，其源头是通俗拉丁语 accordare，由拉丁语 ad「向」与 cor「心」构成。「心」这一词根确定；通俗拉丁语动词属重构形式。"},"items":[{"era":"LATIN COR","en":"Cor, cordis, heart, is also the source of cordial and record; to bring hearts together was to agree.","cn":"cor 意为「心」，也是 cordial 与 record 的来源；把心放到一起就是达成一致。"},{"era":"VULGAR LATIN ACCORDARE","en":"The reconstructed verb meant to reconcile or bring into harmony.","cn":"重构的动词意为调和、使和谐。"},{"era":"OLD FRENCH ACORDER","en":"Old French acorder meant to be of one heart, and gave English the noun accord.","cn":"古法语 acorder 意为同心，给英语带来名词 accord。"},{"era":"ENGLISH ACCORDANCE","en":"Accordance, meaning agreement, is recorded in Middle English; the date is approximate.","cn":"accordance 意为一致，见于中古英语，年代为约数。"},{"era":"THE LEGAL PHRASE","en":"The phrase with this preposition settles in modern legal and administrative writing.","cn":"带这个介词的短语在近代法律与行政文字中定型。"}]},"similar":{"note":{"en":"The first group marks a standard being followed but differs in formality or in what is followed; the second group holds formal ways of citing a rule.","cn":"第一组都标出所遵循的标准，但正式程度或所循对象不同；第二组是引用规则的正式说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"according to","ipa":"/əˈkɔːdɪŋ tuː/","tag":"plainer, wider register","definition":"It reports a source or a rule in neutral prose and can also mean as stated by.","definitionCN":"它在中性文字中交代来源或规则，也可表「据……所说」。"},{"word":"in agreement with","ipa":"/ɪn əˈɡriːmənt wɪð/","tag":"agreement, not procedure","definition":"It stresses harmony between parties rather than compliance with a rule.","definitionCN":"它强调各方和谐，而非对规则的遵守。"},{"word":"in compliance with","ipa":"/ɪn kəmˈplaɪəns wɪð/","tag":"regulatory obedience","definition":"It is the regulator's phrase and foregrounds obedience to a requirement.","definitionCN":"这是监管者的用语，突出对要求的服从。"},{"word":"under","ipa":"/ˈʌndə/","tag":"legal shorthand","definition":"Under plus a law is a shorter legal formula with the same authority.","definitionCN":"「根据」加法律是更短的法律套语，授权意味相同。"}]},{"heading":"NEAR MEANING","entries":[{"word":"pursuant to","ipa":"/pəˈsjuːənt tuː/","tag":"contractual and statutory","definition":"A dense legal phrase meaning in carrying out the terms of.","definitionCN":"一个密集的法律短语，意为「依……条款执行」。"},{"word":"consistent with","ipa":"/kənˈsɪstənt wɪð/","tag":"coherence","definition":"It checks that two statements or acts do not contradict each other.","definitionCN":"它检查两项陈述或行为是否互相矛盾。"},{"word":"in line with","ipa":"/ɪn ˈlaɪn wɪð/","tag":"alignment in policy","definition":"It is the policy writer's phrase for keeping to an agreed direction.","definitionCN":"政策写作者的用语，指与既定方向保持一致。"},{"word":"as per","ipa":"/æz pɜː/","tag":"commercial shorthand","definition":"A brief business formula meaning according to, often criticized as informal.","definitionCN":"简短的商务套语，意为「按照」，常被指为不够正式。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real heart root, the real legal phrase and the real register.","cn":"正常联想用真实的「心」词根、真实法律短语与真实语域。"},"normal":[{"en":"The root is heart: agreement was first a coming together of hearts.","cn":"词根是「心」：一致最初指心走到一起。"},{"en":"It takes a noun, never a clause; a whole statement needs the fact that frame.","cn":"它接名词，从不接从句；完整命题要靠「事实是」框架。"},{"en":"The object is usually a law, a rule, a standard or an instruction.","cn":"宾语通常是法律、规则、标准或指示。"},{"en":"Its everyday cousin according to is shorter and less institutional.","cn":"它的日常表亲更短，也没那么机构化。"},{"en":"In contracts it points to the document itself as the authority.","cn":"在合同里，它把文件本身指为授权来源。"}],"abstract":[{"en":"Like a stamp pressed onto a form only after the rule book has been checked line by line.","cn":"像逐条核对规则汇编之后，才在表格上盖章。"},{"en":"Like a road that follows the fence rather than cutting across it.","cn":"像一条顺着栅栏走、而不横穿过去的道路。"},{"en":"Like two hearts beating to the same rhythm before a signature is given.","cn":"像签字之前，两颗心按同一节奏跳动。"}]},"examples":[{"en":"The work was carried out in accordance with the agreed schedule.","cn":"工作依照商定的日程进行。"},{"en":"In accordance with the regulations, all visitors must register.","cn":"依照规定，所有访客必须登记。"},{"en":"The account was adjusted in accordance with the auditor's findings.","cn":"账目已依照审计发现作了调整。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「因 阿科丹斯 威斯」——先翻规则再盖章：依照、按照","word":"in accordance with"},"root":"accordance 源自拉丁语 cor「心」，经通俗拉丁语重构形式 accordare 与古法语 acorder 进入英语，本义「同心、一致」；in accordance with 是近代法律与公文定型短语，首见年代为约数。","sensesIntro":{"en":"Eight senses split by the object followed: a law, an instruction, the facts, a contract clause, a technical standard, formal register, procedure formulas, and an abstract principle.","cn":"八个义项按所循对象区分：法律、指示、事实、合同条款、技术标准、正式语域、公文句式、抽象原则。"},"semanticMap":{"core":{"en":"CORE IMAGE: a seal pressed only after the rule book has been checked line by line.","cn":"核心意象：逐条核对规则汇编后才落下的印章。"},"chain":["ONE HEART","LAW AND RULE","INSTRUCTION","FACTS","CONTRACT","PRINCIPLE"],"branches":[{"senses":"01 · 05","en":"THE RULE: statutes and technical standards supply the authority for an act.","cn":"规则：法规与技术标准为行为提供依据。"},{"senses":"02 · 04","en":"THE AUTHORIZATION: instructions and contract clauses bind the act to a document.","cn":"授权：指示与合同条款把行为绑到文件上。"},{"senses":"03","en":"THE RECORD: accuracy is checked against the evidence rather than permission.","cn":"记录：对照证据检验准确，而非许可。"},{"senses":"06 · 07","en":"THE REGISTER: official prose and procedure formulas keep the phrase institutional.","cn":"语域：官方文字与程序句式让它保持机构语气。"},{"senses":"08","en":"THE PRINCIPLE: an abstract value is checked for coherence over time.","cn":"原则：抽象价值被检验是否长期一贯。"}]},"affixes":{"intro":{"en":"The phrase joins a noun built on the Latin word for heart with an English preposition; the Latin core is transparent.","cn":"这个短语把建在拉丁语「心」上的名词与英语介词结合；拉丁核心透明。"},"latinIntro":{"en":"The Latin etymon is cor, heart, through the reconstructed Vulgar Latin verb accordare.","cn":"拉丁语词源是 cor「心」，经通俗拉丁语重构动词 accordare 而来。"},"items":[{"word":"cor","structure":"Latin noun, third declension","meaning":"heart","meaningCN":"心","example":"The root also gives cordial and record.","exampleCN":"这个词根也给出另外两个英语词。"},{"word":"accordare","structure":"Vulgar Latin verb, reconstructed","meaning":"to reconcile; to bring into harmony","meaningCN":"调和；使一致","example":"The verb is reconstructed rather than attested.","exampleCN":"这个动词属重构，并非有直接记录。"},{"word":"acorder","structure":"Old French verb","meaning":"to agree; to be of one heart","meaningCN":"同意；同心","example":"French passed the verb and its noun to English.","exampleCN":"法语把这个动词及其名词传给英语。"},{"word":"accord","structure":"English noun and verb","meaning":"agreement; to grant","meaningCN":"一致；给予","example":"The noun still means a mutual agreement.","exampleCN":"这个名词至今指相互一致。"},{"word":"accordance","structure":"accord + -ance","meaning":"the state of agreeing","meaningCN":"一致的状态","example":"The suffix turns the verb into a noun of state.","exampleCN":"后缀把动词变成表状态的名词。"},{"word":"according","structure":"accord + -ing","meaning":"in agreement with","meaningCN":"与……相符","example":"The participle heads the everyday phrase.","exampleCN":"这个分词领起日常说法。"},{"word":"accordingly","structure":"according + -ly","meaning":"therefore; in the fitting way","meaningCN":"因此；相应地","example":"The adverb marks a consequence or a fit.","exampleCN":"副词标出结果或相称。"},{"word":"in accordance with","structure":"preposition + noun + preposition","meaning":"following or matching","meaningCN":"依照；与……一致","example":"The phrase is standard in statutes and manuals.","exampleCN":"这个短语在法规与手册中是标准用法。"}],"latinEntries":[{"word":"cor","structure":"cor, cordis (noun, third declension)","meaning":"heart","meaningCN":"心"},{"word":"accordare","structure":"accordare (Vulgar Latin verb, reconstructed)","meaning":"to reconcile","meaningCN":"调和"}],"derivatives":[{"word":"accord","pos":"n./v.","zh":"一致；给予"},{"word":"according","pos":"prep.","zh":"根据（according to）"},{"word":"accordingly","pos":"adv.","zh":"因此；相应地"},{"word":"accordance","pos":"n.","zh":"一致；依照"},{"word":"in accordance with","pos":"prep. phr.","zh":"依照（正式）"}]}},{"word":"in addition to","ipa_uk":"/ɪn əˈdɪʃn tuː/","ipa_us":"/ɪn əˈdɪʃn tuː/","definition_zh":"除……之外（还）；此外还有（表示累加，不表示排除）","definition_en":"used to add a further item to what has already been mentioned; besides","core_image":"采购清单上已经写了灯泡，店员又在末尾添上一盒电池","scene":"采购清单上已经列了灯泡，店员又在末尾添上电池。In addition to the bulbs, the order included batteries.","sceneCN":"这里取「除……之外还」（第 1 个义项：句首累加标记）；句意为除了灯泡，订单里还包括电池。","pos":[{"tag":"prep. phr.","zh":"介词短语：除……之外还（累加）"},{"tag":"adv. phr.","zh":"状语用法：此外、另外"}],"collocations":[{"phrase":"in addition to the cost","zh":"除成本之外"},{"phrase":"in addition to the main course","zh":"除主菜之外"},{"phrase":"in addition to which","zh":"除此之外还"},{"phrase":"in addition to the fact that","zh":"除了……这一事实之外"},{"phrase":"in addition to doing","zh":"除做……之外"},{"phrase":"in addition to a salary","zh":"除薪水之外"}],"forms":[{"label":"原形","form":"in addition to"},{"label":"接动名词","form":"in addition to doing"},{"label":"接事实从句","form":"in addition to the fact that"},{"label":"独立副词","form":"in addition"}],"derivatives":[{"word":"add","pos":"v.","zh":"增加；添加"},{"word":"addition","pos":"n.","zh":"增加；加法"},{"word":"additional","pos":"adj.","zh":"额外的"},{"word":"additionally","pos":"adv.","zh":"此外；另外"},{"word":"additive","pos":"n./adj.","zh":"添加剂；附加的"}],"senses":[{"no":"01","title":"The sentence-opening additive marker","titleCN":"句首：除……之外还","definition":"placed at the start of a sentence to add an item to what was just said","definitionCN":"置于句首，在刚说过的内容上再加一项","example":"In addition to the bulbs, the order included batteries.","exampleCN":"除了灯泡，订单里还包括电池。","why":"Fronting the phrase tells the reader that the new item is extra, not a replacement.","whyCN":"把短语提到句首，读者便知新项是额外添加，而非替换。"},{"no":"02","title":"The mid-sentence addition","titleCN":"句中：除……外另加","definition":"placed after the main clause to attach an extra item without changing the main assertion","definitionCN":"放在主句之后，附加一项而不改变主要断言","example":"The room has a desk, in addition to a small bed.","exampleCN":"这间房除了一张小床，还有一张书桌。","why":"Trailing position keeps the main statement intact and simply appends the further item.","whyCN":"后置让主句保持完整，只是把附加项接在后面。"},{"no":"03","title":"A gerund after the phrase","titleCN":"后接动名词：除做……之外","definition":"used before an -ing form when the added item is an activity rather than a thing","definitionCN":"在附加项是活动而非物品时，用在动名词之前","example":"In addition to teaching, she supervises three labs.","exampleCN":"除了教学，她还管理三个实验室。","why":"Because the phrase is prepositional, an activity must appear as a gerund and cannot appear as a bare verb.","whyCN":"由于这是介词短语，活动必须以动名词形式出现，不能用光秃秃的动词。"},{"no":"04","title":"The fact clause extension","titleCN":"后接事实从句：除了……这一事实","definition":"used before the fact that when the added item is a full statement","definitionCN":"在附加项是完整命题时，用在「事实是」之前","example":"In addition to the fact that the roof leaked, the heating failed.","exampleCN":"除了屋顶漏水这一事实，供暖也坏了。","why":"The frame is the only clean way to add a whole clause after a prepositional phrase.","whyCN":"这个框架是介词短语后追加整句的唯一干净办法。"},{"no":"05","title":"Adding evidence in academic prose","titleCN":"学术写作：追加论据","definition":"in research writing, used to introduce a second line of evidence for the same claim","definitionCN":"在学术写作中，为同一主张引入第二条证据","example":"In addition to the survey data, the study used two interviews.","exampleCN":"除调查数据外，研究还用了两次访谈。","why":"Academic argument often needs to stack support without implying that the first item was weak.","whyCN":"学术论证常需叠加支撑，又不暗示第一项薄弱。"},{"no":"06","title":"Adding a charge or an amount","titleCN":"费用与数量：另外加收","definition":"used in bills and quotations to name a charge that comes on top of the base figure","definitionCN":"在账单与报价中，点出基础数字之外另加的费用","example":"In addition to the base fee, a delivery charge applies.","exampleCN":"除基本费用外，还另收配送费。","why":"Commercial writing uses the phrase to separate the base price from the extras that follow it.","whyCN":"商务文字借此把基础价格与随后的附加项分开。"},{"no":"07","title":"Appending an item to a list","titleCN":"清单：追加一项","definition":"used in inventories and instructions to append one more item to an existing list","definitionCN":"在清单与说明中，向已有列表追加一项","example":"In addition to the tools listed, bring a torch.","exampleCN":"除了所列工具，再带一支手电。","why":"Lists need a marker that says the enumeration continues, and the phrase supplies one.","whyCN":"清单需要一个表示列举继续的标记，这个短语正好提供。"},{"no":"08","title":"The formal cousin of a casual word","titleCN":"语域：比口语说法更正式","definition":"in formal and written prose it replaces the shorter casual word besides","definitionCN":"在正式与书面文字中替代更短、更口语的说法","example":"In addition to its cost, the plan has a political price.","exampleCN":"除了成本，这个计划还有政治代价。","why":"Register is the main reason to choose the longer phrase: it sounds planned rather than chatty.","whyCN":"选择更长短语的主要理由是语域：它听起来像经过筹划，而非随口一说。"}],"etymology":{"intro":{"en":"Addition comes from Latin additio, from addere, to give to, itself ad-, to, and dare, to give. The Latin line is certain; the English phrase is modern.","cn":"addition 来自拉丁语 additio，词根 addere 意为「给到」，由 ad-「向」与 dare「给」构成。拉丁语线索确定，英语短语属近代。"},"items":[{"era":"LATIN DARE","en":"Dare, to give, is also the root of date and donate.","cn":"dare 意为「给」，也是 date 与 donate 的词根。"},{"era":"LATIN ADDERE","en":"Addere meant to give to something, hence to put an extra thing onto it.","cn":"addere 意为「给到某物上」，即把额外之物加上去。"},{"era":"LATIN ADDITIO","en":"The noun named the act of adding, and Old French addition carried it to English.","cn":"这个名词指添加的动作，古法语 addition 把它带入英语。"},{"era":"ENGLISH ADDITION","en":"English addition appears in the Middle English period; the date is approximate.","cn":"英语 addition 见于中古英语，年代为约数。"},{"era":"THE MODERN PHRASE","en":"The prepositional phrase with this preposition and to settles in modern written English.","cn":"带这个介词与 to 的介词短语在近代书面英语中定型。"}]},"similar":{"note":{"en":"The first group adds or excludes items and differs in whether the main item is included; the second group holds adverbs that also stack further points.","cn":"第一组都涉及增删项目，但主项是否包含不同；第二组是同样叠加观点或项目的副词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"besides","ipa":"/bɪˈsaɪdz/","tag":"casual twin, wider use","definition":"It can add an item or dismiss one as an aside, and it sounds more conversational.","definitionCN":"它可追加项目，也可撇开一项作旁白，语气更口语。"},{"word":"apart from","ipa":"/əˈpɑːt frɒm/","tag":"adds or excludes","definition":"It can add, but it also commonly means except, so context matters.","definitionCN":"它可以表追加，但也常表排除，须看语境。"},{"word":"aside from","ipa":"/əˈsaɪd frɒm/","tag":"North American variant","definition":"It works like apart from and carries the same double possibility.","definitionCN":"用法像另一个排除类说法，同样有追加与排除两种可能。"},{"word":"as well as","ipa":"/æz ˈwel æz/","tag":"clausal coordinator","definition":"It joins two items of equal weight rather than attaching an extra one.","definitionCN":"它连接两个等权项目，而非附加一项。"}]},{"heading":"NEAR MEANING","entries":[{"word":"additively","ipa":"/əˈdɪtɪvli/","tag":"manner adverb","definition":"It describes combining effects by simple addition.","definitionCN":"描述把效应简单相加。"},{"word":"additionally","ipa":"/əˈdɪʃənəli/","tag":"stand-alone connector","definition":"It opens a sentence with a further point, without naming an item.","definitionCN":"在句首补一个观点，不点名具体项目。"},{"word":"furthermore","ipa":"/ˌfɜːðəˈmɔː/","tag":"formal connector","definition":"A formal adverb that stacks another argument.","definitionCN":"正式的叠加论证副词。"},{"word":"on top of","ipa":"/ɒn ˈtɒp ɒv/","tag":"informal stacking","definition":"It adds a burden or an extra cost in conversational style.","definitionCN":"以口语方式追加负担或额外成本。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Latin verb of giving, the real complement rules and the real register.","cn":"正常联想用真实拉丁语「给」动词、真实搭配规则与真实语域。"},"normal":[{"en":"To add is to give to, so the second item is literally given on top of the first.","cn":"添加就是给到上面，所以第二项确实叠在第一项上。"},{"en":"It takes a noun or a gerund, never a bare verb.","cn":"它接名词或动名词，绝不接光秃秃的动词。"},{"en":"A whole clause needs the fact that frame after it.","cn":"完整从句需要「事实是」框架接在后面。"},{"en":"It adds and never excludes; the excluding sense belongs to other phrases.","cn":"它只追加，从不排除；排除义属别的短语。"},{"en":"The longer form sounds planned, which is why bills and papers prefer it.","cn":"较长形式听起来像筹划过，所以账单与论文偏爱它。"}],"abstract":[{"en":"Like a hand adding one more item to a shopping basket already on the counter.","cn":"像一只手往已经放在柜台的购物篮里再添一件。"},{"en":"Like a second lamp switched on beside one that is already lit.","cn":"像在一盏已亮的灯旁再点第二盏。"},{"en":"Like a bill whose base price sits on top, with extras listed beneath.","cn":"像一张账单，基础价在上，附加项列在下面。"}]},"examples":[{"en":"In addition to the tuition fee, students pay a laboratory charge.","cn":"除学费之外，学生还要缴实验费。"},{"en":"In addition to writing the report, she prepared the slides.","cn":"除了写报告，她还准备了幻灯片。"},{"en":"In addition to its cost, the scheme carries a legal risk.","cn":"除了成本，这个方案还带法律风险。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「因 阿迪申 图」——往篮子里再添一件：除……之外还","word":"in addition to"},"root":"addition 来自拉丁语 additio，词根 addere「给到」由 ad-「向」与 dare「给」构成，经古法语进入英语；短语 in addition to 属近代书面用法，首见年代为约数。","sensesIntro":{"en":"Eight senses split by position and complement: front and trailing, a gerund, a fact clause, academic evidence, charges, lists, and register against a casual synonym.","cn":"八个义项按位置与搭配区分：句首与后置、动名词、事实从句、学术论据、费用、清单、与口语同义词的语域。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hand dropping one more item into a basket already on the counter.","cn":"核心意象：一只手往已放在柜台的篮子里再添一件。"},"chain":["GIVE TO","FRONT ADDITION","TRAILING ADDITION","GERUND","FACT CLAUSE","EXTRA CHARGE"],"branches":[{"senses":"01 · 02","en":"THE STACK: front and trailing positions both attach an extra item.","cn":"叠加：句首与后置都附加额外一项。"},{"senses":"03 · 04","en":"THE FORM: activities turn into gerunds and full statements take a fact frame.","cn":"形式：活动变动名词，完整命题用事实框架。"},{"senses":"05","en":"THE EVIDENCE: research stacks a second support without weakening the first.","cn":"证据：研究叠加第二条支撑，不削弱第一条。"},{"senses":"06 · 07","en":"THE BILL AND THE LIST: extras are named after a base figure or a base list.","cn":"账单与清单：附加项列在基础数字或清单之后。"},{"senses":"08","en":"THE REGISTER: the longer form replaces a casual word in formal prose.","cn":"语域：正式文字里用较长形式替代口语词。"}]},"affixes":{"intro":{"en":"The phrase joins a Latin noun of giving with an English preposition; the Latin core is clear.","cn":"这个短语把拉丁语「给」的名词与英语介词结合；拉丁核心清楚。"},"latinIntro":{"en":"The Latin etyma are addere, to give to, and dare, to give.","cn":"拉丁语词源是 addere「给到」与 dare「给」。"},"items":[{"word":"dare","structure":"Latin verb, first conjugation","meaning":"to give","meaningCN":"给","example":"The verb also underlies donate and date.","exampleCN":"这个动词也是另外两个英语词的基础。"},{"word":"addere","structure":"ad- + dare (verb, third conjugation)","meaning":"to give to; to add","meaningCN":"给到；添加","example":"The prefix directs the giving onto something.","exampleCN":"前缀把「给」引到某物之上。"},{"word":"additio","structure":"Latin noun from addere","meaning":"an adding","meaningCN":"添加","example":"The noun names the act the phrase marks.","exampleCN":"名词命名短语所标动作。"},{"word":"addition","structure":"English noun from additio","meaning":"the act or result of adding","meaningCN":"添加；增加物","example":"French carried the noun into Middle English.","exampleCN":"法语把这个名词带入中古英语。"},{"word":"add","structure":"English verb, back-formed from addition","meaning":"to put something more","meaningCN":"添加","example":"The short verb is the everyday base.","exampleCN":"短动词是日常基词。"},{"word":"additional","structure":"addition + -al","meaning":"extra","meaningCN":"额外的","example":"The adjective describes what is added.","exampleCN":"形容词描述被添加的部分。"},{"word":"additionally","structure":"additional + -ly","meaning":"in addition","meaningCN":"此外","example":"The adverb opens a further point.","exampleCN":"副词开启进一步论点。"},{"word":"in addition to","structure":"preposition + noun + preposition","meaning":"besides; as an extra","meaningCN":"除……之外还","example":"The phrase is the formal additive marker.","exampleCN":"这个短语是正式的累加标记。"}],"latinEntries":[{"word":"addere","structure":"addere, addo, addidi, additum (verb, third conjugation)","meaning":"to give to; to add","meaningCN":"给到；添加"},{"word":"dare","structure":"dare, do, dedi, datum (verb, first conjugation)","meaning":"to give","meaningCN":"给"}],"derivatives":[{"word":"add","pos":"v.","zh":"增加；添加"},{"word":"addition","pos":"n.","zh":"增加；加法"},{"word":"additional","pos":"adj.","zh":"额外的"},{"word":"additionally","pos":"adv.","zh":"此外；另外"},{"word":"additive","pos":"n./adj.","zh":"添加剂；附加的"}]}},{"word":"in conjunction with","ipa_uk":"/ɪn kənˈdʒʌŋkʃn wɪð/","ipa_us":"/ɪn kənˈdʒʌŋkʃn wɪð/","definition_zh":"与……共同；连同……一起（多用于正式、法律与技术文本）","definition_en":"together with another person, body or measure; used in formal, legal and technical writing","core_image":"两名工程师在同一台设备前同时插入两张授权卡","scene":"两名工程师在同一台设备前同时插入两张授权卡。The test was run in conjunction with the manufacturer.","sceneCN":"这里取「与……共同」（第 1 个义项：两方合作完成一件事）；句意为这项测试是与制造商共同进行的。","pos":[{"tag":"prep. phr.","zh":"介词短语：与……共同；连同……一起（正式）"}],"collocations":[{"phrase":"in conjunction with the manufacturer","zh":"与制造商共同"},{"phrase":"in conjunction with other measures","zh":"连同其他措施"},{"phrase":"work in conjunction with","zh":"与……协同工作"},{"phrase":"used in conjunction with","zh":"与……配合使用"},{"phrase":"in conjunction with local authorities","zh":"会同地方当局"},{"phrase":"in conjunction with the police","zh":"与警方联合"}],"forms":[{"label":"原形","form":"in conjunction with"},{"label":"后置用法","form":"run in conjunction with"},{"label":"被动结构","form":"be used in conjunction with"}],"derivatives":[{"word":"conjunction","pos":"n.","zh":"连词；结合"},{"word":"conjoin","pos":"v.","zh":"使结合"},{"word":"conjunctive","pos":"adj.","zh":"连接的；结合的"},{"word":"junction","pos":"n.","zh":"交叉点；接合处"},{"word":"jointly","pos":"adv.","zh":"共同地"}],"senses":[{"no":"01","title":"Working together with another party","titleCN":"与……共同（合作）","definition":"used to say that two parties carry out one task together","definitionCN":"表示两方共同完成同一项任务","example":"The test was run in conjunction with the manufacturer.","exampleCN":"这项测试是与制造商共同进行的。","why":"The phrase names a partner rather than a tool, so the two sides share responsibility for the same act.","whyCN":"这个短语点出的是伙伴而非工具，因此两方对同一动作共同负责。"},{"no":"02","title":"Combining two measures at once","titleCN":"连同……一并（措施并用）","definition":"used to say that one measure is applied together with another","definitionCN":"表示一项措施与另一项措施同时施用","example":"The drug was given in conjunction with rest and diet.","exampleCN":"这种药连同休息与饮食调整一并施用。","why":"Here the second item is not an agent but an accompanying measure, which shifts the phrase from partnership to combination.","whyCN":"此处第二项不是行动者，而是伴随措施，短语于是从「合作」转向「组合」。"},{"no":"03","title":"Technical pairing of devices or systems","titleCN":"技术语境：与……配合使用","definition":"used in manuals to say that one device or system must be used together with another","definitionCN":"在手册中说明某设备或系统须与另一设备配合使用","example":"The sensor works in conjunction with the control unit.","exampleCN":"这个传感器与控制单元配合工作。","why":"Technical writing uses the phrase to describe a required pairing rather than a temporary collaboration.","whyCN":"技术写作借此描述必需的配对，而非临时的协作。"},{"no":"04","title":"Joint handling under a contract","titleCN":"法律合同：连同……一并处理","definition":"in legal drafting, used to say that a matter is handled together with another provision or party","definitionCN":"在法律起草中，表示某事项与另一条款或另一方一并处理","example":"The claim was settled in conjunction with the earlier agreement.","exampleCN":"这项索赔是连同早先的协议一并解决的。","why":"Contracts use the phrase to bind two instruments into one settlement without merging them into a single clause.","whyCN":"合同借此把两份文书绑进同一处理，却不合并成一条。"},{"no":"05","title":"Official joint action","titleCN":"官方联合行动","definition":"used in official statements to name an authority acting together with another body","definitionCN":"在官方声明中点出某机构与另一机构共同行动","example":"The inquiry was opened in conjunction with local authorities.","exampleCN":"调查是会同地方当局启动的。","why":"Institutional prose needs to show shared authority without saying who leads, and the phrase keeps the balance.","whyCN":"机构文字需要显示共同授权、又不说明谁主导，这个短语保持平衡。"},{"no":"06","title":"Combined treatment in medicine","titleCN":"医学：联合用药、联合治疗","definition":"used in clinical writing to describe one treatment given together with another","definitionCN":"在临床写作中，描述一种治疗与另一种同时使用","example":"The therapy is most effective in conjunction with physical exercise.","exampleCN":"这种疗法与体育锻炼联合使用效果最好。","why":"Clinical writing distinguishes a single agent from a regimen, and the phrase marks the regimen.","whyCN":"临床写作要区分单一药物与联合方案，这个短语标出后者。"},{"no":"07","title":"The formal stand-in for a plain phrase","titleCN":"句末后置：正式替代「与……一起」","definition":"placed after the verb as a formal alternative to the plainer together with","definitionCN":"放在动词之后，作为更正式的说法替代日常的「与……一起」","example":"The two departments submitted the report in conjunction with each other.","exampleCN":"两个部门共同提交了这份报告。","why":"Trailing position keeps the main verb in focus while raising the register of the whole sentence.","whyCN":"后置让主要动词保持焦点，同时抬高整句语域。"},{"no":"08","title":"Joint sponsorship of an event","titleCN":"事件语境：联合主办、共同发布","definition":"used to name a second organization that shares the staging or issuing of something","definitionCN":"点出共同承办或共同发布的第二个组织","example":"The exhibition was opened in conjunction with the city museum.","exampleCN":"展览是与市博物馆联合举办的。","why":"Events and publications use the phrase to share credit between institutions without naming a hierarchy.","whyCN":"活动与出版物借此在机构间分摊功劳，而不排出高低。"}],"etymology":{"intro":{"en":"Conjunction comes from Latin coniunctio, from coniungere, to join together, itself con-, with, and iungere, to join, from the yoke root iug-. The Latin line is clear.","cn":"conjunction 来自拉丁语 coniunctio，词根 coniungere 意为「连在一起」，由 con-「共同」与 iungere「连接」构成，后者出自「轭」的词根 iug-。拉丁语线索清楚。"},"items":[{"era":"LATIN IUGUM","en":"Iugum, yoke, is the image behind the whole family: two things bound under one beam.","cn":"iugum 意为「轭」，是整族词的画面：两物被同一根横梁套住。"},{"era":"LATIN IUNGERE","en":"Iungere meant to join or unite, and supplied the verb behind conjunction.","cn":"iungere 意为连接、结合，提供了 conjunction 背后的动词。"},{"era":"LATIN CONIUNCTIO","en":"The noun named a joining together, in grammar as well as in general use.","cn":"这个名词指连在一起，既用于语法，也用于一般意义。"},{"era":"ENGLISH CONJUNCTION","en":"English conjunction appears in the Middle English period; the date is approximate.","cn":"英语 conjunction 见于中古英语，年代为约数。"},{"era":"THE FORMAL PHRASE","en":"The phrase with this preposition settles in modern legal, technical and official writing.","cn":"带这个介词的短语在近代法律、技术与官方文字中定型。"}]},"similar":{"note":{"en":"The first group shares the together-slot but stresses connection, compliance or plain accompaniment; the second group holds adverbs and phrases of shared action.","cn":"第一组同样表示「一起」，但侧重连接、遵守或单纯伴随；第二组是共同行动的副词与短语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"in connection with","ipa":"/ɪn kəˈnekʃn wɪð/","tag":"connection, often about a matter","definition":"It usually means concerning a matter, not acting together on it.","definitionCN":"它通常指「关于某事项」，而非共同去做。"},{"word":"in accordance with","ipa":"/ɪn əˈkɔːdəns wɪð/","tag":"compliance, not partnership","definition":"It names a rule being followed and never a partner.","definitionCN":"它点出所遵循的规则，从不点出伙伴。"},{"word":"together with","ipa":"/təˈɡeðə wɪð/","tag":"plain accompaniment","definition":"It is the everyday phrase for accompanying items and carries no institutional weight.","definitionCN":"它是最平常的伴随说法，没有机构分量。"},{"word":"along with","ipa":"/əˈlɒŋ wɪð/","tag":"neutral accompaniment","definition":"It adds a companion item in neutral prose.","definitionCN":"在中性文字中追加伴随项。"}]},{"heading":"NEAR MEANING","entries":[{"word":"jointly","ipa":"/ˈdʒɔɪntli/","tag":"shared responsibility","definition":"It states that two parties share an act, usually without naming them.","definitionCN":"说明两方共担一事，通常不点名。"},{"word":"in partnership with","ipa":"/ɪn ˈpɑːtnəʃɪp wɪð/","tag":"commercial cooperation","definition":"It stresses a business relationship rather than a single shared task.","definitionCN":"强调商业关系，而非单次共同任务。"},{"word":"combined with","ipa":"/kəmˈbaɪnd wɪð/","tag":"measures merged","definition":"It describes two measures merged into one effect.","definitionCN":"描述两项措施合并为一个效果。"},{"word":"in coordination with","ipa":"/ɪn kəʊˌɔːdɪˈneɪʃn wɪð/","tag":"synchronized action","definition":"It stresses timing and organization rather than shared credit.","definitionCN":"强调时机与组织协调，而非共同署名。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real yoke root, the real partners and the real register.","cn":"正常联想用真实「轭」词根、真实伙伴与真实语域。"},"normal":[{"en":"A yoke binds two animals under one beam, and the word keeps that picture of joint work.","cn":"轭把两头牲口套在同一横梁下，这个词保留了共同劳作的画面。"},{"en":"It is formal: contracts, manuals and official notices use it, not lunchtime chat.","cn":"它很正式：合同、手册与官方通告用它，午饭闲谈不用。"},{"en":"The partner may be a company, an agency, a treatment or a measure.","cn":"伙伴可以是公司、机构、疗法或措施。"},{"en":"It differs from compliance: a rule is followed, a partner acts alongside.","cn":"它与「遵守」不同：规则被遵循，伙伴则并肩行动。"},{"en":"At the end of a clause it raises the tone of the whole sentence.","cn":"放在从句末尾，它会抬高整句语气。"}],"abstract":[{"en":"Like two keys turned in two locks at the same moment.","cn":"像两把钥匙在同一刻转动两把锁。"},{"en":"Like two beams tied under one yoke so they pull together.","cn":"像两根梁被同一副轭套住，一起发力。"},{"en":"Like two signatures on one page, neither above the other.","cn":"像同一页上的两个签名，谁也不比谁高。"}]},"examples":[{"en":"The survey was designed in conjunction with two local hospitals.","cn":"这项调查是与两家地方医院共同设计的。"},{"en":"The software must be installed in conjunction with the driver.","cn":"这个软件必须与驱动程序配合安装。"},{"en":"The campaign was launched in conjunction with the health ministry.","cn":"这场活动是与卫生部联合发起的。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「因 肯琼克申 威斯」——两把钥匙同时转两把锁：与……共同","word":"in conjunction with"},"root":"conjunction 来自拉丁语 coniunctio，词根 coniungere「连在一起」由 con-「共同」与 iungere「连接」构成，后者出自「轭」词根 iug-；短语 in conjunction with 在近代法律、技术与官方文字中定型，首见年代为约数。","sensesIntro":{"en":"Eight senses split by the second term: a partner, an accompanying measure, a paired device, a contract instrument, an official body, a treatment, a trailing formal phrase, and a co-sponsor.","cn":"八个义项按第二项的性质区分：伙伴、伴随措施、配对设备、合同文书、官方机构、治疗方案、句末正式替代、共同主办方。"},"semanticMap":{"core":{"en":"CORE IMAGE: two authorization cards inserted into one machine at the same moment.","cn":"核心意象：两张授权卡在同一刻插入同一台设备。"},"chain":["YOKE TOGETHER","PARTNER","MEASURE PLUS MEASURE","PAIRED SYSTEM","CONTRACT","JOINT EVENT"],"branches":[{"senses":"01 · 05 · 08","en":"THE PARTNER: a company, an authority or a co-sponsor acts alongside.","cn":"伙伴：公司、机构或共同主办方并肩行动。"},{"senses":"02 · 06","en":"THE REGIMEN: measures and treatments are applied together.","cn":"方案：措施与疗法一并施用。"},{"senses":"03","en":"THE PAIRING: a device requires another unit to work.","cn":"配对：设备需要另一单元才能工作。"},{"senses":"04","en":"THE INSTRUMENT: two legal documents are settled as one matter.","cn":"文书：两份法律文件作为一事处理。"},{"senses":"07","en":"THE REGISTER: trailing position makes plain accompaniment formal.","cn":"语域：后置把日常伴随抬成正式说法。"}]},"affixes":{"intro":{"en":"The phrase joins a Latin noun of yoking with an English preposition; the yoke root is the core image.","cn":"这个短语把拉丁语「套轭」名词与英语介词结合；轭词根是核心画面。"},"latinIntro":{"en":"The Latin etyma are iungere, to join, and iugum, yoke; coniunctio is the noun built on them.","cn":"拉丁语词源是 iungere「连接」与 iugum「轭」；coniunctio 是在其上构成的名词。"},"items":[{"word":"iugum","structure":"Latin noun, second declension","meaning":"yoke","meaningCN":"轭","example":"The yoke binds two animals to one beam.","exampleCN":"轭把两头牲口绑到一根横梁上。"},{"word":"iungere","structure":"Latin verb, third conjugation","meaning":"to join; to unite","meaningCN":"连接；结合","example":"The verb supplies the action of the family.","exampleCN":"这个动词提供该词族的动作。"},{"word":"coniungere","structure":"con- + iungere","meaning":"to join together","meaningCN":"连在一起","example":"The prefix adds the idea of two sides meeting.","exampleCN":"前缀加进两方会合之意。"},{"word":"coniunctio","structure":"Latin noun from coniungere","meaning":"a joining together","meaningCN":"连在一起","example":"Grammar borrowed the noun for the joining word.","exampleCN":"语法借这个名词指连接词。"},{"word":"conjunction","structure":"English noun","meaning":"a joining; a connecting word","meaningCN":"结合；连词","example":"English keeps both the general and the grammatical sense.","exampleCN":"英语保留一般义与语法义。"},{"word":"conjoin","structure":"con- + join (verb)","meaning":"to join together","meaningCN":"使结合","example":"The short verb is the everyday base.","exampleCN":"短动词是日常基词。"},{"word":"junction","structure":"Latin iunctio through French","meaning":"a joining point","meaningCN":"接合处","example":"The word names where two lines meet.","exampleCN":"这个词指两条线相接之处。"},{"word":"in conjunction with","structure":"preposition + noun + preposition","meaning":"together with","meaningCN":"与……共同","example":"The phrase is the formal marker of joint action.","exampleCN":"这个短语是共同行动的正式标记。"}],"latinEntries":[{"word":"iungere","structure":"iungere, iungo, iunxi, iunctum (verb, third conjugation)","meaning":"to join","meaningCN":"连接"},{"word":"iugum","structure":"iugum, -i (noun, second declension)","meaning":"yoke","meaningCN":"轭"}],"derivatives":[{"word":"conjunction","pos":"n.","zh":"连词；结合"},{"word":"conjoin","pos":"v.","zh":"使结合"},{"word":"conjunctive","pos":"adj.","zh":"连接的；结合的"},{"word":"junction","pos":"n.","zh":"交叉点；接合处"},{"word":"jointly","pos":"adv.","zh":"共同地"}]}},{"word":"in light of","ipa_uk":"/ɪn ˈlaɪt əv/","ipa_us":"/ɪn ˈlaɪt əv/","definition_zh":"鉴于；考虑到；依据（新信息或事实）重新判断","definition_en":"after considering or because of new information; used to justify a judgement or decision","core_image":"刚送达的检测报告被放在旧卷宗上面，办案人重新翻看","scene":"检察官把刚送达的检测报告放在桌上，重新翻看旧卷宗。The verdict was reviewed in light of the new evidence.","sceneCN":"这里取「鉴于、考虑到」（第 1 个义项：依据新出现的信息）；句意为判决依据新证据被重新审议。","pos":[{"tag":"prep. phr.","zh":"介词短语：鉴于；考虑到（正式）"},{"tag":"adv. phr.","zh":"状语用法：依据……来看"}],"collocations":[{"phrase":"in light of the evidence","zh":"鉴于证据"},{"phrase":"in light of recent events","zh":"鉴于近期事件"},{"phrase":"in light of this","zh":"有鉴于此"},{"phrase":"in light of what happened","zh":"考虑到所发生的事"},{"phrase":"in light of the findings","zh":"根据调查结果"},{"phrase":"reconsider in light of","zh":"鉴于……而重新考虑"}],"forms":[{"label":"原形","form":"in light of"},{"label":"英式变体","form":"in the light of"},{"label":"从句搭配","form":"in light of what happened"}],"derivatives":[{"word":"light","pos":"n./adj.","zh":"光；光线；明亮的"},{"word":"lighten","pos":"v.","zh":"照亮；减轻"},{"word":"enlighten","pos":"v.","zh":"启发；使明白"},{"word":"lighting","pos":"n.","zh":"照明"},{"word":"lightness","pos":"n.","zh":"轻；明亮"}],"senses":[{"no":"01","title":"Considering newly arrived information","titleCN":"句首：鉴于（新信息）","definition":"placed at the start of a sentence to say that a judgement has been revised because of new information","definitionCN":"置于句首，表示由于新信息而修正了判断","example":"In light of the new evidence, the verdict was reviewed.","exampleCN":"鉴于新证据，判决被重新审议。","why":"The image of light makes the information something that illuminates what was already there, so the judgement changes without the old facts disappearing.","whyCN":"「光」的意象让新信息照亮已有事实，因此判断改变而旧事实并不消失。"},{"no":"02","title":"Weighing a known fact","titleCN":"后接名词：考虑到","definition":"used before a noun to say that a fact was taken into account","definitionCN":"用在名词前，表示某一事实已被纳入考虑","example":"In light of the cost, the plan was shortened.","exampleCN":"考虑到成本，计划被缩短了。","why":"A noun after the phrase is the plainest use: the fact is named, and the decision follows from it.","whyCN":"短语后接名词是最朴素的用法：点出事实，决定随之而来。"},{"no":"03","title":"Reassessing an earlier decision","titleCN":"基于……重新评估","definition":"used with verbs of review to say that an earlier decision is being tested against new material","definitionCN":"与「复审」类动词连用，表示用新材料检验早先的决定","example":"The policy was reassessed in light of the latest figures.","exampleCN":"依据最新数据，这项政策被重新评估。","why":"Review verbs and the phrase form a natural pair because both look backward at a decision and forward to a revision.","whyCN":"复审动词与这个短语天然成对，因为两者都回看旧决定、前瞻新修正。"},{"no":"04","title":"Looking back after an event","titleCN":"事后回看：依据已发生的事","definition":"used after an event to judge what was done with the benefit of hindsight","definitionCN":"在事件发生之后使用，带着事后眼光评判当时的做法","example":"In light of what happened, the rule was tightened.","exampleCN":"考虑到所发生的事，规则被收紧了。","why":"Hindsight is exactly the light the phrase names: the facts are old, but their meaning has changed.","whyCN":"「事后眼光」正是这个短语所指的光：事实是旧的，意义却已改变。"},{"no":"05","title":"Justifying a decision","titleCN":"决策语境：依据……作出决定","definition":"used to present the reason that makes a decision defensible","definitionCN":"用来陈述使某项决定站得住脚的理由","example":"The committee acted in light of the risks involved.","exampleCN":"委员会依据所涉风险采取了行动。","why":"In decisions the phrase supplies the formal reason, which is why it appears in minutes and reports.","whyCN":"在决定中，这个短语提供正式理由，因此常出现在会议记录与报告里。"},{"no":"06","title":"The formal cousin of a plain causal phrase","titleCN":"语域：比口语因果说法更正式","definition":"in formal prose it replaces the plainer because of, adding the idea of a standard being consulted","definitionCN":"在正式文字中替代更口语的因果说法，并加进「参照某标准」之意","example":"In light of the delay, the deadline was extended.","exampleCN":"鉴于延误，截止日期被延后。","why":"The phrase does not merely give a cause; it presents the cause as something weighed before acting.","whyCN":"这个短语不只是给出原因，而是把原因摆出来称量之后才行动。"},{"no":"07","title":"Interpreting a text by its context","titleCN":"学术与法律：依循……解释条文","definition":"used in scholarship and law to say that a passage is read with a wider context in mind","definitionCN":"在学术与法律中，表示参照更广的背景来读某段文字","example":"The clause was read in light of the treaty's purpose.","exampleCN":"该条款是参照条约目的来解读的。","why":"Interpretation needs a phrase that brings background to bear without rewriting the text, and this one does that.","whyCN":"解释需要一个把背景带进来、又不改写文本的说法，这个短语正是。"},{"no":"08","title":"A trailing statement of grounds","titleCN":"句末后置：说明判断依据","definition":"placed at the end of a clause to add the grounds after the judgement has been stated","definitionCN":"放在从句末尾，在判断之后补出依据","example":"The schedule was changed, in light of the weather.","exampleCN":"日程被改了，依据是天气情况。","why":"Final position lets the judgement land first and the grounds follow as an explanation rather than a precondition.","whyCN":"后置让判断先落地，依据随后作为解释，而非前提。"}],"etymology":{"intro":{"en":"Light is a native Old English noun of Germanic origin, and there is no Latin element in the phrase. The figurative sense of considering something by the light it throws is modern; dates are approximate.","cn":"light 是古英语本族名词，属日耳曼语，整个短语没有拉丁语成分。用「它照出的光」比喻「据此考量」是近代引申；年代为约数。"},"items":[{"era":"OLD ENGLISH LEOHT","en":"The noun goes back to Old English leoht, light, a Germanic word with no Latin ancestor.","cn":"这个名词可追溯到古英语 leoht「光」，属日耳曼语，没有拉丁语祖先。"},{"era":"SIGHT AND UNDERSTANDING","en":"English has long used light for understanding, as in a light on the problem.","cn":"英语早已用「光」指理解，例如「照亮问题」。"},{"era":"THE PHRASE ARISES","en":"The prepositional phrase with this noun develops in modern written English; the exact date is approximate.","cn":"带这个名词的介词短语在近代书面英语中发展出来，确切年代为约数。"},{"era":"FORMAL REGISTER","en":"The phrase settles in official, legal and academic prose rather than in speech.","cn":"这个短语定型于官方、法律与学术文字，而非口语。"},{"era":"BRITISH VARIANT","en":"British writing often inserts the definite article, while the shorter form dominates elsewhere.","cn":"英式文字常加定冠词，其他地区则多用较短形式。"}]},"similar":{"note":{"en":"The first group also looks at information before judging but differs in source or timing; the second group holds plainer causal and evaluative phrases.","cn":"第一组同样在判断前查看信息，但来源或时点不同；第二组是更朴素的因果与评断说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"in view of","ipa":"/ɪn vjuː əv/","tag":"same picture, plainer","definition":"It uses sight rather than light for the same weighing of facts.","definitionCN":"它用「看」而非「光」来承担同样的权衡。"},{"word":"in the light of","ipa":"/ɪn ðə ˈlaɪt əv/","tag":"British variant","definition":"The longer British form has the same meaning and a slightly heavier tone.","definitionCN":"更长的英式形式意义相同，语气略重。"},{"word":"in the wake of","ipa":"/ɪn ðə weɪk əv/","tag":"after and because of","definition":"It stresses that something follows an event in time, often a disruption.","definitionCN":"它强调某事在事件之后发生，常指混乱之后。"},{"word":"in terms of","ipa":"/ɪn ˈtɜːmz əv/","tag":"dimension, not grounds","definition":"It names the measure being used rather than the reason for a judgement.","definitionCN":"它点出所用的衡量维度，而非判断理由。"}]},{"heading":"NEAR MEANING","entries":[{"word":"given","ipa":"/ˈɡɪvn/","tag":"compact preposition","definition":"It takes a fact as a starting point in fewer words.","definitionCN":"用更少的词把一个事实当作起点。"},{"word":"considering","ipa":"/kənˈsɪdərɪŋ/","tag":"evaluative preposition","definition":"It weighs a fact when forming a judgement, often about quality.","definitionCN":"在形成判断时权衡事实，常关乎优劣。"},{"word":"because of","ipa":"/bɪˈkɒz əv/","tag":"plain cause","definition":"It states a cause directly, without the idea of consulting a standard.","definitionCN":"直接陈述原因，不含「参照标准」之意。"},{"word":"on the basis of","ipa":"/ɒn ðə ˈbeɪsɪs əv/","tag":"explicit foundation","definition":"It names the foundation on which a decision rests.","definitionCN":"点出决定所依托的基础。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real native noun, the real image of illumination and the real register.","cn":"正常联想用真实本族名词、真实照明意象与真实语域。"},"normal":[{"en":"Light makes what is already there visible, so new facts change the reading of old ones.","cn":"光让已有之物显形，所以新事实改变旧事的读法。"},{"en":"It takes a noun or a question clause, not a bare statement.","cn":"它接名词或疑问从句，不接光秃秃的陈述。"},{"en":"It pairs naturally with verbs of review and reconsideration.","cn":"它天然与复审、重新考虑类动词配对。"},{"en":"It is formal: minutes, judgments and papers use it.","cn":"它很正式：会议记录、判决与论文用它。"},{"en":"Its everyday cousins are because of and given.","cn":"它的日常表亲是「因为」与「鉴于」。"}],"abstract":[{"en":"Like a lamp switched on over an old photograph, showing details that were always there.","cn":"像一盏灯照在旧照片上，显出一直都在的细节。"},{"en":"Like a window opened in a dim room just before a decision is made.","cn":"像做决定前，在一间暗屋里推开一扇窗。"},{"en":"Like a second pair of eyes arriving after the first judgement was written.","cn":"像第一份判断写完之后，又来了第二双眼睛。"}]},"examples":[{"en":"In light of the new figures, the forecast was revised downward.","cn":"鉴于新数据，预测被下调。"},{"en":"The rule was relaxed in light of the burden it placed on small firms.","cn":"考虑到给小企业造成的负担，规则被放宽了。"},{"en":"In light of what happened, the committee reopened the case.","cn":"考虑到所发生的事，委员会重新立案。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「因 赖特 奥夫」——灯照旧照片，细节忽然显出来：鉴于、考虑到","word":"in light of"},"root":"light 是古英语本族名词，属日耳曼语，短语没有拉丁语成分；用「照出的光」比喻「据此考量」是近代引申，首见年代为约数。","sensesIntro":{"en":"Eight senses split by the material weighed and the moment of judging: new information, a known fact, a review, hindsight, a decision, formal register, textual interpretation, and trailing grounds.","cn":"八个义项按所权衡的材料与判断时点区分：新信息、已知事实、复审、事后回看、决策、正式语域、条文解释、句末依据。"},"semanticMap":{"core":{"en":"CORE IMAGE: a lamp switched on over an old file, revealing details already there.","cn":"核心意象：一盏灯照在旧卷宗上，显出本就存在的细节。"},"chain":["LIGHT","NEW INFORMATION","KNOWN FACT","REVIEW","HINDSIGHT","GROUNDS"],"branches":[{"senses":"01 · 04","en":"THE NEW LIGHT: fresh information or hindsight changes how old facts read.","cn":"新光：新信息或事后眼光改变旧事实的读法。"},{"senses":"02 · 05","en":"THE WEIGHING: a known fact is taken into account before a decision.","cn":"权衡：已知事实在做决定前被纳入考虑。"},{"senses":"03","en":"THE REVIEW: earlier decisions are tested against new material.","cn":"复审：早先决定用新材料检验。"},{"senses":"06 · 07","en":"THE REGISTER: formal prose and textual interpretation use the phrase as a frame.","cn":"语域：正式文字与条文解释把它当框架。"},{"senses":"08","en":"THE GROUNDS: trailing position states the reason after the judgement.","cn":"依据：后置在判断之后补出理由。"}]},"affixes":{"intro":{"en":"The phrase is native English in both halves; no Latin element is involved.","cn":"这个短语前后两半都是英语本族成分；不涉及拉丁语。"},"latinIntro":{"en":"There is no Latin etymon here: the noun is Old English and the preposition is native.","cn":"这里没有拉丁语词源：名词是古英语，介词也是本族成分。"},"items":[{"word":"leoht","structure":"Old English noun","meaning":"light","meaningCN":"光","example":"The word is Germanic and has no Latin ancestor.","exampleCN":"这个词属日耳曼语，没有拉丁语祖先。"},{"word":"light","structure":"English noun and adjective","meaning":"light; not heavy; bright","meaningCN":"光；轻的；明亮的","example":"English keeps the noun and a separate adjective of weight.","exampleCN":"英语保留名词，另有表重量的形容词。"},{"word":"lighten","structure":"light + -en (verb)","meaning":"to make brighter; to reduce weight","meaningCN":"照亮；减轻","example":"The suffix makes a verb with two distinct senses.","exampleCN":"后缀造出两个不同意义的动词。"},{"word":"enlighten","structure":"en- + lighten","meaning":"to inform; to free from ignorance","meaningCN":"启发；使明白","example":"The prefix turns brightness into understanding.","exampleCN":"前缀把明亮转为理解。"},{"word":"lighting","structure":"light + -ing (noun)","meaning":"a system of lights","meaningCN":"照明","example":"The noun names an arrangement of lamps.","exampleCN":"名词指灯具的安排。"},{"word":"lightness","structure":"light + -ness","meaning":"brightness; low weight","meaningCN":"明亮；轻","example":"The suffix names a quality of either sense.","exampleCN":"后缀指两种意义之一的性质。"},{"word":"in light of","structure":"preposition + noun + preposition","meaning":"considering","meaningCN":"鉴于","example":"The phrase is formal and written.","exampleCN":"这个短语正式且书面。"},{"word":"light-year","structure":"light + year (compound)","meaning":"a distance in astronomy","meaningCN":"光年","example":"The compound shows how far the light image travels.","exampleCN":"复合词显示「光」的意象能走多远。"}],"latinEntries":[],"derivatives":[{"word":"light","pos":"n./adj.","zh":"光；光线；明亮的"},{"word":"lighten","pos":"v.","zh":"照亮；减轻"},{"word":"enlighten","pos":"v.","zh":"启发；使明白"},{"word":"lighting","pos":"n.","zh":"照明"},{"word":"lightness","pos":"n.","zh":"轻；明亮"}]}},{"word":"in response to","ipa_uk":"/ɪn rɪˈspɒns tuː/","ipa_us":"/ɪn rɪˈspɑːns tuː/","definition_zh":"作为对……的回应；为回应……；针对……（作出反应）","definition_en":"as an answer or reaction to something said, done or experienced","core_image":"服务台收到一封投诉信，主管当天就拟好回复","scene":"服务台收到一封投诉信，主管当天就拟好回复。The company changed its policy in response to customer complaints.","sceneCN":"这里取「回应投诉」（第 3 个义项：针对批评或投诉作出反应）；句意为公司因客户投诉而改变了政策。","pos":[{"tag":"prep. phr.","zh":"介词短语：作为对……的回应；针对……"}],"collocations":[{"phrase":"in response to a question","zh":"回应提问"},{"phrase":"in response to complaints","zh":"回应投诉"},{"phrase":"in response to the crisis","zh":"应对危机"},{"phrase":"in response to treatment","zh":"对治疗的反应"},{"phrase":"in response to your letter","zh":"针对来函"},{"phrase":"in response to pressure","zh":"回应压力"}],"forms":[{"label":"原形","form":"in response to"},{"label":"后置用法","form":"act in response to"},{"label":"被动结构","form":"be issued in response to"}],"derivatives":[{"word":"respond","pos":"v.","zh":"回应；作答"},{"word":"response","pos":"n.","zh":"回应；反应"},{"word":"responsive","pos":"adj.","zh":"反应灵敏的"},{"word":"respondent","pos":"n.","zh":"受访者；应答者"},{"word":"responsiveness","pos":"n.","zh":"响应度"}],"senses":[{"no":"01","title":"Answering a question or request","titleCN":"回应问题、请求","definition":"used to say that something is said or done as an answer","definitionCN":"表示某话或某动作是作为回答而作出","example":"The note was written in response to a direct question.","exampleCN":"这张便条是针对一个直接提问写的。","why":"The phrase points backward to a stimulus and forward to the answer, so it naturally follows verbs of replying.","whyCN":"这个短语向后指向刺激、向前指向回答，因此天然跟在答复类动词之后。"},{"no":"02","title":"Reacting to an event","titleCN":"作为对……的反应（事件）","definition":"used to describe a reaction to something that has happened rather than a verbal answer","definitionCN":"描述对已发生之事的反应，而非口头回答","example":"Prices fell in response to the announcement.","exampleCN":"价格因这项公告而下跌。","why":"Here the answer is not words but a change in behaviour, which widens the phrase beyond conversation.","whyCN":"此处的回应不是言语，而是行为变化，于是短语超出会话范围。"},{"no":"03","title":"Answering criticism or complaints","titleCN":"针对投诉、批评","definition":"used when an organization reacts to complaints or public criticism","definitionCN":"在机构对投诉或公众批评作出反应时使用","example":"The company changed its policy in response to customer complaints.","exampleCN":"公司因客户投诉而改变了政策。","why":"Institutional writing uses the phrase to show that a change was forced by outside pressure, not chosen freely.","whyCN":"机构文字借此显示改变由外部压力促成，而非自由选择。"},{"no":"04","title":"Reacting to medical treatment","titleCN":"医学：对治疗的反应","definition":"used in clinical writing to describe how a body or illness reacts to treatment","definitionCN":"在临床写作中，描述身体或疾病对治疗的反应","example":"The tumour shrank in response to the new drug.","exampleCN":"肿瘤对这种新药产生了反应而缩小。","why":"Clinical prose needs a neutral way to describe improvement or failure without naming a cause with certainty.","whyCN":"临床文字需要一个中性说法，不确定地描述好转或无效。"},{"no":"05","title":"Policy reaction to pressure or prices","titleCN":"市场与政策：应对压力、价格","definition":"used to describe a policy move taken because of market or political pressure","definitionCN":"描述因市场或政治压力而采取的政策动作","example":"Interest rates were raised in response to rising prices.","exampleCN":"为应对物价上涨，利率被提高。","why":"Policy writing uses the phrase to tie a measure to a pressure without claiming that the pressure was the only cause.","whyCN":"政策文字借此把措施与压力挂钩，又不宣称压力是唯一原因。"},{"no":"06","title":"The news-style opening","titleCN":"句首状语（新闻体）","definition":"placed at the start of a report to name the trigger before the action","definitionCN":"置于报道开头，先点名触发因素，再说行动","example":"In response to the outbreak, the city closed its schools.","exampleCN":"针对疫情暴发，这座城市关闭了学校。","why":"News prose front-loads the trigger so the action reads as a consequence, which is why the phrase often opens a sentence.","whyCN":"新闻文字把触发因素前置，使行动读起来像结果，因此这个短语常开句。"},{"no":"07","title":"Replying to a letter or request in official style","titleCN":"公文信函：针对来函","definition":"used at the start of official correspondence to name the letter being answered","definitionCN":"在公函开头点出所答复的来信","example":"In response to your letter of the fifth, we enclose the file.","exampleCN":"针对你方五日来函，随信附上档案。","why":"Official letters need a formula that names the incoming document without repeating its contents.","whyCN":"公函需要一个套语，点出来文而不重复其内容。"},{"no":"08","title":"A bodily reaction to a stimulus","titleCN":"生理：对刺激的反应","definition":"used in science to describe a living system's reaction to a stimulus","definitionCN":"在科学文字中，描述生命系统对刺激的反应","example":"The pupil narrows in response to bright light.","exampleCN":"瞳孔对强光作出反应而收缩。","why":"Scientific writing uses the phrase for automatic reactions that need no intention behind them.","whyCN":"科学文字借此描述无需意图的自动反应。"}],"etymology":{"intro":{"en":"Response comes from Latin responsum, from respondere, to answer, itself re-, back, and spondere, to pledge. The Latin line is clear; the English phrase is modern.","cn":"response 来自拉丁语 responsum，词根 respondere 意为「回答」，由 re-「回」与 spondere「承诺」构成。拉丁语线索清楚，英语短语属近代。"},"items":[{"era":"LATIN SPONDERE","en":"Spondere meant to pledge or promise, and survives in sponsor and spouse.","cn":"spondere 意为许诺、承诺，仍见于 sponsor 与 spouse。"},{"era":"LATIN RESPONDERE","en":"Respondere meant to answer, literally to pledge back.","cn":"respondere 意为回答，字面是「回以承诺」。"},{"era":"LATIN RESPONSUM","en":"The noun named the answer given, and Old French response carried it to English.","cn":"这个名词指给出的回答，古法语 response 把它带入英语。"},{"era":"ENGLISH RESPONSE","en":"English response appears in the Middle English period; the date is approximate.","cn":"英语 response 见于中古英语，年代为约数。"},{"era":"THE MODERN PHRASE","en":"The phrase with this preposition and to settles in modern official and scientific writing.","cn":"带这个介词与 to 的短语在近代官方与科学文字中定型。"}]},"similar":{"note":{"en":"The first group also points to a trigger but stresses connection, cause or rejection; the second group holds plainer phrases of reaction.","cn":"第一组同样指向触发因素，但侧重关联、原因或拒斥；第二组是更朴素的反应说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"in reaction to","ipa":"/ɪn riˈækʃn tuː/","tag":"reaction, often emotional","definition":"It stresses a response to a stimulus, often immediate and emotional.","definitionCN":"它强调对刺激的反应，常是即时且情绪化的。"},{"word":"in reply to","ipa":"/ɪn rɪˈplaɪ tuː/","tag":"verbal answer only","definition":"It is used for words in return, especially in letters.","definitionCN":"它只用于回话，尤见于书信。"},{"word":"in answer to","ipa":"/ɪn ˈɑːnsə tuː/","tag":"formal reply","definition":"It is a formal way to name the question being answered.","definitionCN":"正式点出所回答的问题。"},{"word":"in relation to","ipa":"/ɪn rɪˈleɪʃn tuː/","tag":"relation, not reply","definition":"It links two matters without any answering.","definitionCN":"它只连接两件事，不含回答。"}]},{"heading":"NEAR MEANING","entries":[{"word":"as a reaction","ipa":"/æz ə riˈækʃn/","tag":"plain paraphrase","definition":"It describes a response without naming the trigger as a prepositional object.","definitionCN":"描述反应，但不把触发因素作介词宾语。"},{"word":"reacting to","ipa":"/riˈæktɪŋ tuː/","tag":"participial frame","definition":"It turns the response into an action in progress.","definitionCN":"把回应写成正在进行的动作。"},{"word":"owing to","ipa":"/ˈəʊɪŋ tuː/","tag":"cause, not answer","definition":"It gives a cause and has no answering sense.","definitionCN":"它给出原因，没有回答之意。"},{"word":"on account of","ipa":"/ɒn əˈkaʊnt əv/","tag":"formal cause","definition":"It explains why something happened rather than what it answers.","definitionCN":"解释事情为何发生，而非回应什么。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real pledge root, the real trigger types and the real register.","cn":"正常联想用真实「承诺」词根、真实触发类型与真实语域。"},"normal":[{"en":"To respond is to pledge back, so the word carries an answer returned to a source.","cn":"回应就是回以承诺，因此这个词带着一个还回源头的答复。"},{"en":"It takes a noun, never a clause.","cn":"它接名词，从不接从句。"},{"en":"The trigger may be a question, a complaint, a price, a drug or a light.","cn":"触发因素可以是提问、投诉、价格、药物或光。"},{"en":"It is neutral about cause: the phrase ties a reaction to a trigger without proving it.","cn":"它对因果保持中性：把反应与触发因素挂钩，却不证明因果。"},{"en":"News and official prose front it so the action reads as a consequence.","cn":"新闻与公文常把它前置，使行动读作结果。"}],"abstract":[{"en":"Like a letter arriving and an answer leaving the same desk on the same day.","cn":"像一封信送到，当天同一张桌上就有回信发出。"},{"en":"Like a thermostat switching on because the room turned cold.","cn":"像恒温器因屋子变冷而启动。"},{"en":"Like an echo that returns only to the wall it came from.","cn":"像只朝来处返回的回声。"}]},"examples":[{"en":"The firm issued a statement in response to the rumours.","cn":"公司针对谣言发表了一份声明。"},{"en":"In response to the drought, the city limited water use.","cn":"为应对旱情，城市限制了用水。"},{"en":"The patient improved in response to the second course of treatment.","cn":"病人在第二个疗程后有所好转。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「因 瑞斯庞斯 图」——信一到，回信当天就走：作为回应","word":"in response to"},"root":"response 来自拉丁语 responsum，词根 respondere「回答」由 re-「回」与 spondere「承诺」构成，经古法语进入英语；短语 in response to 在近代官方与科学文字中定型，首见年代为约数。","sensesIntro":{"en":"Eight senses split by the trigger and the kind of answer: a question, an event, a complaint, a treatment, a market pressure, a news opening, an official letter, and a bodily stimulus.","cn":"八个义项按触发因素与回应方式区分：提问、事件、投诉、治疗、市场压力、新闻开头、公函来文、生理刺激。"},"semanticMap":{"core":{"en":"CORE IMAGE: a complaint letter arriving and a reply leaving the same desk the same day.","cn":"核心意象：投诉信送到，当天同一张桌上发出回信。"},"chain":["PLEDGE BACK","ANSWER","REACTION","COMPLAINT","POLICY","STIMULUS"],"branches":[{"senses":"01 · 07","en":"THE ANSWER: questions and official letters receive a direct reply.","cn":"回答：提问与公函得到直接答复。"},{"senses":"02","en":"THE EVENT: an action is tied to what set it off.","cn":"事件：行动被绑到引发它的事情上。"},{"senses":"03 · 05","en":"THE PRESSURE: complaints and market moves force a policy change.","cn":"压力：投诉与市场变动迫使政策改变。"},{"senses":"04 · 08","en":"THE BODY: treatment and stimuli produce reactions without intention.","cn":"身体：治疗与刺激产生无意图的反应。"},{"senses":"06","en":"THE FRAME: fronting makes the action read as a consequence.","cn":"框架：前置使行动读作结果。"}]},"affixes":{"intro":{"en":"The phrase joins a Latin noun of answering with an English preposition; the Latin core is clear.","cn":"这个短语把拉丁语「回答」名词与英语介词结合；拉丁核心清楚。"},"latinIntro":{"en":"The Latin etyma are respondere, to answer, and spondere, to pledge.","cn":"拉丁语词源是 respondere「回答」与 spondere「承诺」。"},"items":[{"word":"spondere","structure":"Latin verb, second conjugation","meaning":"to pledge; to promise","meaningCN":"许诺；承诺","example":"The verb also underlies sponsor and spouse.","exampleCN":"这个动词也是另外两个英语词的基础。"},{"word":"respondere","structure":"re- + spondere","meaning":"to answer; to pledge back","meaningCN":"回答；回以承诺","example":"The prefix sends the pledge back to its source.","exampleCN":"前缀把承诺送回源头。"},{"word":"responsum","structure":"Latin noun from respondere","meaning":"an answer","meaningCN":"回答","example":"The noun names the reply itself.","exampleCN":"名词直接指答复。"},{"word":"response","structure":"English noun through Old French","meaning":"an answer or reaction","meaningCN":"回答；反应","example":"English widened the noun to include reactions.","exampleCN":"英语把名词扩展到反应。"},{"word":"respond","structure":"English verb","meaning":"to answer; to react","meaningCN":"回答；反应","example":"The verb is the everyday base.","exampleCN":"动词是日常基词。"},{"word":"responsive","structure":"response + -ive","meaning":"quick to react","meaningCN":"反应灵敏的","example":"The suffix turns the noun into a quality.","exampleCN":"后缀把名词变成性质。"},{"word":"respondent","structure":"respond + -ent","meaning":"one who answers","meaningCN":"应答者；受访者","example":"The suffix names the person answering.","exampleCN":"后缀指作出回答的人。"},{"word":"in response to","structure":"preposition + noun + preposition","meaning":"as an answer to","meaningCN":"作为对……的回应","example":"The phrase is standard in official and scientific prose.","exampleCN":"这个短语在官方与科学文字中是标准用法。"}],"latinEntries":[{"word":"respondere","structure":"respondere, respondeo, respondi, responsum (verb, second conjugation)","meaning":"to answer","meaningCN":"回答"},{"word":"spondere","structure":"spondere, spondeo, spopondi, sponsum (verb, second conjugation)","meaning":"to pledge","meaningCN":"承诺"}],"derivatives":[{"word":"respond","pos":"v.","zh":"回应；作答"},{"word":"response","pos":"n.","zh":"回应；反应"},{"word":"responsive","pos":"adj.","zh":"反应灵敏的"},{"word":"respondent","pos":"n.","zh":"受访者；应答者"},{"word":"responsiveness","pos":"n.","zh":"响应度"}]}},{"word":"in terms of","ipa_uk":"/ɪn ˈtɜːmz əv/","ipa_us":"/ɪn ˈtɜːrmz əv/","definition_zh":"就……而言；在……方面；以……为单位或术语来衡量","definition_en":"with regard to a particular measure, unit or way of expressing something","core_image":"一张报价单横向分成几栏，每栏标着不同的衡量口径","scene":"财务报表把同一笔支出拆成几栏，分别用金额、工时与占比衡量。In terms of cost, the second option is far cheaper.","sceneCN":"这里取「就……而言」（第 1 个义项：限定评价所用的衡量维度）；句意为就成本而言，第二个方案便宜得多。","pos":[{"tag":"prep. phr.","zh":"介词短语：就……而言；在……方面"},{"tag":"prep. phr.","zh":"介词短语：以……为单位或术语衡量"}],"collocations":[{"phrase":"in terms of cost","zh":"就成本而言"},{"phrase":"in terms of quality","zh":"在质量方面"},{"phrase":"in terms of percentage","zh":"按百分比计算"},{"phrase":"in real terms","zh":"按实际价值计算"},{"phrase":"in terms of employment","zh":"就就业而言"},{"phrase":"expressed in terms of","zh":"用……表示"}],"forms":[{"label":"原形","form":"in terms of"},{"label":"数学用法","form":"expressed in terms of"},{"label":"实际价值用法","form":"in real terms"}],"derivatives":[{"word":"term","pos":"n.","zh":"术语；期限；项"},{"word":"terminal","pos":"n./adj.","zh":"终点站；终端的"},{"word":"terminate","pos":"v.","zh":"终止"},{"word":"terminology","pos":"n.","zh":"术语体系"},{"word":"terms","pos":"n.","zh":"条件；条款"}],"senses":[{"no":"01","title":"The dimension used for judgement","titleCN":"句首：就……而言","definition":"placed at the start of a clause to name the dimension on which a judgement is made","definitionCN":"置于从句开头，点出作出判断所依据的维度","example":"In terms of cost, the second option is far cheaper.","exampleCN":"就成本而言，第二个方案便宜得多。","why":"The phrase narrows the comparison to one measure, so the judgement holds on that measure and not necessarily on others.","whyCN":"这个短语把比较收窄到单一尺度，因此判断只在该尺度上成立。"},{"no":"02","title":"The broad aspect being discussed","titleCN":"在……方面","definition":"used to name the aspect of a matter that the sentence is about","definitionCN":"点出句子所谈论的某事的方面","example":"In terms of employment, the region has recovered slowly.","exampleCN":"在就业方面，该地区恢复缓慢。","why":"Aspect is looser than a unit: nothing is counted, but the discussion is still confined to one side of the matter.","whyCN":"「方面」比「单位」宽松：不计数，但讨论仍被限制在事情的一面。"},{"no":"03","title":"The unit or basis of calculation","titleCN":"以……为单位、按……计算","definition":"used before a unit or a basis to say how a quantity is counted","definitionCN":"用在单位或基准之前，说明数量按什么计","example":"The fee is calculated in terms of hours, not days.","exampleCN":"费用按小时计算，而非按天。","why":"Here the phrase supplies the unit of account, which is why it often follows verbs of measuring, paying or counting.","whyCN":"此处短语提供计价单位，因此常跟在测量、支付、计数类动词之后。"},{"no":"04","title":"The vocabulary of a document","titleCN":"用……术语表述（法律、技术）","definition":"used to say that something is expressed in the language of a particular field or document","definitionCN":"表示某事是用某领域或某文件的语言表述的","example":"The obligation is defined in terms of the contract, not of custom.","exampleCN":"这项义务是以合同条款界定的，而不是以惯例界定的。","why":"When the object is a document, the phrase shifts from measuring to wording: what matters is the vocabulary used.","whyCN":"当宾语是文件时，短语从「衡量」转向「措辞」：重要的是所用的语言。"},{"no":"05","title":"Mathematical expression in variables","titleCN":"数学：用……表示","definition":"in mathematics, used after express or write to name the variables that carry a quantity","definitionCN":"在数学中，跟在「表达」「写出」之后，点出承载某量的变量","example":"The area can be expressed in terms of the radius.","exampleCN":"面积可以用半径来表示。","why":"Mathematics uses the phrase for rewriting one quantity as a formula of others, which is a precise kind of measuring.","whyCN":"数学借此把一个量改写成其他量的公式，这是一种精确的衡量。"},{"no":"06","title":"Value after inflation is removed","titleCN":"实际价值口径：按不变价格计算","definition":"in economics, used in the fixed pattern in real terms to strip out the effect of prices","definitionCN":"在经济学中，用于固定说法「按实际价值」，剔除物价影响","example":"Measured in terms of real value, wages fell over the decade.","exampleCN":"这十年间工资按实际价值计算下降了。","why":"Economists need to separate nominal figures from purchasing power, and the phrase marks the corrected figure.","whyCN":"经济学家要把名义数字与购买力分开，这个短语标出修正后的数字。"},{"no":"07","title":"The boundary against a phrase about topics","titleCN":"与「关于」类短语的边界","definition":"unlike a topic marker, it names the measure rather than the subject matter","definitionCN":"与限定话题的说法不同，它点出衡量尺度而非主题","example":"The two plans differ in terms of risk, not in terms of aim.","exampleCN":"两个方案在风险上不同，在目标上并无不同。","why":"This is the key split: one phrase asks on what scale, the other asks about what matter.","whyCN":"这是关键分工：一个问「用什么尺度」，另一个问「关于什么事项」。"},{"no":"08","title":"The commercial terms of a deal","titleCN":"商务：按……条件谈","definition":"in business writing, used to discuss the conditions under which a deal is made","definitionCN":"在商务文字中，讨论交易达成的条件","example":"The parties negotiated in terms of payment and delivery.","exampleCN":"双方就付款与交付条件进行了商谈。","why":"Commercial usage extends the phrase from measurement to the clauses of a bargain, where terms means conditions.","whyCN":"商务用法把这个短语从衡量扩展到交易条款，此处「条款」意为条件。"}],"etymology":{"intro":{"en":"Term comes from Latin terminus, a boundary or end, and the plural terms came to mean conditions or expressions. The English phrase is modern; the Latin noun is clear.","cn":"term 来自拉丁语 terminus「边界、终点」，复数形式后来指条件或说法。英语短语属近代；拉丁语名词清楚。"},"items":[{"era":"LATIN TERMINUS","en":"Terminus meant a boundary stone or an end, and gave English term and terminal.","cn":"terminus 意为界石或终点，给英语带来 term 与 terminal。"},{"era":"BOUNDARY TO LIMIT","en":"A boundary fixes where something stops, and the word came to mean a fixed limit or a set period.","cn":"边界确定某物止于何处，这个词由此指固定期限。"},{"era":"TERMS AS CONDITIONS","en":"The plural acquired the sense of agreed conditions, as in the terms of a contract.","cn":"复数形式获得「商定条件」之义，如合同条款。"},{"era":"TERMS AS EXPRESSIONS","en":"It also came to mean the words in which something is expressed, hence terminology.","cn":"它也指表述某事所用的词语，由此有「术语体系」。"},{"era":"THE MODERN PHRASE","en":"The phrase with this preposition and of settles in modern analytical writing; dates are approximate.","cn":"带这个介词与 of 的短语在近代分析性文字中定型，年代为约数。"}]},"similar":{"note":{"en":"The first group also limits a statement but points to a topic rather than a measure; the second group holds phrases of proportion, basis and reference.","cn":"第一组同样限定陈述，但指向话题而非尺度；第二组是比例、基准与参照类说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"with respect to","ipa":"/wɪð rɪˈspekt tuː/","tag":"topic, not measure","definition":"It says what matter is being discussed, not on what scale it is judged.","definitionCN":"它说讨论的是哪个事项，而非用什么尺度评判。"},{"word":"in relation to","ipa":"/ɪn rɪˈleɪʃn tuː/","tag":"relation, wider","definition":"It links two matters without fixing a unit of measurement.","definitionCN":"它连接两件事，不固定计量单位。"},{"word":"as regards","ipa":"/æz rɪˈɡɑːdz/","tag":"formal topic marker","definition":"It introduces a subject in formal prose.","definitionCN":"在正式文字中引出主题。"},{"word":"in the case of","ipa":"/ɪn ðə keɪs əv/","tag":"instance, not dimension","definition":"It picks out one instance from a group.","definitionCN":"从一组中挑出一个实例。"}]},{"heading":"NEAR MEANING","entries":[{"word":"measured by","ipa":"/ˈmeʒəd baɪ/","tag":"plain instrument","definition":"It names the instrument of measurement directly.","definitionCN":"直接点出测量工具。"},{"word":"expressed as","ipa":"/ɪˈsprest æz/","tag":"form of statement","definition":"It names the form in which a quantity is written.","definitionCN":"点出数量写成的形式。"},{"word":"by volume","ipa":"/baɪ ˈvɒljuːm/","tag":"unit phrase","definition":"It gives one common unit of account in trade.","definitionCN":"给出贸易中常用的一种计价单位。"},{"word":"on a per capita basis","ipa":"/ɒn ə pɜː ˈkæpɪtə ˈbeɪsɪs/","tag":"basis phrase","definition":"It states the basis on which a figure is divided.","definitionCN":"说明数字按什么基准分摊。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real boundary root, the real units and the real fixed phrases.","cn":"正常联想用真实「边界」词根、真实单位与真实固定说法。"},"normal":[{"en":"A term is a boundary, so the phrase fixes the line within which a judgement is made.","cn":"这个词根意为边界，所以这个短语划定判断所限的界线。"},{"en":"It names a scale, a unit, a vocabulary or a set of conditions.","cn":"它可点出尺度、单位、术语或条件。"},{"en":"In mathematics it rewrites one quantity through others.","cn":"在数学里它用其他量改写一个量。"},{"en":"In real terms is the economist's fixed pattern for removing inflation.","cn":"「按实际价值」是经济学家剔除通胀的固定说法。"},{"en":"It is not a topic marker: it asks on what scale, not about what matter.","cn":"它不是话题标记：问的是用什么尺度，而非关于什么事项。"}],"abstract":[{"en":"Like a receipt split into columns, each column measuring the same purchase differently.","cn":"像一张收据分成几栏，每栏用不同口径量同一笔支出。"},{"en":"Like a ruler laid across a table, deciding which dimension gets counted.","cn":"像一把尺横在桌上，决定量哪一个维度。"},{"en":"Like a contract margin where the same promise is restated in the language of clauses.","cn":"像合同页边，把同一个承诺改写成条款语言。"}]},"examples":[{"en":"In terms of cost, the second route is the better choice.","cn":"就成本而言，第二条路线是更好的选择。"},{"en":"The two cities differ in terms of climate rather than size.","cn":"这两座城市在气候上不同，而非规模上不同。"},{"en":"Output is measured in terms of units produced per hour.","cn":"产量按每小时生产的件数计算。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「因 特姆兹 奥夫」——一张收据分成几栏，各用各的尺：就……而言","word":"in terms of"},"root":"term 来自拉丁语 terminus「边界、终点」，复数 later 指条件与说法；短语 in terms of 在近代分析性文字中定型，首见年代为约数。","sensesIntro":{"en":"Eight senses split by what follows: a dimension, an aspect, a unit, a vocabulary, a mathematical variable, a real-value basis, a boundary against topic phrases, and commercial conditions.","cn":"八个义项按后接内容区分：尺度、方面、单位、术语、数学变量、实际价值口径、与话题短语的边界、商务条件。"},"semanticMap":{"core":{"en":"CORE IMAGE: one receipt split into several columns, each measuring the same purchase on another scale.","cn":"核心意象：一张收据分成几栏，每栏用另一种尺度量同一笔支出。"},"chain":["BOUNDARY","DIMENSION","ASPECT","UNIT","VOCABULARY","REAL VALUE"],"branches":[{"senses":"01 · 07","en":"THE DIMENSION: a judgement is confined to one scale, not to the whole subject.","cn":"尺度：判断被限定在一个尺度，而非整个主题。"},{"senses":"02","en":"THE ASPECT: a looser side of the matter is named without counting.","cn":"方面：点出事情较宽松的一面，不计数。"},{"senses":"03 · 06","en":"THE UNIT: hours, percentages or real value supply the basis of account.","cn":"单位：小时、百分比或实际价值提供计价基准。"},{"senses":"04 · 08","en":"THE LANGUAGE: contracts and deals restate a promise in their own terms.","cn":"语言：合同与交易用自己的条款重述承诺。"},{"senses":"05","en":"THE FORMULA: mathematics rewrites one quantity through others.","cn":"公式：数学用其他量改写一个量。"}]},"affixes":{"intro":{"en":"The phrase joins a Latin noun of boundary with an English preposition; the boundary root is the core.","cn":"这个短语把拉丁语「边界」名词与英语介词结合；边界词根是核心。"},"latinIntro":{"en":"The Latin etymon is terminus, a boundary stone or end; the plural sense of conditions is later.","cn":"拉丁语词源是 terminus「界石、终点」；复数表条件之义较晚。"},"items":[{"word":"terminus","structure":"Latin noun, second declension","meaning":"boundary; end","meaningCN":"边界；终点","example":"The noun also gives terminal and terminate.","exampleCN":"这个名词也给出两个相关英语词。"},{"word":"term","structure":"English noun from Latin","meaning":"a word; a limit; a period","meaningCN":"术语；期限","example":"English keeps the limit and the expression senses.","exampleCN":"英语保留「界限」与「表述」两义。"},{"word":"terms","structure":"English plural noun","meaning":"conditions; wording","meaningCN":"条件；条款","example":"The plural covers both a contract and a phrasing.","exampleCN":"复数兼指合同条款与措辞。"},{"word":"terminal","structure":"term + -inal","meaning":"end point; final","meaningCN":"终点；末端的","example":"The adjective marks the end of a line.","exampleCN":"形容词标出线路的尽头。"},{"word":"terminate","structure":"terminus + -ate (verb)","meaning":"to bring to an end","meaningCN":"终止","example":"The verb turns the boundary into an action.","exampleCN":"动词把边界变成动作。"},{"word":"terminology","structure":"term + -ology","meaning":"the system of terms in a field","meaningCN":"术语体系","example":"The suffix names the study or set of terms.","exampleCN":"后缀指术语的研究或集合。"},{"word":"in terms of","structure":"preposition + plural noun + preposition","meaning":"with regard to a measure","meaningCN":"就……而言","example":"The phrase is standard in analytical prose.","exampleCN":"这个短语在分析性文字中是标准用法。"},{"word":"in real terms","structure":"fixed economic phrase","meaning":"after adjusting for prices","meaningCN":"按实际价值计算","example":"The pattern removes inflation from a figure.","exampleCN":"这个说法从数字中剔除通胀。"}],"latinEntries":[{"word":"terminus","structure":"terminus, -i (noun, second declension)","meaning":"boundary; end","meaningCN":"边界；终点"}],"derivatives":[{"word":"term","pos":"n.","zh":"术语；期限；项"},{"word":"terminal","pos":"n./adj.","zh":"终点站；终端的"},{"word":"terminate","pos":"v.","zh":"终止"},{"word":"terminology","pos":"n.","zh":"术语体系"},{"word":"terms","pos":"n.","zh":"条件；条款"}]}},{"word":"with respect to","ipa_uk":"/wɪð rɪˈspekt tuː/","ipa_us":"/wɪð rɪˈspekt tuː/","definition_zh":"关于；就……而言；就……事项（正式，用于限定讨论范围）","definition_en":"concerning a particular matter; used to narrow the topic of a statement","core_image":"律师在合同边上画一道线，把讨论限定在其中一条","scene":"律师在合同边上画了一道线，把讨论限定在其中一条。With respect to clause four, both parties accepted the change.","sceneCN":"这里取「关于、就……事项」（第 3 个义项：法律文本中限定具体条款）；句意为就第四条而言，双方接受了改动。","pos":[{"tag":"prep. phr.","zh":"介词短语：关于；就……而言（正式）"},{"tag":"prep. phr.","zh":"介词短语：就……事项（法律）"}],"collocations":[{"phrase":"with respect to clause four","zh":"就第四条而言"},{"phrase":"with respect to your inquiry","zh":"关于你的询问"},{"phrase":"with respect to the property","zh":"就该财产而言"},{"phrase":"with respect to costs","zh":"在费用方面"},{"phrase":"with respect to the agreement","zh":"关于该协议"},{"phrase":"with respect to the data","zh":"就数据而言"}],"forms":[{"label":"原形","form":"with respect to"},{"label":"英式法律变体","form":"in respect of"},{"label":"句末用法","form":"a question with respect to"}],"derivatives":[{"word":"respect","pos":"n./v.","zh":"尊重；方面"},{"word":"respectful","pos":"adj.","zh":"恭敬的"},{"word":"respective","pos":"adj.","zh":"各自的"},{"word":"respectively","pos":"adv.","zh":"分别地"},{"word":"respected","pos":"adj.","zh":"受尊敬的"}],"senses":[{"no":"01","title":"The formal sentence-opening topic marker","titleCN":"句首：关于、就……而言","definition":"placed at the start of a formal sentence to name the matter under discussion","definitionCN":"置于正式句子开头，点出所讨论的事项","example":"With respect to costs, the committee asked for a new estimate.","exampleCN":"关于费用，委员会要求重新估算。","why":"The phrase opens a formal frame: the speaker announces the matter first, then speaks only to that matter.","whyCN":"这个短语打开一个正式框架：先报事项，再只就该项发言。"},{"no":"02","title":"Narrowing the topic mid-argument","titleCN":"议题限定：就……来说","definition":"used to confine an argument to one part of a larger question","definitionCN":"把论证限制在更大问题中的某一部分","example":"The proposal is sound with respect to safety, but not with respect to cost.","exampleCN":"这个提案在安全方面是合理的，但在成本方面不是。","why":"Two uses in one sentence show the phrase working as a pair of limits rather than a single subject.","whyCN":"一句中用两次，显示这个短语成对地划界，而非只点一个主题。"},{"no":"03","title":"A specific item in legal drafting","titleCN":"法律文本：就……事项","definition":"in legal texts, used to name the exact item a provision governs","definitionCN":"在法律文本中，点出某条规定所管辖的确切事项","example":"With respect to clause four, both parties accepted the change.","exampleCN":"就第四条而言，双方接受了改动。","why":"Legal drafting must attach a rule to a precise item, and the phrase supplies that attachment.","whyCN":"法律起草必须把规则挂到确切事项上，这个短语提供这种挂接。"},{"no":"04","title":"Reference to an incoming letter","titleCN":"公务来函：关于……","definition":"used in correspondence to name the matter that a reply concerns","definitionCN":"在往来公文中点出答复所涉及的事项","example":"With respect to your inquiry, the file has been forwarded.","exampleCN":"关于你的询问，档案已经转出。","why":"Correspondence uses the phrase to quote the subject without repeating the whole letter.","whyCN":"公文借此点明主题，不必重复整封来信。"},{"no":"05","title":"The neutral comparative aspect","titleCN":"比较语境：在……方面","definition":"used to compare two things on one named aspect without ranking them overall","definitionCN":"只就某一指名的方面比较两物，不作总体排序","example":"The two models are equal with respect to durability.","exampleCN":"这两款在耐用性方面相同。","why":"The phrase can make a comparison narrower and fairer, since it refuses to generalize beyond the named aspect.","whyCN":"这个短语可让比较更窄也更公平，因为它拒绝越过指名方面去概括。"},{"no":"06","title":"The fixed formula of official prose","titleCN":"公文句式：正式框架","definition":"in official and academic prose it frames a statement in a fixed, somewhat heavy way","definitionCN":"在官方与学术文字中，以固定而略嫌厚重的框架陈述","example":"With respect to the second question, no decision has been taken.","exampleCN":"关于第二个问题，尚未作出决定。","why":"The formula is chosen for distance and precision; it signals that the writer is answering a listed item.","whyCN":"这一套语用于制造距离与精确，示意作者正在回答清单上的某一项。"},{"no":"07","title":"The boundary against a phrase about scales","titleCN":"与「用什么尺度」类短语的边界","definition":"unlike a measure phrase, it asks which matter is meant rather than on what scale it is judged","definitionCN":"与表尺度的短语不同，它问的是哪个事项，而非用什么尺度评判","example":"With respect to risk, the question is what counts as a loss.","exampleCN":"就风险而言，问题在于什么算作损失。","why":"The split matters in argument: naming a matter invites definition, naming a scale invites measurement.","whyCN":"这一分工在论证中很重要：点事项就要定义，点尺度就要测量。"},{"no":"08","title":"The British legal parallel","titleCN":"英式法律对应说法","definition":"in British legal writing the shorter parallel phrase is often preferred in the same slot","definitionCN":"在英式法律文字中，同一位置常用更短的平行说法","example":"With respect to the lease, the tenant accepted the terms.","exampleCN":"就该租约而言，承租人接受了条款。","why":"Both forms occupy the same formal slot; the choice between them is a matter of house style.","whyCN":"两种形式占同一正式位置，选用哪一种属行文习惯。"}],"etymology":{"intro":{"en":"Respect comes from Latin respectus, a looking back, from respicere, re-, back, plus specere, to look. The Latin line is clear; the prepositional phrase is modern.","cn":"respect 来自拉丁语 respectus「回望」，词根 respicere 由 re-「回」与 specere「看」构成。拉丁语线索清楚，介词短语属近代。"},"items":[{"era":"LATIN SPECERE","en":"Specere, to look, is also the root of spectacle and specimen.","cn":"specere 意为「看」，也是 spectacle 与 specimen 的词根。"},{"era":"LATIN RESPICERE","en":"Respicere meant to look back at or take notice of, hence to regard.","cn":"respicere 意为回看、注意，由此引申为顾及。"},{"era":"LATIN RESPECTUS","en":"The noun named a looking back and later a regard for someone or something.","cn":"这个名词本指回望，后来指对某人某物的顾及。"},{"era":"ENGLISH RESPECT","en":"English respect appears in the Middle English period; the date is approximate.","cn":"英语 respect 见于中古英语，年代为约数。"},{"era":"THE FORMAL PHRASE","en":"The phrase with this preposition and to settles in modern official and legal writing.","cn":"带这个介词与 to 的短语在近代官方与法律文字中定型。"}]},"similar":{"note":{"en":"The first group also confines a statement but differs in register or in what it points to; the second group holds formal ways of naming a matter.","cn":"第一组同样限定陈述，但语域或指向不同；第二组是点明事项的正式说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"in respect of","ipa":"/ɪn rɪˈspekt əv/","tag":"British legal parallel","definition":"A shorter British legal phrase with the same confining work.","definitionCN":"更短的英式法律短语，限定作用相同。"},{"word":"in terms of","ipa":"/ɪn ˈtɜːmz əv/","tag":"scale, not matter","definition":"It names the measure, while this phrase names the matter.","definitionCN":"它点出尺度，而本短语点出事项。"},{"word":"in relation to","ipa":"/ɪn rɪˈleɪʃn tuː/","tag":"relation, wider","definition":"It links two matters without the legal weight.","definitionCN":"连接两件事，没有法律分量。"},{"word":"as for","ipa":"/æz fɔː/","tag":"conversational topic shift","definition":"It shifts topic in speech and sounds much lighter.","definitionCN":"在口语中转移话题，语气轻得多。"}]},{"heading":"NEAR MEANING","entries":[{"word":"concerning","ipa":"/kənˈsɜːnɪŋ/","tag":"plain preposition","definition":"It means about and carries no legal tone.","definitionCN":"意为关于，不带法律语气。"},{"word":"regarding","ipa":"/rɪˈɡɑːdɪŋ/","tag":"neutral formal","definition":"A neutral formal equivalent used in letters.","definitionCN":"书信中中性的正式对应词。"},{"word":"on the subject of","ipa":"/ɒn ðə ˈsʌbdʒɪkt əv/","tag":"explicit topic","definition":"It spells out that a topic is being introduced.","definitionCN":"明说正在引入一个话题。"},{"word":"so far as concerns","ipa":"/səʊ fɑː æz kənˈsɜːnz/","tag":"heavy legal formula","definition":"A heavier legal formula for the same limiting move.","definitionCN":"同一限定动作的更厚重法律套语。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real looking-back root, the real legal slot and the real register.","cn":"正常联想用真实「回望」词根、真实法律位置与真实语域。"},"normal":[{"en":"Respect is a looking back, so the phrase turns attention onto one named matter.","cn":"词根意为回望，这个短语把注意力转向某个指名事项。"},{"en":"It takes a noun, never a clause.","cn":"它接名词，从不接从句。"},{"en":"Its British legal twin is shorter and sits in the same slot.","cn":"它的英式法律双胞胎更短，占同一位置。"},{"en":"It names the matter, not the scale, which is the boundary against measure phrases.","cn":"它点事项而非尺度，这就是与表尺度短语的边界。"},{"en":"Official prose uses it to answer a listed item precisely.","cn":"公文用它精确回答清单上的某一项。"}],"abstract":[{"en":"Like a pencil line drawn under one clause of a long contract.","cn":"像在长合同某一条下面画的一道铅笔线。"},{"en":"Like a lamp turned to one corner of a room instead of the whole room.","cn":"像把灯转向屋子的一个角落，而非整间屋子。"},{"en":"Like a meeting agenda where only one listed item is opened.","cn":"像会议议程上只翻开其中一项。"}]},"examples":[{"en":"With respect to costs, no decision has yet been made.","cn":"关于费用，尚未作出决定。"},{"en":"The two designs are equal with respect to safety.","cn":"这两个设计在安全方面相同。"},{"en":"With respect to your letter, the documents are enclosed.","cn":"关于你的来信，文件已随函附上。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「威斯 瑞斯佩克特 图」——在合同某一条下画一道线：关于、就……而言","word":"with respect to"},"root":"respect 来自拉丁语 respectus「回望」，词根 respicere 由 re-「回」与 specere「看」构成；短语 with respect to 在近代官方与法律文字中定型，首见年代为约数。","sensesIntro":{"en":"Eight senses split by what is being confined: a formal opening, a mid-argument limit, a legal item, an incoming letter, a comparative aspect, an official formula, the boundary against measure phrases, and a British parallel.","cn":"八个义项按被限定的对象区分：正式开头、论证中的限定、法律事项、来函、比较方面、公文套语、与尺度短语的边界、英式平行说法。"},"semanticMap":{"core":{"en":"CORE IMAGE: a pencil line drawn under one clause of a contract.","cn":"核心意象：在合同某一条下画的一道铅笔线。"},"chain":["LOOK BACK","TOPIC FRAME","NARROWED ARGUMENT","LEGAL ITEM","CORRESPONDENCE","COMPARATIVE ASPECT"],"branches":[{"senses":"01 · 06","en":"THE FRAME: formal openings and official formulas announce the matter first.","cn":"框架：正式开头与公文套语先报事项。"},{"senses":"02 · 05","en":"THE LIMIT: one aspect is isolated for argument or comparison.","cn":"限定：隔离出一个方面用于论证或比较。"},{"senses":"03 · 08","en":"THE ITEM: legal drafting attaches a rule to an exact clause, in either variant.","cn":"事项：法律起草把规则挂到确切条款，两种变体皆可。"},{"senses":"04","en":"THE LETTER: correspondence names the subject being answered.","cn":"来函：公文点出所答复的主题。"},{"senses":"07","en":"THE BOUNDARY: matter is named, not scale.","cn":"边界：点事项，不点尺度。"}]},"affixes":{"intro":{"en":"The phrase joins a Latin noun of looking back with an English preposition; the look root is the core.","cn":"这个短语把拉丁语「回望」名词与英语介词结合；「看」的词根是核心。"},"latinIntro":{"en":"The Latin etyma are respicere, to look back, and specere, to look.","cn":"拉丁语词源是 respicere「回看」与 specere「看」。"},"items":[{"word":"specere","structure":"Latin verb","meaning":"to look","meaningCN":"看","example":"The root runs through the whole spect- family.","exampleCN":"这个词根贯穿整个「看」的词族。"},{"word":"respicere","structure":"re- + specere","meaning":"to look back at; to regard","meaningCN":"回看；顾及","example":"The verb adds direction to the act of looking.","exampleCN":"这个动词给「看」加上方向。"},{"word":"respectus","structure":"Latin noun from respicere","meaning":"a looking back; regard","meaningCN":"回望；顾及","example":"The noun supplies the English base.","exampleCN":"这个名词提供英语基词。"},{"word":"respect","structure":"English noun and verb","meaning":"regard; to admire","meaningCN":"顾及；尊敬","example":"English keeps both the attention and the esteem senses.","exampleCN":"英语保留「注意」与「尊敬」两义。"},{"word":"respectful","structure":"respect + -ful","meaning":"showing esteem","meaningCN":"恭敬的","example":"The suffix marks the esteem sense.","exampleCN":"后缀标出「尊敬」义。"},{"word":"respective","structure":"respectus + -ive","meaning":"relating to each separately","meaningCN":"各自的","example":"The adjective keeps the looking-at-each sense.","exampleCN":"形容词保留「逐个看」义。"},{"word":"respectively","structure":"respective + -ly","meaning":"in the order named","meaningCN":"分别地","example":"The adverb distributes items in order.","exampleCN":"副词按顺序分配项目。"},{"word":"with respect to","structure":"preposition + noun + preposition","meaning":"concerning","meaningCN":"关于","example":"The phrase is formal and often legal.","exampleCN":"这个短语正式，常用于法律。"}],"latinEntries":[{"word":"respicere","structure":"respicere, respicio, respexi, respectum (verb, third conjugation)","meaning":"to look back at","meaningCN":"回看"},{"word":"specere","structure":"specere, specio, spexi, spectum (verb)","meaning":"to look","meaningCN":"看"},{"word":"respectus","structure":"respectus, -us (noun, fourth declension)","meaning":"a looking back; regard","meaningCN":"回望；顾及"}],"derivatives":[{"word":"respect","pos":"n./v.","zh":"尊重；方面"},{"word":"respectful","pos":"adj.","zh":"恭敬的"},{"word":"respective","pos":"adj.","zh":"各自的"},{"word":"respectively","pos":"adv.","zh":"分别地"},{"word":"respected","pos":"adj.","zh":"受尊敬的"}]}},{"word":"by contrast","ipa_uk":"/baɪ ˈkɒntrɑːst/","ipa_us":"/baɪ ˈkɑːntræst/","definition_zh":"相比之下；与之相对（多用于句首，引出与前句相反的情况）","definition_en":"used to introduce a fact or situation that differs sharply from the one just mentioned","core_image":"一张纸左半写满数字，右半只留一个零","scene":"报告左页列满增长数字，右页只有一个零。By contrast, the second region recorded no growth at all.","sceneCN":"这里取「相比之下」（第 1 个义项：句首对比连接语，必须与前句对照）；句意为相比之下，第二个地区毫无增长。","pos":[{"tag":"adv. phr.","zh":"状语短语：相比之下（多置句首）"},{"tag":"prep. phr.","zh":"少见搭配：与……对照"}],"collocations":[{"phrase":"by contrast, the second","zh":"相比之下，第二个"},{"phrase":"by contrast with","zh":"与……对照（少见）"},{"phrase":"by sharp contrast","zh":"形成鲜明对比的是"},{"phrase":"by contrast, however","zh":"相比之下，然而"},{"phrase":"in by contrast","zh":"在对比之下（少见）"},{"phrase":"mark by contrast","zh":"以对比标出"}],"forms":[{"label":"原形","form":"by contrast"},{"label":"强调式","form":"by sharp contrast"},{"label":"少见后接形式","form":"by contrast with"}],"derivatives":[{"word":"contrast","pos":"n./v.","zh":"对比；对照"},{"word":"contrastive","pos":"adj.","zh":"对比的"},{"word":"contrastingly","pos":"adv.","zh":"对比之下（少见）"},{"word":"in contrast","pos":"adv. phr.","zh":"相比之下（可接介词）"},{"word":"contrast with","pos":"v. phr.","zh":"与……形成对比"}],"senses":[{"no":"01","title":"The sentence-opening contrast connector","titleCN":"句首：相比之下","definition":"placed at the start of a sentence to set the new statement against the one just made","definitionCN":"置于句首，把新陈述与刚说过的那句并置对照","example":"The north grew quickly. By contrast, the south stagnated.","exampleCN":"北方增长很快。相比之下，南方停滞。","why":"The phrase is a pure connector: it does not name the benchmark, because the previous sentence already supplies it.","whyCN":"这个短语是纯连接语：不点名基准，因为前一句已经提供。"},{"no":"02","title":"The mid-sentence aside","titleCN":"句中插入：与之相对","definition":"inserted between commas to add a contrasting aside inside a clause","definitionCN":"用逗号插入句中，在从句内部补一个对照性的旁白","example":"The first method is cheap; the second, by contrast, is slow.","exampleCN":"第一种方法便宜；相比之下，第二种慢。","why":"In the middle it behaves like a parenthetical marker, changing the tone without changing the grammar of the clause.","whyCN":"放在中间，它像插入的标记，改变语气却不改变从句语法。"},{"no":"03","title":"The paragraph-opening opposite","titleCN":"段落开头：引出对立面","definition":"at the start of a paragraph, used to turn the discussion to the opposite case","definitionCN":"在段落开头使用，把讨论转向相反情形","example":"By contrast, the following section deals with rural schools.","exampleCN":"相比之下，下一节讨论农村学校。","why":"At paragraph level the phrase is a signpost, telling the reader that the argument is changing sides.","whyCN":"在段落层面，这个短语是路标，告诉读者论证即将换边。"},{"no":"04","title":"The syntactic difference from a close twin","titleCN":"句法差异：通常不接介词","definition":"unlike its close twin, it usually stands alone and rarely takes a following preposition plus noun","definitionCN":"与它的近义双胞胎不同，它通常独立使用，很少在后面接介词加名词","example":"By contrast, the second group moved far less.","exampleCN":"相比之下，第二组流动少得多。","why":"The two connectors do similar work, but the shorter one prefers the stand-alone slot, which is a grammatical habit rather than a rule of meaning.","whyCN":"两个连接语功能相近，但较短的这个偏爱独立位置，这是语法习惯而非意义规则。"},{"no":"05","title":"The elliptical comparison","titleCN":"省略式对比：只补一个新事实","definition":"used when the shared part of the comparison is left out and only the new fact is stated","definitionCN":"当比较中共同的部分被省略、只说出新事实时使用","example":"By contrast, the 1990s brought almost no new housing.","exampleCN":"相比之下，九十年代几乎没有新增住房。","why":"Ellipsis keeps the sentence short: the standard of comparison stays in the previous sentence and need not be repeated.","whyCN":"省略让句子保持简短：比较基准留在前一句，无需重复。"},{"no":"06","title":"The boundary against a denial","titleCN":"与「否定命题」类说法的边界","definition":"unlike a phrase that denies a negative claim, it simply sets two facts against each other","definitionCN":"与否定某个否定命题的说法不同，它只是把两件事实并置","example":"By contrast, the second trial produced no side effects.","exampleCN":"相比之下，第二次试验没有副作用。","why":"The phrase does not argue with what was said; it adds a second fact, which is why a denial phrase would be the wrong choice here.","whyCN":"这个短语不与已说的话争辩，只添第二件事实，因此在此用否定类说法是错的。"},{"no":"07","title":"The research-writing contrast signal","titleCN":"学术与数据写作：对比信号","definition":"in research writing, used to introduce results that differ from those just reported","definitionCN":"在学术写作中，引出与前一条结果不同的结果","example":"By contrast, the treated group showed a sharp decline.","exampleCN":"相比之下，处理组出现了明显下降。","why":"Research prose needs a short signal that two findings are being held apart without judging either.","whyCN":"学术写作需要一个短信号，把两项发现分开而不评判任何一项。"},{"no":"08","title":"The emphasis on a wide gap","titleCN":"强调幅度：反差很大","definition":"used when the difference is large and the writer wants that gap to stand out","definitionCN":"当差异很大、作者想让这一落差突出时使用","example":"By contrast, the richest group saved almost nothing.","exampleCN":"相比之下，最富裕的群体几乎没存下钱。","why":"The phrase can carry emphasis when the two facts are far apart; the contrast itself becomes the point.","whyCN":"当两件事实相距很远时，这个短语可承载强调；对比本身成了重点。"}],"etymology":{"intro":{"en":"Contrast came into English through French from Italian contrastare, a Vulgar Latin verb built on Latin contra, against, and stare, to stand. The Latin line is secure; the connector by contrast is modern.","cn":"contrast 经法语、意大利语进入英语，其动词是通俗拉丁语形式，由拉丁语 contra「反对」与 stare「站立」构成。拉丁语线索可靠；连接语 by contrast 属近代。"},"items":[{"era":"LATIN CONTRA","en":"Contra, against, is the same element found in contradiction and contraflow.","cn":"contra 意为「反对」，与 contradiction、contraflow 中的成分相同。"},{"era":"LATIN STARE","en":"Stare, to stand, gives the picture of two things standing face to face.","cn":"stare 意为「站立」，画出两物面对面站立的画面。"},{"era":"VULGAR LATIN CONTRASTARE","en":"The reconstructed verb meant to stand against or withstand.","cn":"重构的动词意为「对立而站、抵抗」。"},{"era":"ENGLISH NOUN AND VERB","en":"English took contrast in the sixteenth century; the noun named a difference set side by side.","cn":"英语在十六世纪借入 contrast；名词指并置的差异。"},{"era":"THE CONNECTOR","en":"The connector by contrast develops in modern journalistic and academic prose; the exact date is approximate.","cn":"连接语 by contrast 在近代新闻与学术文字中发展出来，确切年代为约数。"}]},"similar":{"note":{"en":"The first group shares the contrast slot but differs in syntax or in what it denies; the second group holds other connectors that set facts against each other.","cn":"第一组同样占对比位置，但句法或否定对象不同；第二组是其他把事实并置的连接语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"in contrast","ipa":"/ɪn ˈkɒntrɑːst/","tag":"twin that takes prepositions","definition":"It can be followed by to or with plus a noun, which the shorter connector usually avoids.","definitionCN":"它后面可接介词加名词，而较短的连接语通常避开这种结构。"},{"word":"on the contrary","ipa":"/ɒn ðə ˈkɒntrəri/","tag":"denies a claim","definition":"It rejects a negative statement rather than adding a second fact.","definitionCN":"它否定一个否定陈述，而非追加第二件事实。"},{"word":"in comparison","ipa":"/ɪn kəmˈpærɪsn/","tag":"similarity allowed","definition":"It may report closeness, while this connector always marks divergence.","definitionCN":"它可报告接近，而这个连接语始终标出分歧。"},{"word":"on the other hand","ipa":"/ɒn ði ˈʌðə hænd/","tag":"balanced alternative","definition":"It introduces the second side of an argument in a softer tone.","definitionCN":"以更柔和的语气引出论点的另一面。"}]},{"heading":"NEAR MEANING","entries":[{"word":"conversely","ipa":"/kənˈvɜːsli/","tag":"inverse relation","definition":"It marks the reverse side of a stated relation rather than a free contrast.","definitionCN":"标出所述关系的反面，而非自由对比。"},{"word":"whereas","ipa":"/ˈweəræz/","tag":"clausal conjunction","definition":"It joins two full clauses inside one sentence.","definitionCN":"在同一句内连接两个完整从句。"},{"word":"instead","ipa":"/ɪnˈsted/","tag":"replacement","definition":"It marks what takes the place of something rather than a parallel fact.","definitionCN":"标出替代物，而非平行事实。"},{"word":"then again","ipa":"/ðen əˈɡen/","tag":"spoken counterpoint","definition":"It adds a counterpoint in conversation, much lighter in tone.","definitionCN":"在口语中补一个对照点，语气轻得多。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Latin pair, the real connector slot and the real boundary.","cn":"正常联想用真实拉丁语对、真实连接语位置与真实边界。"},"normal":[{"en":"Contra is against and stare is to stand, so the word began as a picture of two things facing off.","cn":"拉丁词根一是「反」，一是「站」，这个词最初就是两物对峙的画面。"},{"en":"It usually stands at the front and does not need to repeat the benchmark.","cn":"它通常站句首，不必重复基准。"},{"en":"It prefers to stand alone rather than take a following preposition.","cn":"它偏爱独立使用，不爱接后面的介词。"},{"en":"It adds a fact; it does not deny what was said.","cn":"它追加事实，不否定已说的话。"},{"en":"It always marks divergence, never closeness.","cn":"它始终标出分歧，从不表接近。"}],"abstract":[{"en":"Like a page split down the middle, one side crowded with figures and the other almost blank.","cn":"像一页从中间分开，一边挤满数字，一边几乎空白。"},{"en":"Like two doors facing each other across a corridor.","cn":"像走廊两端面对面的两扇门。"},{"en":"Like a card turned over to show the reverse side of the same picture.","cn":"像把卡片翻过来，露出同一画面的背面。"}]},"examples":[{"en":"The coast is wet and mild. By contrast, the plateau is dry and cold.","cn":"沿海湿润温和。相比之下，高原干燥寒冷。"},{"en":"By contrast, the second experiment produced almost no change.","cn":"相比之下，第二次实验几乎没有变化。"},{"en":"By contrast with the earlier decade, the nineties saw little building.","cn":"与上一个十年相比，九十年代几乎没有建设。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「拜 康特拉斯特」——一页两边，一边满一边空：相比之下","word":"by contrast"},"root":"contrast 经法语、意大利语进入英语，其动词由拉丁语 contra「反对」与 stare「站立」构成通俗拉丁语重构形式；连接语 by contrast 在近代新闻与学术文字中发展出来，首见年代为约数。","sensesIntro":{"en":"Eight senses split by position and function: a sentence opener, a mid-clause aside, a paragraph signpost, the syntax boundary against its twin, ellipsis, the boundary against denial, a research signal, and emphasis on a wide gap.","cn":"八个义项按位置与功能区分：句首、句中旁白、段落路标、与双胞胎的句法边界、省略、与否定说法的边界、研究信号、强调落差。"},"semanticMap":{"core":{"en":"CORE IMAGE: one page split in two, one side crowded with figures, the other almost blank.","cn":"核心意象：一页分成两半，一边挤满数字，一边几乎空白。"},"chain":["STAND AGAINST","FRONT CONNECTOR","MID ASIDE","ELLIPSIS","DENIAL BOUNDARY","WIDE GAP"],"branches":[{"senses":"01 · 03","en":"THE SIGNPOST: front position and paragraph openings announce the other side.","cn":"路标：句首与段落开头宣告另一面。"},{"senses":"02","en":"THE ASIDE: inside commas the connector lowers its voice.","cn":"旁白：被逗号夹住时，连接语降低音量。"},{"senses":"04 · 06","en":"THE BOUNDARIES: it stands alone and adds a fact instead of denying one.","cn":"边界：独立使用，追加事实而非否定。"},{"senses":"05 · 07","en":"THE SHORT CUT: ellipsis and research writing keep the comparison brief.","cn":"省略与学术写作让对比保持简短。"},{"senses":"08","en":"THE GAP: a wide difference becomes the point of the sentence.","cn":"落差：巨大差异成为句子重点。"}]},"affixes":{"intro":{"en":"The connector joins an English preposition with a Latin-derived noun of standing against; the Latin core is clear.","cn":"这个连接语把英语介词与拉丁语「对立而站」的名词结合；拉丁核心清楚。"},"latinIntro":{"en":"The Latin etyma are contra, against, and stare, to stand; the verb passed through Italian and French.","cn":"拉丁语词源是 contra「反对」与 stare「站立」；动词经意大利语与法语传来。"},"items":[{"word":"contra","structure":"Latin preposition","meaning":"against","meaningCN":"反对","example":"Contra appears across English compounds of opposition.","exampleCN":"这个词根出现在许多表对立的英语复合词里。"},{"word":"stare","structure":"Latin verb, first conjugation","meaning":"to stand","meaningCN":"站立","example":"The verb supplies the image of standing one's ground.","exampleCN":"这个动词提供站定不退的画面。"},{"word":"contrastare","structure":"Vulgar Latin verb, reconstructed","meaning":"to stand against","meaningCN":"对立而站","example":"The reconstructed verb links Latin to Italian.","exampleCN":"这个重构动词把拉丁语与意大利语连起来。"},{"word":"contrast","structure":"English noun and verb","meaning":"a difference set side by side","meaningCN":"并置的差异","example":"The noun is the base of the connector.","exampleCN":"这个名词是连接语的基词。"},{"word":"contrastive","structure":"contrast + -ive","meaning":"expressing contrast","meaningCN":"表示对比的","example":"Linguistics speaks of contrastive pairs.","exampleCN":"语言学讲「对比对」。"},{"word":"contrastingly","structure":"contrasting + -ly","meaning":"by way of contrast","meaningCN":"对比之下","example":"The adverb is rare and mostly literary.","exampleCN":"这个副词罕见，多用于文学。"},{"word":"in contrast","structure":"preposition + noun","meaning":"by way of contrast","meaningCN":"相比之下","example":"Its twin can take a following preposition.","exampleCN":"它的双胞胎可接后面的介词。"},{"word":"by contrast","structure":"preposition + noun","meaning":"as a contrast","meaningCN":"相比之下","example":"The short connector usually stands alone.","exampleCN":"较短的连接语通常独立使用。"}],"latinEntries":[{"word":"contra","structure":"contra (preposition, with ablative)","meaning":"against","meaningCN":"反对"},{"word":"stare","structure":"stare, sto, steti, statum (verb, first conjugation)","meaning":"to stand","meaningCN":"站立"}],"derivatives":[{"word":"contrast","pos":"n./v.","zh":"对比；对照"},{"word":"contrastive","pos":"adj.","zh":"对比的"},{"word":"contrastingly","pos":"adv.","zh":"对比之下（少见）"},{"word":"in contrast","pos":"adv. phr.","zh":"相比之下（可接介词）"},{"word":"contrast with","pos":"v. phr.","zh":"与……形成对比"}]}},{"word":"as a consequence","ipa_uk":"/æz ə kənˈsiːkwəns/","ipa_us":"/æz ə kənˈsiːkwəns/","definition_zh":"因此，结果；由于（后接名词或动名词）","definition_en":"as a result of something; used to introduce an effect that follows from a cause","core_image":"第一张多米诺骨牌倒下，第二张随之倾覆","scene":"第一张骨牌倒下，第二张跟着倾覆。As a consequence, the whole line collapsed.","sceneCN":"这里取「因此、结果」（第 1 个义项：句首结果连接语）；句意为结果整条骨牌线都倒了。","pos":[{"tag":"adv. phr.","zh":"状语短语：因此、结果"},{"tag":"prep. phr.","zh":"介词短语：由于"}],"collocations":[{"phrase":"as a consequence of","zh":"由于……"},{"phrase":"as a direct consequence","zh":"作为直接结果"},{"phrase":"as a consequence, however","zh":"因此，然而"},{"phrase":"and as a consequence","zh":"因而"},{"phrase":"as a consequence of which","zh":"由此导致"},{"phrase":"suffer the consequences","zh":"承担后果"}],"forms":[{"label":"原形","form":"as a consequence"},{"label":"后接名词","form":"as a consequence of"},{"label":"强调式","form":"as a direct consequence"}],"derivatives":[{"word":"consequence","pos":"n.","zh":"后果；结果"},{"word":"consequent","pos":"adj.","zh":"随之发生的"},{"word":"consequently","pos":"adv.","zh":"因此"},{"word":"consequential","pos":"adj.","zh":"重要的；随之而来的"},{"word":"sequel","pos":"n.","zh":"续集；后续"}],"senses":[{"no":"01","title":"The sentence-opening result marker","titleCN":"句首：因此、结果","definition":"placed at the start of a sentence to introduce the effect of what was just said","definitionCN":"置于句首，引出前述内容造成的效果","example":"As a consequence, the whole line collapsed.","exampleCN":"结果整条骨牌线都倒了。","why":"The phrase opens the effect after the cause has been stated, which is why it usually follows a full sentence.","whyCN":"这个短语在原因说完后开启结果，因此通常跟在完整句子之后。"},{"no":"02","title":"The mid-sentence result","titleCN":"句中：因而","definition":"used after and or a semicolon inside a sentence to attach a result","definitionCN":"在句中用「并且」或分号之后接出结果","example":"The road was closed, and as a consequence the delivery was late.","exampleCN":"道路封闭，因而送货迟了。","why":"Inside one sentence the phrase keeps cause and effect together, which suits short chains of events.","whyCN":"在同一句内，这个短语把因果放在一起，适合短事件链。"},{"no":"03","title":"Naming the cause with a noun","titleCN":"后接介词加名词：由于","definition":"used before of and a noun to name the cause rather than the effect","definitionCN":"用在介词加名词之前，点出原因而非结果","example":"As a consequence of the drought, food prices rose.","exampleCN":"由于旱情，食品价格上涨。","why":"Adding of reverses the direction: the phrase now points back to the cause and forward to the consequence.","whyCN":"加上介词就调转方向：短语现在回指原因、前指后果。"},{"no":"04","title":"Naming the cause with a gerund","titleCN":"后接介词加动名词：由于做……","definition":"used before of and an -ing form when the cause is an activity","definitionCN":"在介词与动名词前使用，表示原因是一项活动","example":"As a consequence of cutting the budget, two services closed.","exampleCN":"由于削减预算，两项服务被关停。","why":"Because the phrase is prepositional, an activity after of must appear as a gerund, not as a bare verb.","whyCN":"由于这是介词短语，介词后的活动必须以动名词出现，不能用光秃秃的动词。"},{"no":"05","title":"The academic causal chain","titleCN":"学术写作：因果链","definition":"in research writing, used to link a finding to the effect that follows from it","definitionCN":"在学术写作中，把一项发现与随之而来的效果相连","example":"As a consequence, later studies used a much smaller sample.","exampleCN":"结果，后续研究所用的样本小得多。","why":"Academic argument needs a formal marker that a result is being drawn from evidence already presented.","whyCN":"学术论证需要一个正式标记，表明结果是从已呈现的证据推出的。"},{"no":"06","title":"The formal cousin of a plainer phrase","titleCN":"语域：比口语因果说法更正式","definition":"in formal prose it replaces the shorter phrase as a result and often carries a hint of seriousness","definitionCN":"在正式文字中替代更短的「结果是」，并常带一丝严重意味","example":"As a consequence, the scheme was abandoned.","exampleCN":"结果，这个方案被放弃了。","why":"The longer noun sounds weightier than the short phrase, which is why reports and judgments prefer it.","whyCN":"较长的名词比短说法更有分量，因此报告与判决偏爱它。"},{"no":"07","title":"The sense of an unwelcome outcome","titleCN":"负面后果：不利结果","definition":"used especially when the effect is unwelcome or damaging","definitionCN":"尤用于效果不受欢迎或带有损害时","example":"As a consequence, the firm lost two major clients.","exampleCN":"结果，这家公司失去了两个大客户。","why":"The noun itself suggests something that follows unavoidably, so the phrase often introduces loss rather than gain.","whyCN":"这个名词本身暗示不可避免的后续，因此短语常引出损失而非收益。"},{"no":"08","title":"The conclusion marker in reasoning","titleCN":"逻辑推理：结论标记","definition":"used in argument to mark a conclusion drawn from stated premises","definitionCN":"在论证中标记从已述前提出发的结论","example":"As a consequence, the two claims cannot both be true.","exampleCN":"因此，这两个主张不可能同时为真。","why":"Reasoning needs a word that separates premises from conclusion, and this phrase does that formally.","whyCN":"推理需要一个把前提与结论分开的词，这个短语正式地承担了。"}],"etymology":{"intro":{"en":"Consequence comes from Latin consequentia, from consequi, to follow after, itself con-, with, and sequi, to follow. The Latin line is clear; the English phrase is modern.","cn":"consequence 来自拉丁语 consequentia，词根 consequi 意为「跟随」，由 con-「共同」与 sequi「跟随」构成。拉丁语线索清楚，英语短语属近代。"},"items":[{"era":"LATIN SEQUI","en":"Sequi, to follow, is also the root of sequence and sequel.","cn":"sequi 意为「跟随」，也是 sequence 与 sequel 的词根。"},{"era":"LATIN CONSEQUI","en":"Consequi meant to follow closely or to result from something.","cn":"consequi 意为紧随，或由某事物导致。"},{"era":"LATIN CONSEQUENTIA","en":"The noun named what follows from a cause, and Old French consequence carried it to English.","cn":"这个名词指由原因导致的结果，古法语 consequence 把它带入英语。"},{"era":"ENGLISH CONSEQUENCE","en":"English consequence appears in the Middle English period; the date is approximate.","cn":"英语 consequence 见于中古英语，年代为约数。"},{"era":"THE MODERN PHRASE","en":"The phrase with this article and noun settles in modern formal writing.","cn":"带冠词与名词的这个短语在近代正式文字中定型。"}]},"similar":{"note":{"en":"The first group also marks a result but differs in register or direction; the second group holds adverbs and phrases of effect.","cn":"第一组同样标记结果，但语域或方向不同；第二组是表效果与结论的副词短语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"as a result","ipa":"/æz ə rɪˈzʌlt/","tag":"shorter, more neutral","definition":"It is the plainer and more common result marker.","definitionCN":"它是更朴素、更常见的结果标记。"},{"word":"because of","ipa":"/bɪˈkɒz əv/","tag":"cause, not result","definition":"It points back to a cause rather than forward to an effect.","definitionCN":"它回指原因，而非前指效果。"},{"word":"in consequence","ipa":"/ɪn kənˈsiːkwəns/","tag":"formal British variant","definition":"A British written variant with the same result sense.","definitionCN":"英式书面变体，结果义相同。"},{"word":"as a consequence of","ipa":"/æz ə kənˈsiːkwəns əv/","tag":"cause-naming form","definition":"With of it names the cause instead of the effect.","definitionCN":"加上介词后点出原因而非结果。"}]},{"heading":"NEAR MEANING","entries":[{"word":"consequently","ipa":"/ˈkɒnsɪkwəntli/","tag":"single adverb","definition":"It marks a result in one word and often opens a sentence.","definitionCN":"用一个词标记结果，常开句。"},{"word":"therefore","ipa":"/ˈðeəfɔː/","tag":"logic marker","definition":"It draws a conclusion rather than narrating an effect.","definitionCN":"它引出结论，而非叙述效果。"},{"word":"accordingly","ipa":"/əˈkɔːdɪŋli/","tag":"fitting response","definition":"It marks an action taken in response to a fact.","definitionCN":"标记针对事实采取的行动。"},{"word":"hence","ipa":"/hens/","tag":"compact formal result","definition":"A short formal word meaning for this reason.","definitionCN":"一个简短的正式词，意为「因此」。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real follow root, the real cause-and-effect pattern and the real register.","cn":"正常联想用真实「跟随」词根、真实因果结构与真实语域。"},"normal":[{"en":"To follow is the root, so a consequence is what comes after a cause.","cn":"词根是「跟随」，后果就是原因之后跟来的东西。"},{"en":"It takes of to name the cause and stands alone to name the effect.","cn":"加介词点原因，单独用则点结果。"},{"en":"The object after of may be a noun or a gerund, never a bare verb.","cn":"介词后的宾语可以是名词或动名词，不能是光秃秃的动词。"},{"en":"Reports and judgments prefer it because the noun sounds weighty.","cn":"报告与判决偏爱它，因为这个名词听起来有分量。"},{"en":"It often introduces loss, since what follows unavoidably is rarely good news.","cn":"它常引出损失，因为不可避免的后续很少是好消息。"}],"abstract":[{"en":"Like one domino tipping the next, and the next, until the line is down.","cn":"像一张骨牌推倒下一张，再下一张，直到整排倒下。"},{"en":"Like a receipt printed only after the purchase has gone wrong.","cn":"像只有购买出了问题之后才打印出来的收据。"},{"en":"Like the last line of a proof, where the conclusion finally appears.","cn":"像证明的最后一行，结论终于出现。"}]},"examples":[{"en":"As a consequence, the project was delayed by three months.","cn":"结果，项目被延误了三个月。"},{"en":"As a consequence of the flood, the bridge was closed.","cn":"由于洪水，这座桥被关闭了。"},{"en":"The company cut costs and, as a consequence, lost several clients.","cn":"公司削减成本，因而失去了几个客户。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「阿兹 额 康西昆斯」——一张骨牌推倒下一张：因此、结果","word":"as a consequence"},"root":"consequence 来自拉丁语 consequentia，词根 consequi「跟随」由 con-「共同」与 sequi「跟随」构成，经古法语进入英语；短语 as a consequence 在近代正式文字中定型，首见年代为约数。","sensesIntro":{"en":"Eight senses split by position and direction: a sentence opener, a mid-sentence link, of plus a noun, of plus a gerund, an academic chain, formal register, an unwelcome outcome, and a conclusion marker.","cn":"八个义项按位置与方向区分：句首、句中、介词加名词、介词加动名词、学术因果链、正式语域、负面后果、结论标记。"},"semanticMap":{"core":{"en":"CORE IMAGE: one domino tipping the next until the line is down.","cn":"核心意象：一张骨牌推倒下一张，直到整排倒下。"},"chain":["FOLLOW AFTER","RESULT MARKER","NAMED CAUSE","GERUND CAUSE","UNWELCOME OUTCOME","CONCLUSION"],"branches":[{"senses":"01 · 02","en":"THE EFFECT: front and mid positions introduce what follows.","cn":"效果：句首与句中引出后续。"},{"senses":"03 · 04","en":"THE CAUSE: of turns the phrase backward to a noun or an activity.","cn":"原因：介词把短语转向名词或活动。"},{"senses":"05 · 08","en":"THE CHAIN: research and logic use it to draw a conclusion from evidence.","cn":"链条：研究与逻辑用它从证据推出结论。"},{"senses":"06","en":"THE REGISTER: the longer noun carries more weight than the short phrase.","cn":"语域：较长名词比短说法更有分量。"},{"senses":"07","en":"THE LOSS: what follows unavoidably is often unwelcome.","cn":"损失：不可避免的后续常不受欢迎。"}]},"affixes":{"intro":{"en":"The phrase joins a Latin noun of following with English prepositions; the follow root is the core.","cn":"这个短语把拉丁语「跟随」名词与英语介词结合；「跟随」词根是核心。"},"latinIntro":{"en":"The Latin etyma are consequi, to follow after, and sequi, to follow.","cn":"拉丁语词源是 consequi「跟随」与 sequi「跟随」。"},"items":[{"word":"sequi","structure":"Latin verb, third conjugation, deponent","meaning":"to follow","meaningCN":"跟随","example":"The verb also gives sequence and sequel.","exampleCN":"这个动词也给出两个相关英语词。"},{"word":"consequi","structure":"con- + sequi","meaning":"to follow closely; to result","meaningCN":"紧随；导致","example":"The prefix binds the following to its source.","exampleCN":"前缀把「跟随」绑到源头。"},{"word":"consequentia","structure":"Latin noun from consequi","meaning":"what follows","meaningCN":"后续；结果","example":"The noun names the effect itself.","exampleCN":"名词直接指效果。"},{"word":"consequence","structure":"English noun through Old French","meaning":"a result; importance","meaningCN":"结果；重要性","example":"English keeps both the effect and the weight senses.","exampleCN":"英语保留「结果」与「分量」两义。"},{"word":"consequent","structure":"consequence + -ent","meaning":"following as a result","meaningCN":"随之发生的","example":"The adjective describes what follows.","exampleCN":"形容词描述随之而来的东西。"},{"word":"consequently","structure":"consequent + -ly","meaning":"as a result","meaningCN":"因此","example":"The adverb marks a result in one word.","exampleCN":"副词用一个词标记结果。"},{"word":"consequential","structure":"consequence + -ial","meaning":"important; resulting","meaningCN":"重要的；随之而来的","example":"The adjective stresses weight rather than order.","exampleCN":"这个形容词强调分量而非顺序。"},{"word":"as a consequence","structure":"preposition + article + noun","meaning":"as a result","meaningCN":"因此","example":"The phrase is the formal result marker.","exampleCN":"这个短语是正式的结果标记。"}],"latinEntries":[{"word":"sequi","structure":"sequi, sequor, secutus sum (verb, third conjugation, deponent)","meaning":"to follow","meaningCN":"跟随"},{"word":"consequi","structure":"consequi, consequor, consecutus sum (verb, deponent)","meaning":"to follow after; to result","meaningCN":"跟随；导致"}],"derivatives":[{"word":"consequence","pos":"n.","zh":"后果；结果"},{"word":"consequent","pos":"adj.","zh":"随之发生的"},{"word":"consequently","pos":"adv.","zh":"因此"},{"word":"consequential","pos":"adj.","zh":"重要的； consequential 的"},{"word":"sequel","pos":"n.","zh":"续集；后续"}]}},{"word":"as opposed to","ipa_uk":"/æz əˈpəʊzd tuː/","ipa_us":"/æz əˈpoʊzd tuː/","definition_zh":"而不是；与……相对（用于对比两类事物，强调区别）","definition_en":"rather than; used to contrast one kind of thing with another kind","core_image":"工作台上两个抽屉贴着不同标签，一边放工具，一边放零件","scene":"工作台上两个抽屉贴着不同标签，一边放工具，一边放零件。The report counts full-time staff, as opposed to temporary workers.","sceneCN":"这里取「而不是」（第 1 个义项：对比两类，强调区别）；句意为报告统计的是全职员工，而不是临时工。","pos":[{"tag":"prep. phr.","zh":"介词短语：而不是；与……相对（强调区别）"}],"collocations":[{"phrase":"as opposed to a theory","zh":"而不是理论"},{"phrase":"as opposed to simply","zh":"而不是仅仅"},{"phrase":"full-time as opposed to part-time","zh":"全职而非兼职"},{"phrase":"as opposed to the previous method","zh":"而非先前的方法"},{"phrase":"as opposed to what","zh":"而不是什么（口语追问）"},{"phrase":"as opposed to the alternative","zh":"而非替代方案"}],"forms":[{"label":"原形","form":"as opposed to"},{"label":"后接动名词","form":"as opposed to doing"},{"label":"口语追问","form":"as opposed to what"}],"derivatives":[{"word":"oppose","pos":"v.","zh":"反对；对抗"},{"word":"opposed","pos":"adj.","zh":"反对的；对立的"},{"word":"opposition","pos":"n.","zh":"反对；对立"},{"word":"opposing","pos":"adj.","zh":"对立的；相反的"},{"word":"opposite","pos":"adj./n.","zh":"相反的；对立面"}],"senses":[{"no":"01","title":"The contrast between two kinds","titleCN":"而不是（两类对比）","definition":"used to set one category against another so that the difference between kinds is clear","definitionCN":"把一类与另一类并置，使种类差别清楚","example":"The report counts full-time staff, as opposed to temporary workers.","exampleCN":"报告统计的是全职员工，而不是临时工。","why":"The phrase separates two categories rather than two individual things, which is why the nouns are usually plural or generic.","whyCN":"这个短语分开的是两个类别而非两个个体，因此名词常为复数或统称。"},{"no":"02","title":"The preferred alternative","titleCN":"而不是（取舍对比）","definition":"used to say that one option is chosen and the other is not","definitionCN":"表示选定了某一选项，另一项未被选","example":"The committee chose the smaller site, as opposed to the cheaper one.","exampleCN":"委员会选了较小的地块，而不是较便宜的那块。","why":"Here the contrast carries a decision: the first item is preferred, and the second is explicitly set aside.","whyCN":"此处的对比带有决定：第一项被选中，第二项被明确搁置。"},{"no":"03","title":"The static comparison after a noun","titleCN":"后接名词：静态对比","definition":"used immediately after a noun phrase to name the contrasting kind","definitionCN":"紧跟在名词短语之后，点出对照的另一类","example":"The study uses interviews, as opposed to questionnaires.","exampleCN":"这项研究使用访谈，而不是问卷。","why":"Static comparison does not describe an action; it fixes the identity of two kinds side by side.","whyCN":"静态对比不描述动作，而是把两类事物的身份并排固定。"},{"no":"04","title":"The comparison of activities","titleCN":"后接动名词：对比两种做法","definition":"used before an -ing form when two activities are being contrasted","definitionCN":"对比两项活动时，用在动名词之前","example":"The team favoured testing early, as opposed to waiting for the deadline.","exampleCN":"团队倾向于尽早测试，而不是等到截止日期。","why":"Because the phrase is prepositional, an activity must be a gerund, not a bare verb or a clause.","whyCN":"由于这是介词短语，活动必须用动名词，不能用光秃秃的动词或从句。"},{"no":"05","title":"The clarification rather than replacement","titleCN":"澄清而非替换：与「代替」类说法分工","definition":"it clarifies which kind is meant instead of announcing that one thing replaces another","definitionCN":"它澄清指的是哪一类，而不是宣布一物替代另一物","example":"The rule concerns employees, as opposed to contractors.","exampleCN":"这条规则针对雇员，而不是承包商。","why":"Nothing is being swapped here; the phrase is defining the scope of a word, which is the boundary against replacement phrases.","whyCN":"这里没有东西被替换；短语是在界定一个词的范围，这就是与「代替」类说法的边界。"},{"no":"06","title":"The mid-clause or trailing aside","titleCN":"句中或句末插入：补出对照项","definition":"inserted after a comma to add the contrasting kind without breaking the main clause","definitionCN":"用逗号插入，补出对照类别而不打断主句","example":"The figures cover last year, as opposed to the year before.","exampleCN":"这些数字涵盖去年，而不是前年。","why":"The aside keeps the main claim intact and attaches the excluded kind at the edge.","whyCN":"旁白保持主要断言完整，把被排除的类别挂在边上。"},{"no":"07","title":"Defining terms in academic writing","titleCN":"学术写作：界定术语","definition":"in academic prose, used to define a term by excluding the neighbouring category","definitionCN":"在学术文字中，通过排除相邻类别来界定一个术语","example":"The model measures adaptation, as opposed to adjustment.","exampleCN":"这个模型衡量的是适应，而不是调整。","why":"Research often defines by contrast, and the phrase marks the excluded neighbour that gives the term its edge.","whyCN":"研究常靠对比来定义，这个短语标出被排除的邻项，术语因此有了边界。"},{"no":"08","title":"The legal and technical classification","titleCN":"法律与技术分类：相对而言","definition":"in legal or technical texts, used to separate two categories that carry different rules","definitionCN":"在法律或技术文本中，分开适用不同规则的两个类别","example":"The clause applies to fixed assets, as opposed to current assets.","exampleCN":"该条款适用于固定资产，而不是流动资产。","why":"Classification needs a phrase that keeps two categories apart without suggesting that one is better.","whyCN":"分类需要一个把两类分开、又不暗示优劣的说法。"}],"etymology":{"intro":{"en":"Oppose comes from Latin opponere, to set against, itself ob-, against, and ponere, to place. The Latin line is clear; the English phrase is modern.","cn":"oppose 来自拉丁语 opponere「置于对面」，由 ob-「对着」与 ponere「放置」构成。拉丁语线索清楚，英语短语属近代。"},"items":[{"era":"LATIN PONERE","en":"Ponere, to place, is also the root of position and impose.","cn":"ponere 意为「放置」，也是 position 与 impose 的词根。"},{"era":"LATIN OPPONERE","en":"Opponere meant to place something in front of another as a counterweight.","cn":"opponere 意为把某物放到另一物前面作为对抗。"},{"era":"ENGLISH OPPOSE","en":"English oppose appears in the Middle English period with the sense of resisting.","cn":"英语 oppose 见于中古英语，意为抵抗。"},{"era":"THE PARTICIPLE","en":"The past participle opposed supplies the fixed frame as opposed to.","cn":"过去分词 opposed 提供「as opposed to」这一固定框架。"},{"era":"MODERN USE","en":"The construction spreads in modern analytical writing; the exact date is approximate.","cn":"这一结构在近代分析性文字中传播，确切年代为约数。"}]},"similar":{"note":{"en":"The first group also contrasts two things but differs in grammar or in what is being replaced; the second group holds conjunctions and prepositions of preference.","cn":"第一组同样对比两物，但语法或替代关系不同；第二组是表取舍的连词与介词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"instead of","ipa":"/ɪnˈsted əv/","tag":"replacement, not definition","definition":"It says one thing takes the place of another, often in an action.","definitionCN":"它指一物取代另一物，常用于动作。"},{"word":"rather than","ipa":"/ˈrɑːðə ðæn/","tag":"preference, often verbal","definition":"It expresses preference between options and fits verbs as well as nouns.","definitionCN":"它表达选项间的偏好，名词动词皆可。"},{"word":"in contrast to","ipa":"/ɪn ˈkɒntrɑːst tuː/","tag":"difference, not category","definition":"It stresses divergence between two facts rather than two categories.","definitionCN":"它强调两件事实的分歧，而非两个类别。"},{"word":"as distinct from","ipa":"/æz dɪˈstɪŋkt frɒm/","tag":"formal separation","definition":"A formal phrase that stresses separateness of categories.","definitionCN":"正式短语，强调类别的分离。"}]},{"heading":"NEAR MEANING","entries":[{"word":"unlike","ipa":"/ʌnˈlaɪk/","tag":"preposition of difference","definition":"It opens a comparison by naming what the subject is not like.","definitionCN":"通过点出主语不像什么来开启比较。"},{"word":"not","ipa":"/nɒt/","tag":"plain negation","definition":"It simply denies and carries no category contrast.","definitionCN":"它只作否定，不含类别对照。"},{"word":"rather","ipa":"/ˈrɑːðə/","tag":"preference adverb","definition":"It marks a preferred alternative in a lighter tone.","definitionCN":"以较轻的语气标出更偏好的选项。"},{"word":"by comparison","ipa":"/baɪ kəmˈpærɪsn/","tag":"measured difference","definition":"It weighs two things without defining either.","definitionCN":"它衡量两物，不界定任何一方。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real placing root, the real category contrast and the real boundary.","cn":"正常联想用真实「放置」词根、真实类别对比与真实边界。"},"normal":[{"en":"To oppose is to place one thing against another, so the phrase sets two kinds face to face.","cn":"词根意为把一物放到另一物对面，所以短语把两类事物面对面摆开。"},{"en":"It separates categories, not single objects.","cn":"它分开的是类别，不是单个物体。"},{"en":"It takes a noun or a gerund, never a clause.","cn":"它接名词或动名词，从不接从句。"},{"en":"It clarifies scope; it does not announce a replacement.","cn":"它澄清范围，不宣布替代。"},{"en":"In research it defines a term by excluding its neighbour.","cn":"在研究中，它靠排除邻项来定义术语。"}],"abstract":[{"en":"Like two drawers labelled differently, each holding a separate kind of thing.","cn":"像两个贴着不同标签的抽屉，各装一类东西。"},{"en":"Like a line drawn between two columns of a table before any counting begins.","cn":"像计数开始前，在表格两栏之间画的一道线。"},{"en":"Like a sign that says this path, not that one, without saying the other is worse.","cn":"像一块牌子写着走这条、不走那条，却不说另一条更差。"}]},"examples":[{"en":"The course is assessed by coursework, as opposed to a final examination.","cn":"这门课以平时作业评定，而不是期末考试。"},{"en":"The clause covers permanent staff, as opposed to seasonal workers.","cn":"该条款涵盖正式员工，而不是季节工。"},{"en":"They chose to renovate, as opposed to building anew.","cn":"他们选择了翻修，而不是新建。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「阿兹 额波兹德 图」——两个抽屉贴不同标签，各装一类：而不是","word":"as opposed to"},"root":"oppose 来自拉丁语 opponere「置于对面」，由 ob-「对着」与 ponere「放置」构成；结构 as opposed to 在近代分析性文字中传播，首见年代为约数。","sensesIntro":{"en":"Eight senses split by grammar and purpose: two categories, a preferred option, a noun contrast, a gerund contrast, clarification rather than replacement, a mid-clause aside, academic definition, and legal classification.","cn":"八个义项按语法与用途区分：两类对比、取舍、名词对比、动名词对比、澄清而非替代、句中旁白、学术界定、法律分类。"},"semanticMap":{"core":{"en":"CORE IMAGE: two drawers labelled differently, each holding a separate kind of thing.","cn":"核心意象：两个贴着不同标签的抽屉，各装一类东西。"},"chain":["SET AGAINST","TWO CATEGORIES","PREFERRED OPTION","NOUN CONTRAST","GERUND CONTRAST","CLASSIFICATION"],"branches":[{"senses":"01 · 03 · 08","en":"THE CATEGORY: two kinds are separated, often in legal or technical texts.","cn":"类别：分开两类，常见于法律或技术文本。"},{"senses":"02","en":"THE CHOICE: one option is taken and the other set aside.","cn":"取舍：选定一项，搁置另一项。"},{"senses":"04","en":"THE ACTIVITY: two practices are contrasted through gerunds.","cn":"活动：通过动名词对比两种做法。"},{"senses":"05 · 07","en":"THE DEFINITION: scope is clarified by excluding the neighbouring term.","cn":"定义：靠排除邻项来澄清范围。"},{"senses":"06","en":"THE ASIDE: the excluded kind is attached at the edge of the clause.","cn":"旁白：被排除的类别挂在从句边上。"}]},"affixes":{"intro":{"en":"The phrase joins a Latin participle of placing against with English prepositions; the placing root is the core.","cn":"这个短语把拉丁语「置于对面」的分词与英语介词结合；「放置」词根是核心。"},"latinIntro":{"en":"The Latin etyma are opponere, to set against, and ponere, to place.","cn":"拉丁语词源是 opponere「置于对面」与 ponere「放置」。"},"items":[{"word":"ponere","structure":"Latin verb, third conjugation","meaning":"to place; to put","meaningCN":"放置","example":"The verb also gives position and impose.","exampleCN":"这个动词也给出两个相关英语词。"},{"word":"opponere","structure":"ob- + ponere","meaning":"to place against","meaningCN":"置于对面","example":"The prefix turns placing into opposition.","exampleCN":"前缀把「放置」变成「对抗」。"},{"word":"oppose","structure":"English verb from Old French","meaning":"to resist; to set against","meaningCN":"反对；对抗","example":"English keeps the resisting sense.","exampleCN":"英语保留「抵抗」义。"},{"word":"opposed","structure":"oppose + -ed","meaning":"set against; hostile","meaningCN":"对立的；反对的","example":"The participle supplies the fixed frame.","exampleCN":"分词提供固定框架。"},{"word":"opposition","structure":"oppose + -ition","meaning":"resistance; a contrast","meaningCN":"反对；对立","example":"The noun names the state of standing against.","exampleCN":"名词指对立状态。"},{"word":"opposing","structure":"oppose + -ing","meaning":"acting against","meaningCN":"对立的","example":"The participle describes one side of a contest.","exampleCN":"分词描述竞争的一方。"},{"word":"opposite","structure":"opponere through French","meaning":"facing; contrary","meaningCN":"对面的；相反的","example":"The word names what lies across from something.","exampleCN":"这个词指位于对面之物。"},{"word":"as opposed to","structure":"fixed contrast frame","meaning":"rather than","meaningCN":"而不是","example":"The frame separates categories in formal prose.","exampleCN":"这个框架在正式文字中分开类别。"}],"latinEntries":[{"word":"ponere","structure":"ponere, pono, posui, positum (verb, third conjugation)","meaning":"to place","meaningCN":"放置"},{"word":"opponere","structure":"opponere, oppono, opposui, oppositum (verb, third conjugation)","meaning":"to set against","meaningCN":"置于对面"}],"derivatives":[{"word":"oppose","pos":"v.","zh":"反对；对抗"},{"word":"opposed","pos":"adj.","zh":"反对的；对立的"},{"word":"opposition","pos":"n.","zh":"反对；对立"},{"word":"opposing","pos":"adj.","zh":"对立的；相反的"},{"word":"opposite","pos":"adj./n.","zh":"相反的；对立面"}]}},{"word":"in spite of","ipa_uk":"/ɪn ˈspaɪt əv/","ipa_us":"/ɪn ˈspaɪt əv/","definition_zh":"尽管；不顾（后接名词或动名词，不直接接从句）","definition_en":"despite; used before a noun or gerund to concede an obstacle that did not stop something","core_image":"一个人顶着逆风把推车推上斜坡，车轮仍向前","scene":"风力很大，送货员仍把推车推上斜坡。The delivery went ahead in spite of the strong wind.","sceneCN":"这里取「尽管」（第 1 个义项：后接名词，承认阻碍但结果未变）；句意为尽管风大，送货仍照常进行。","pos":[{"tag":"prep. phr.","zh":"介词短语：尽管、不顾（后接名词或动名词）"}],"collocations":[{"phrase":"in spite of the rain","zh":"尽管下雨"},{"phrase":"in spite of the cost","zh":"尽管成本高"},{"phrase":"in spite of everything","zh":"尽管如此种种"},{"phrase":"in spite of the fact that","zh":"尽管事实是"},{"phrase":"in spite of oneself","zh":"不由自主地"},{"phrase":"in spite of repeated warnings","zh":"尽管反复警告"}],"forms":[{"label":"原形","form":"in spite of"},{"label":"动名词搭配","form":"in spite of doing"},{"label":"事实从句","form":"in spite of the fact that"},{"label":"固定说法","form":"in spite of oneself"}],"derivatives":[{"word":"spite","pos":"n.","zh":"恶意；怨气"},{"word":"spiteful","pos":"adj.","zh":"怀有恶意的"},{"word":"despite","pos":"prep.","zh":"尽管"},{"word":"despite of","pos":"prep. phr.","zh":"尽管（非标准）"},{"word":"in spite of","pos":"prep. phr.","zh":"尽管（标准）"}],"senses":[{"no":"01","title":"Conceding an obstacle named by a noun","titleCN":"尽管（后接名词）","definition":"used before a noun to admit that an obstacle existed while saying the result was unchanged","definitionCN":"用在名词前，承认阻碍存在，同时说明结果未变","example":"The delivery went ahead in spite of the strong wind.","exampleCN":"尽管风很大，送货仍照常进行。","why":"The phrase admits the obstacle first and denies its effect second, which is the opposite order from a cause phrase.","whyCN":"这个短语先承认阻碍，再否认其效果，与因果短语的顺序正好相反。"},{"no":"02","title":"Conceding an activity","titleCN":"尽管（后接动名词）","definition":"used before an -ing form when the obstacle is an activity or a process","definitionCN":"当阻碍是活动或过程时，用在动名词之前","example":"She finished the report in spite of feeling unwell.","exampleCN":"尽管身体不适，她还是完成了报告。","why":"A prepositional phrase cannot take a bare verb, so the activity appears as a gerund.","whyCN":"介词短语不能接光秃秃的动词，所以活动以动名词出现。"},{"no":"03","title":"Conceding a full statement","titleCN":"尽管事实是：后接事实从句","definition":"used before the fact that when the obstacle is a whole statement","definitionCN":"当阻碍是完整命题时，用在「事实是」之前","example":"The plan succeeded in spite of the fact that funding was cut.","exampleCN":"尽管经费被削减，计划还是成功了。","why":"The fact that frame is the standard route to a clause after this prepositional phrase.","whyCN":"「事实是」框架是这一介词短语后接从句的标准通道。"},{"no":"04","title":"The front-position concession","titleCN":"句首让步：尽管……仍……","definition":"placed at the start of a sentence to set up the concession before the main claim","definitionCN":"置于句首，在主句之前先摆出让步","example":"In spite of the delay, the goods arrived intact.","exampleCN":"尽管延误，货物完好送达。","why":"Fronting the concession makes the main clause read as a triumph over the obstacle.","whyCN":"把让步前置，主句便读作对阻碍的胜利。"},{"no":"05","title":"The trailing concession","titleCN":"句末：仍然……","definition":"placed after the main clause to add the obstacle as an afterthought","definitionCN":"放在主句之后，把阻碍作为补充","example":"The team finished on time, in spite of every setback.","exampleCN":"团队按时完成，尽管遭遇了种种挫折。","why":"Trailing position keeps the achievement first and lets the obstacle follow as a qualification.","whyCN":"后置把成绩放在前面，让阻碍随后作为限定。"},{"no":"06","title":"The boundary against a shorter synonym","titleCN":"与更短同义介词的边界","definition":"it carries the same meaning as a shorter synonym but is slightly heavier and more conversational","definitionCN":"它与更短的同义介词意义相同，但语气略重、更口语","example":"In spite of the cost, the plan was approved.","exampleCN":"尽管成本高，计划仍获批准。","why":"The shorter synonym is more formal and cannot take the fact frame as naturally, so the choice is a matter of weight and idiom.","whyCN":"更短的同义词更正式，接事实框架也不如它自然，因此选择取决于分量与习惯。"},{"no":"07","title":"The fixed phrase of involuntary action","titleCN":"固定说法：不由自主地","definition":"in the fixed pattern in spite of oneself, used when a reaction happens against one's will","definitionCN":"在固定说法「不由自主」中，表示反应违背本人意愿而发生","example":"She laughed in spite of herself.","exampleCN":"她不由自主地笑了。","why":"Here spite turns inward: the person's own will is the obstacle that the reaction overrides.","whyCN":"此处「恶意」转向自身：本人的意愿成了被反应压过的阻碍。"},{"no":"08","title":"The grammatical boundary against a conjunction","titleCN":"语法边界：不能直接接从句","definition":"unlike a concessive conjunction, it cannot be followed directly by a clause","definitionCN":"与让步连词不同，它后面不能直接跟从句","example":"In spite of the rain, the match continued.","exampleCN":"尽管下雨，比赛仍继续。","why":"This is the grammar that separates it from although: a preposition needs a noun, while a conjunction takes a clause.","whyCN":"这正是它与让步连词的分界：介词要名词，连词接从句。"}],"etymology":{"intro":{"en":"Spite comes from Middle English despite, from Old French despit, from Latin despicere, to look down on, itself de-, down, and specere, to look. The Latin line is clear; the phrase is modern.","cn":"spite 来自中古英语 despite，经古法语 despit，出自拉丁语 despicere「俯视、轻视」，由 de-「向下」与 specere「看」构成。拉丁语线索清楚，短语属近代。"},"items":[{"era":"LATIN SPECERE","en":"Specere, to look, is also the root of spectacle and specimen.","cn":"specere 意为「看」，也是 spectacle 与 specimen 的词根。"},{"era":"LATIN DESPICERE","en":"Despicere meant to look down on, hence to scorn.","cn":"despicere 意为俯视，由此引申为轻视。"},{"era":"OLD FRENCH DESPIT","en":"Old French despit meant contempt or vexation, and English took it as despite.","cn":"古法语 despit 意为轻蔑或恼怒，英语借入作 despite。"},{"era":"SPITE AND DESPITE","en":"English kept despite as a preposition of concession and spite as a noun of malice.","cn":"英语保留 despite 作让步介词，spite 作表恶意的名词。"},{"era":"THE MODERN PHRASE","en":"The phrase with this noun and preposition settles in modern English; dates are approximate.","cn":"带这个名词与介词的短语在近代英语中定型，年代为约数。"}]},"similar":{"note":{"en":"The first group also concedes an obstacle but differs in grammar or in the direction of the concession; the second group holds conjunctions and adverbs of concession.","cn":"第一组同样承认阻碍，但语法或让步方向不同；第二组是表让步的连词与副词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"despite","ipa":"/dɪˈspaɪt/","tag":"shorter, more formal","definition":"It is the shorter synonym and is commoner in formal writing.","definitionCN":"它是更短的同义词，在正式文字中更常见。"},{"word":"notwithstanding","ipa":"/ˌnɒtwɪθˈstændɪŋ/","tag":"heavy legal concession","definition":"A formal legal preposition meaning in spite of.","definitionCN":"正式法律介词，意为尽管。"},{"word":"regardless of","ipa":"/rɪˈɡɑːdləs əv/","tag":"dismisses the factor","definition":"It denies that the factor matters at all, while this phrase admits it exists.","definitionCN":"它否认因素有任何分量，而本短语承认其存在。"},{"word":"for all","ipa":"/fɔːr ɔːl/","tag":"concessive with a sting","definition":"It concedes a fact and often hints that the concession is grudging.","definitionCN":"承认事实，常暗示让步并不情愿。"}]},{"heading":"NEAR MEANING","entries":[{"word":"although","ipa":"/ɔːlˈðəʊ/","tag":"conjunction of concession","definition":"It takes a full clause, which a preposition cannot do.","definitionCN":"它接完整从句，介词做不到。"},{"word":"even so","ipa":"/ˈiːvn səʊ/","tag":"conversational concession","definition":"It concedes the previous point in speech.","definitionCN":"在口语中承认上一点。"},{"word":"nevertheless","ipa":"/ˌnevəˈðeles/","tag":"formal connector","definition":"It marks the main clause as surviving a stated obstacle.","definitionCN":"标记主句在所述阻碍下仍成立。"},{"word":"even if","ipa":"/ˈiːvn ɪf/","tag":"hypothetical concession","definition":"It concedes a possible condition rather than an existing fact.","definitionCN":"它承认可能条件，而非既存事实。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real looking-down root, the real concession grammar and the real fixed phrase.","cn":"正常联想用真实「俯视」词根、真实让步语法与真实固定说法。"},"normal":[{"en":"The root is looking down on something, so the phrase began as a picture of scorn overcome.","cn":"词根是俯视某物，所以短语最初是「轻蔑被克服」的画面。"},{"en":"It takes a noun or a gerund, never a clause.","cn":"它接名词或动名词，从不接从句。"},{"en":"A full statement needs the fact that frame.","cn":"完整命题需要「事实是」框架。"},{"en":"At the front it sets up a triumph; at the end it adds a qualification.","cn":"放句首搭起胜利，放句末补上限定。"},{"en":"In spite of oneself turns the scorn inward, against one's own will.","cn":"「不由自主」把轻蔑转向内部，违背本人意愿。"}],"abstract":[{"en":"Like a cart pushed up a slope against a strong headwind, still reaching the top.","cn":"像推车顶着强逆风上坡，仍然到达坡顶。"},{"en":"Like a letter delivered in the rain with the ink still dry.","cn":"像雨中送到的信，字迹仍然干燥。"},{"en":"Like a laugh that escapes before the person decides to laugh.","cn":"像笑意在人决定之前就先跑出来。"}]},"examples":[{"en":"The match continued in spite of the rain.","cn":"尽管下雨，比赛仍继续。"},{"en":"In spite of the cost, the committee approved the plan.","cn":"尽管成本高，委员会仍批准了计划。"},{"en":"She finished the work in spite of feeling ill.","cn":"尽管身体不适，她还是完成了工作。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「因 斯派特 奥夫」——顶着逆风仍把车推上坡：尽管","word":"in spite of"},"root":"spite 来自中古英语 despite，经古法语 despit，出自拉丁语 despicere「俯视、轻视」，由 de-「向下」与 specere「看」构成；短语 in spite of 在近代英语中定型，首见年代为约数。","sensesIntro":{"en":"Eight senses split by complement and position: a noun, a gerund, a fact clause, front and trailing concessions, the boundary against a shorter synonym, the fixed phrase of involuntary action, and the grammar boundary against a conjunction.","cn":"八个义项按搭配与位置区分：名词、动名词、事实从句、句首与句末让步、与更短同义词的边界、「不由自主」固定说法、与连词的语法边界。"},"semanticMap":{"core":{"en":"CORE IMAGE: a cart pushed up a slope against a strong headwind, still reaching the top.","cn":"核心意象：推车顶着强逆风上坡，仍然到达坡顶。"},"chain":["LOOK DOWN ON","CONCEDED OBSTACLE","GERUND","FACT CLAUSE","FRONT CONCESSION","INVOLUNTARY"],"branches":[{"senses":"01 · 02","en":"THE OBSTACLE: a noun or an activity is admitted before the result is asserted.","cn":"阻碍：先承认名词或活动，再断言结果。"},{"senses":"03","en":"THE STATEMENT: a full clause needs the fact frame.","cn":"命题：完整从句需要事实框架。"},{"senses":"04 · 05","en":"THE POSITION: fronting sets up a triumph, trailing adds a qualification.","cn":"位置：前置搭起胜利，后置补上限定。"},{"senses":"06","en":"THE WEIGHT: the longer phrase is heavier and more conversational than its synonym.","cn":"分量：较长短语比同义词更重、更口语。"},{"senses":"07 · 08","en":"THE INWARD AND THE GRAMMAR: involuntary action turns scorn inward, and the phrase takes no clause directly.","cn":"向内与语法：不由自主把轻蔑转向内部，且短语不直接接从句。"}]},"affixes":{"intro":{"en":"The phrase joins a Latin noun of scorn with English prepositions; the looking-down root is the core.","cn":"这个短语把拉丁语「轻蔑」名词与英语介词结合；「俯视」词根是核心。"},"latinIntro":{"en":"The Latin etyma are despicere, to look down on, and specere, to look.","cn":"拉丁语词源是 despicere「俯视」与 specere「看」。"},"items":[{"word":"specere","structure":"Latin verb","meaning":"to look","meaningCN":"看","example":"The root runs through the spect- family.","exampleCN":"这个词根贯穿「看」的词族。"},{"word":"despicere","structure":"de- + specere","meaning":"to look down on; to scorn","meaningCN":"俯视；轻视","example":"The prefix turns looking into looking down.","exampleCN":"前缀把「看」变成「俯视」。"},{"word":"despit","structure":"Old French noun from despicere","meaning":"contempt; vexation","meaningCN":"轻蔑；恼怒","example":"French passed the word to Middle English.","exampleCN":"法语把这个词传给中古英语。"},{"word":"despite","structure":"English preposition from the noun","meaning":"in spite of","meaningCN":"尽管","example":"The preposition keeps the concessive sense.","exampleCN":"介词保留让步义。"},{"word":"spite","structure":"English noun from the same source","meaning":"malice; petty resentment","meaningCN":"恶意；怨气","example":"The noun split off with the malice sense.","exampleCN":"名词分出「恶意」义。"},{"word":"spiteful","structure":"spite + -ful","meaning":"full of malice","meaningCN":"怀有恶意的","example":"The suffix marks the malice sense.","exampleCN":"后缀标出恶意义。"},{"word":"in spite of","structure":"preposition + noun + preposition","meaning":"despite","meaningCN":"尽管","example":"The phrase is the standard concessive form.","exampleCN":"这个短语是标准让步形式。"},{"word":"in spite of oneself","structure":"fixed reflexive phrase","meaning":"against one's own will","meaningCN":"不由自主地","example":"The reflexive turns the concession inward.","exampleCN":"反身形式把让步转向内部。"}],"latinEntries":[{"word":"despicere","structure":"despicere, despicio, despexi, despectum (verb, third conjugation)","meaning":"to look down on","meaningCN":"俯视；轻视"},{"word":"specere","structure":"specere, specio, spexi, spectum (verb)","meaning":"to look","meaningCN":"看"}],"derivatives":[{"word":"spite","pos":"n.","zh":"恶意；怨气"},{"word":"spiteful","pos":"adj.","zh":"怀有恶意的"},{"word":"despite","pos":"prep.","zh":"尽管"},{"word":"despite of","pos":"prep. phr.","zh":"尽管（非标准）"},{"word":"in spite of","pos":"prep. phr.","zh":"尽管（标准）"}]}}]);
